local GTA_ROLE_BY_ID, GTA_ROLE_ORDER = {}, {}
for i, r in ipairs(_G.GTA_ROLE_DEFS) do GTA_ROLE_BY_ID[r.id] = r; GTA_ROLE_ORDER[r.id] = i end

local function GTA_Http(url)
    local body
    pcall(function() body = game:HttpGet(url .. OBF("\153\206\151") .. math.floor(os.time())) end)
    if not body or body == "" then
        pcall(function()
            local req = request or http_request or (syn and syn.request)
            local r = req and req({Url = url, Method = OBF("\161\159\174")})
            body = r and r.Body
        end)
    end
    return (type(body) == OBF("\205\206\204\195\200\193") and body ~= "") and body or nil
end




local function GTA_ParseRoles(body)
    local out = {}
    if type(body) ~= OBF("\205\206\204\195\200\193") then return out end
    for line in body:gmatch(OBF("\181\184\103\100\183\133")) do
        if not line:match(OBF("\184\127\205\132\125")) then
            local n, rest = line:match(OBF("\184\127\205\132\130\181\127\209\185\183\133\131\127\205\132\181\148\127\205\127\181\183\153\127\205\132\130\136\135\131\127\205\132\126"))
            if n and rest and rest ~= "" then
                local tags = {}
                for tag in rest:gmatch(OBF("\127\187\181\127\187\127\190\183\132")) do
                    tag = tag:upper()
                    if tag == OBF("\158\176") then tag = OBF("\158\159\176") end  
                    if GTA_ROLE_BY_ID[tag] then tags[tag] = true end
                end
                if next(tags) then out[n:lower()] = tags end
            end
        end
    end
    return out
end
_G.GTA_ParseRoles = GTA_ParseRoles

function _G.GTA_MergeLocalRoles(roles)
    for k, list in pairs(_G.GTA_LOCAL_ROLES or {}) do
        k = tostring(k):lower()
        roles[k] = roles[k] or {}
        for _, tag in ipairs(list) do
            tag = tostring(tag):upper()
            if GTA_ROLE_BY_ID[tag] then roles[k][tag] = true end
        end
    end
    return roles
end

local function GTA_ParseBlacklist(body)
    local out = {}
    if type(body) ~= OBF("\205\206\204\195\200\193") then return out end
    for line in body:gmatch(OBF("\181\184\103\100\183\133")) do
        if not line:match(OBF("\184\127\205\132\125")) then
            local k = line:match(OBF("\184\127\205\132\130\181\184\214\183\133\131"))
            if k then k = k:gsub(OBF("\127\205\133\126"), ""):lower(); if k ~= "" then out[k] = true end end
        end
    end
    return out
end

