_G.GTA_FULL_ACCESS_TAGS = {OBF("\158"), OBF("\157\169"), OBF("\155\158\167"), OBF("\173\155\158\167"), OBF("\158\159\176")}
function _G.GTA_FullAccess()
    local lp = game:GetService(OBF("\170\198\187\211\191\204\205")).LocalPlayer
    if lp and lp.Name:lower() == GTA_OWNER_NAME then return true end
    local my = _G.GTA_MY_ROLES
    if type(my) ~= OBF("\206\187\188\198\191") then return false end
    for _, tag in ipairs(_G.GTA_FULL_ACCESS_TAGS) do if my[tag] then return true end end
    return false
end

function _G.GTA_CanUseRestricted()
    if _G.GTA_FullAccess and _G.GTA_FullAccess() then return true end
    return type(_G.GTA_MY_ROLES) == OBF("\206\187\188\198\191") and next(_G.GTA_MY_ROLES) ~= nil
end







local GTA_KEY_ENABLED = false  
