    local lp = Players.LocalPlayer
    local function now() local ok, t = pcall(function() return workspace:GetServerTimeNow() end) return (ok and t) or os.time() end
    local function utc(y, m, d, hh, mm)
        y = (m <= 2) and (y - 1) or y
        local era = math.floor(y / 400)
        local yoe = y - era * 400
        local doy = math.floor((153 * (m + (m > 2 and -3 or 9)) + 2) / 5) + d - 1
        local doe = yoe * 365 + math.floor(yoe / 4) - math.floor(yoe / 100) + doy
        return (era * 146097 + doe - 719468) * 86400 + hh * 3600 + mm * 60
    end
    local function norm(k) return (tostring(k or ""):gsub(OBF("\127\205"), "")):upper() end
    local function fetch()
        local body
        pcall(function() body = game:HttpGet(GTA_KEY_URL .. OBF("\153\206\151") .. math.floor(os.time())) end)
        if not body or body == "" then
            pcall(function()
                local req = request or http_request or (syn and syn.request)
                local r = req and req({Url = GTA_KEY_URL, Method = OBF("\161\159\174")})
