                if y then exp = utc(tonumber(y), tonumber(mo), tonumber(d), tonumber(hh), tonumber(mi))
                else local n = tonumber((tostring(e):gsub(OBF("\127\205"), ""))); if n and n > 1e9 then exp = n end end
                list[norm(k)] = {exp = exp, uid = tonumber((tostring(u):gsub(OBF("\127\205"), ""))) or 0}
            end
        end
        return list
    end
    local function check(list, key)  
        local e = list[norm(key)]
        if not e then return false, OBF("\197\191\211\122\195\200\208\29\251\198\195\190\187\122\201\207\122\196\29\251\122\206\204\201\189\187\190\187") end
