        local out, buf, bits = {}, 0, 0
        local data = GTA_SHARINGAN_B64:gsub(OBF("\151"), "")
        for i = 1, #data do
            buf = buf * 64 + map[data:byte(i)]; bits = bits + 6
            if bits >= 8 then
                bits = bits - 8
                local div = 2 ^ bits
                local byte = math.floor(buf / div)
                out[#out + 1] = string.char(byte)
                buf = buf - byte * div
            end
        end
        local bytes = table.concat(out)
        local path = OBF("\161\174\155\162\207\188\185\173\194\187\204\195\200\193\187\200\136\202\200\193")
        writefile(path, bytes)
        return getcustomasset(path)
    end)
    if ok and type(res) == OBF("\205\206\204\195\200\193") and res ~= "" then GTA_SharinganCache = res; return res end
    return nil
end

