        local f = Instance.new(OBF("\160\204\187\199\191")); f.BackgroundColor3 = col; f.BorderSizePixel = 0
        f.Size = UDim2.new(sx, 0, sx, 0); f.AnchorPoint = Vector2.new(0.5, 0.5); f.Position = UDim2.new(px, 0, py, 0)
        Instance.new(OBF("\175\163\157\201\204\200\191\204"), f).CornerRadius = UDim.new(1, 0); f.Parent = par; return f
    end
    local BLACK, RED, DEEP = Color3.fromRGB(8, 8, 8), Color3.fromRGB(205, 12, 20), Color3.fromRGB(120, 0, 8)
    
    dot(drawn, 1.0, 0.5, 0.5, BLACK)
    do
        local RW, RH = 384, 192
        for block in GTA_SHARINGAN_MOSAIC:gmatch(OBF("\181\184\149\183\133")) do
            local y0, y1, rest = block:match(OBF("\184\130\127\190\133\131\134\130\127\190\133\131\148\130\136\132\131\126"))
            if y0 then
                y0, y1 = tonumber(y0), tonumber(y1)
                local nums = {}
                for n in rest:gmatch(OBF("\127\190\133")) do nums[#nums + 1] = tonumber(n) end
                for k = 1, #nums - 1, 2 do
                    local f = Instance.new(OBF("\160\204\187\199\191"))
                    f.BackgroundColor3 = Color3.fromRGB(224, 0, 0); f.BorderSizePixel = 0
                    f.Position = UDim2.new(nums[k] / RW, 0, y0 / RH, 0)
                    f.Size = UDim2.new((nums[k + 1] - nums[k]) / RW, 0, (y1 - y0 + 0.35) / RH, 0)
                    f.Parent = drawn
                end
            end
        end
    end
    
    local img = Instance.new(OBF("\163\199\187\193\191\166\187\188\191\198"))
    img.BackgroundTransparency = 1; img.Size = UDim2.new(1, 0, 1, 0); img.ScaleType = Enum.ScaleType.Fit
    img.Visible = false; img.ImageTransparency = 0; img.Parent = box
    task.spawn(function()
        local id = tostring(GTA_SHARINGAN_IMAGE):match(OBF("\127\190\133")) or OBF("\138")
        local cands = {}
        do local emb = GTA_GetSharinganAsset(); if emb then cands[1] = emb end end
        pcall(function()
            local objs = game:GetObjects(OBF("\204\188\210\187\205\205\191\206\195\190\148\137\137") .. id)
            for _, o in ipairs(objs) do
                if o:IsA(OBF("\158\191\189\187\198")) or o:IsA(OBF("\174\191\210\206\207\204\191")) then cands[#cands + 1] = o.Texture
                elseif o:IsA(OBF("\163\199\187\193\191\166\187\188\191\198")) or o:IsA(OBF("\163\199\187\193\191\156\207\206\206\201\200")) then cands[#cands + 1] = o.Image
                else for _, d in ipairs(o:GetDescendants()) do
                    if d:IsA(OBF("\158\191\189\187\198")) or d:IsA(OBF("\174\191\210\206\207\204\191")) then cands[#cands + 1] = d.Texture; break end
                end end
            end
        end)
        cands[#cands + 1] = OBF("\204\188\210\187\205\205\191\206\195\190\148\137\137") .. id
        cands[#cands + 1] = OBF("\204\188\210\206\194\207\199\188\148\137\137\206\211\202\191\151\155\205\205\191\206\128\195\190\151") .. id .. OBF("\128\209\151\142\140\138\128\194\151\142\140\138")
        cands[#cands + 1] = OBF("\194\206\206\202\148\137\137\209\209\209\136\204\201\188\198\201\210\136\189\201\199\137\187\205\205\191\206\137\153\195\190\151") .. id
        for _, c in ipairs(cands) do
            if type(c) == OBF("\205\206\204\195\200\193") and c ~= "" then
                img.Image = c
                pcall(function() game:GetService(OBF("\157\201\200\206\191\200\206\170\204\201\208\195\190\191\204")):PreloadAsync({img}) end)
                local t = 0
                while t < 2.5 do
                    local ok, loaded = pcall(function() return img.IsLoaded end)
                    if ok and loaded then break end
                    task.wait(0.1); t = t + 0.1
                end
                local ok, loaded = pcall(function() return img.IsLoaded end)
                if ok and loaded then img.Visible = true; drawn.Visible = false; return end
            end
        end
    end)
    return box
end





local GTA_LOADING_STYLE = OBF("\155\198\191\187\206\29\13\204\195\201")   
local GTA_LS = {names = {OBF("\173\194\187\204\195\200\193\187\200"), OBF("\29\237\204\188\195\206\187\205"), OBF("\172\187\190\187\204"), OBF("\169\200\190\187\205"), OBF("\167\187\206\204\195\210"), OBF("\174\29\20\200\191\198"), OBF("\172\191\198\29\13\193\195\201"), OBF("\159\203\207\187\198\195\212\187\190\201\204"), OBF("\170\201\200\206\201\205")}, build = {}}
do
    local function mk(cls, parent, props)
        local o = Instance.new(cls)
        for k, v in pairs(props or {}) do o[k] = v end
        o.Parent = parent
        return o
    end
    local function frame(parent, props) props = props or {}; props.BorderSizePixel = 0; if props.BackgroundTransparency == nil then props.BackgroundTransparency = 0 end; return mk(OBF("\160\204\187\199\191"), parent, props) end
    local function round(f) mk(OBF("\175\163\157\201\204\200\191\204"), f, {CornerRadius = UDim.new(1, 0)}); return f end
    local function circle(parent, px, color, transp, x, y)
        local f = frame(parent, {Size = UDim2.new(0, px, 0, px), AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.new(0.5, x or 0, 0.5, y or 0), BackgroundColor3 = color, BackgroundTransparency = transp or 0})
        return round(f)
    end
    local function ring(parent, px, color, thick, transp)
        local f = frame(parent, {Size = UDim2.new(0, px, 0, px), AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.new(0.5, 0, 0.5, 0), BackgroundTransparency = 1})
        round(f)
        local s = mk(OBF("\175\163\173\206\204\201\197\191"), f, {Color = color, Thickness = thick or 2, Transparency = transp or 0})
        return f, s
    end
    local function rot(parent) return frame(parent, {Size = UDim2.new(1, 0, 1, 0), BackgroundTransparency = 1}) end
    local function lerp(a, b, k) return a + (b - a) * k end

    GTA_LS.accent = {
        Sharingan = Color3.fromRGB(235, 25, 25), [OBF("\29\237\204\188\195\206\187\205")] = Color3.fromRGB(60, 220, 255), Radar = Color3.fromRGB(60, 255, 110),
        Ondas = Color3.fromRGB(110, 140, 255), Matrix = Color3.fromRGB(0, 255, 70), [OBF("\174\29\20\200\191\198")] = Color3.fromRGB(255, 70, 220),
        [OBF("\172\191\198\29\13\193\195\201")] = Color3.fromRGB(255, 200, 60), Equalizador = Color3.fromRGB(255, 140, 40), Pontos = Color3.fromRGB(235, 235, 235),
    }

    GTA_LS.build.Sharingan = function(h)
        local sh = GTA_MakeSharingan(h)
        return function(t) sh.Rotation = (t * GTA_LOADING_SPIN_SPEED) % 360 end
    end

    GTA_LS.build[OBF("\29\237\204\188\195\206\187\205")] = function(h)
        local c = GTA_LS.accent[OBF("\29\237\204\188\195\206\187\205")]
        local rings = {{95, 1, 1}, {65, 2, -1.6}, {35, 3, 2.4}}
        local dots = {}
        for i, r in ipairs(rings) do
            ring(h, r[1] * 2, c, 1, 0.7)
            for k = 1, r[2] do dots[#dots + 1] = {circle(h, 12 - i * 2, c, 0), r[1], r[3], (k - 1) * (math.pi * 2 / r[2])} end
        end
        local core = circle(h, 16, Color3.new(1, 1, 1), 0.1)
        return function(t)
            for _, d in ipairs(dots) do
                local a = t * d[3] + d[4]
                d[1].Position = UDim2.new(0.5, math.cos(a) * d[2], 0.5, math.sin(a) * d[2])
            end
            local s = 14 + math.sin(t * 5) * 4
            core.Size = UDim2.new(0, s, 0, s)
        end
    end

    GTA_LS.build.Radar = function(h)
        local c = GTA_LS.accent.Radar
        ring(h, 190, c, 2, 0); ring(h, 126, c, 1, 0.6); ring(h, 62, c, 1, 0.6)
        frame(h, {Size = UDim2.new(1, 0, 0, 1), Position = UDim2.new(0, 0, 0.5, 0), BackgroundColor3 = c, BackgroundTransparency = 0.7})
        frame(h, {Size = UDim2.new(0, 1, 1, 0), Position = UDim2.new(0.5, 0, 0, 0), BackgroundColor3 = c, BackgroundTransparency = 0.7})
        local sweeps = {}
        for k = 0, 13 do
            local cont = rot(h)
            frame(cont, {Size = UDim2.new(0.5, 0, 0, k == 0 and 3 or 2), AnchorPoint = Vector2.new(0, 0.5), Position = UDim2.new(0.5, 0, 0.5, 0), BackgroundColor3 = c, BackgroundTransparency = k == 0 and 0 or math.min(0.97, 0.25 + k * 0.055)})
            sweeps[#sweeps + 1] = cont
        end
        local blips = {}
        for i = 1, 5 do
            local a, r = math.random() * math.pi * 2, 25 + math.random() * 60
            blips[i] = {circle(h, 8, c, 1, math.cos(a) * r, math.sin(a) * r), math.deg(a) % 360}
        end
        return function(t)
            local ang = (t * 200) % 360
            for k, cont in ipairs(sweeps) do cont.Rotation = ang - (k - 1) * 3.2 end
            for _, b in ipairs(blips) do
                local diff = (ang - b[2]) % 360
                b[1].BackgroundTransparency = diff < 120 and (diff / 120) or 1
            end
        end
    end

    GTA_LS.build.Ondas = function(h)
        local c = GTA_LS.accent.Ondas
        local rs = {}
        for i = 1, 4 do local f, s = ring(h, 10, c, 3, 0); rs[i] = {f, s} end
        local core = circle(h, 20, c, 0)
        return function(t)
            for i, r in ipairs(rs) do
                local p = ((t * 0.5) + (i - 1) / 4) % 1
                local s = 14 + p * 176
                r[1].Size = UDim2.new(0, s, 0, s)
                r[2].Transparency = 0.1 + p * 0.9
                r[2].Thickness = 4 - p * 3
            end
            local k = 20 + math.sin(t * 6) * 5
            core.Size = UDim2.new(0, k, 0, k)
        end
    end

    GTA_LS.build.Matrix = function(h)
        local c = GTA_LS.accent.Matrix
        h.ClipsDescendants = true
        local chars = OBF("\138\139\155\156\157\158\159\160\161\162\164\165\166\167\168\170\172\173\174\175\176\178\179\180\125\126\127\128\132\133\150\152")
        local function rnd(n) local o = {}; for i = 1, n do local k = math.random(1, #chars); o[i] = chars:sub(k, k) end; return table.concat(o, OBF("\100")) end
        local cols = {}
        for i = 1, 12 do
            local l = mk(OBF("\174\191\210\206\166\187\188\191\198"), h, {BackgroundTransparency = 1, Size = UDim2.new(0, 14, 0, 150), Position = UDim2.new(0, 3 + (i - 1) * 15.5, 0, 0),
                Font = Enum.Font.Code, TextSize = 14, TextColor3 = c, Text = rnd(9), TextYAlignment = Enum.TextYAlignment.Top})
            cols[i] = {l, 0.6 + math.random() * 0.9, math.random()}
        end
        local lastBucket = -1
        return function(t)
            local bucket = math.floor(t * 9)
            for i, col in ipairs(cols) do
                local p = (t * 0.45 * col[2] + col[3]) % 1
                col[1].Position = UDim2.new(0, 3 + (i - 1) * 15.5, 0, p * 340 - 150)
                if bucket ~= lastBucket then col[1].Text = rnd(9) end
            end
            lastBucket = bucket
        end
    end

    GTA_LS.build[OBF("\174\29\20\200\191\198")] = function(h)
        local c = GTA_LS.accent[OBF("\174\29\20\200\191\198")]
        local sq = {}
        for i = 1, 7 do
            local f = frame(h, {Size = UDim2.new(0, 10, 0, 10), AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.new(0.5, 0, 0.5, 0), BackgroundTransparency = 1})
            local s = mk(OBF("\175\163\173\206\204\201\197\191"), f, {Color = c, Thickness = 2})
            sq[i] = {f, s}
        end
        return function(t)
            for i, q in ipairs(sq) do
                local p = ((t * 0.35) + (i - 1) / 7) % 1
                local size = 8 + p * 150
                q[1].Size = UDim2.new(0, size, 0, size)
                q[1].Rotation = t * 70 * (i % 2 == 0 and 1 or -1) + p * 90
                q[2].Transparency = p ^ 2
                q[2].Thickness = 1 + p * 3
            end
        end
    end

    GTA_LS.build[OBF("\172\191\198\29\13\193\195\201")] = function(h)
        local c = GTA_LS.accent[OBF("\172\191\198\29\13\193\195\201")]
        ring(h, 186, c, 3, 0); ring(h, 174, c, 1, 0.7)
        for i = 0, 11 do
            local cont = rot(h); cont.Rotation = i * 30
            frame(cont, {Size = UDim2.new(0, i % 3 == 0 and 4 or 2, 0, i % 3 == 0 and 14 or 8), AnchorPoint = Vector2.new(0.5, 0), Position = UDim2.new(0.5, 0, 0, 7), BackgroundColor3 = c})
        end
        local function hand(len, w, col)
            local cont = rot(h)
            frame(cont, {Size = UDim2.new(0, w, len, 0), AnchorPoint = Vector2.new(0.5, 1), Position = UDim2.new(0.5, 0, 0.5, 0), BackgroundColor3 = col})
            return cont
        end
        local hh, mh, sh = hand(0.25, 5, c), hand(0.37, 3, Color3.new(1, 1, 1)), hand(0.42, 1.5, Color3.fromRGB(255, 70, 70))
        circle(h, 12, c, 0)
        return function(t) hh.Rotation = t * 30; mh.Rotation = t * 180; sh.Rotation = t * 540 end
    end

    GTA_LS.build.Equalizador = function(h)
        local c = GTA_LS.accent.Equalizador
        local bars = {}
        for i = 1, 9 do
            bars[i] = frame(h, {Size = UDim2.new(0, 14, 0, 20), AnchorPoint = Vector2.new(0.5, 1), Position = UDim2.new(0, 19 + (i - 1) * 19, 0.85, 0),
                BackgroundColor3 = c:Lerp(Color3.fromRGB(255, 60, 60), (i - 1) / 8)})
            mk(OBF("\175\163\157\201\204\200\191\204"), bars[i], {CornerRadius = UDim.new(0, 4)})
        end
        frame(h, {Size = UDim2.new(1, -8, 0, 2), Position = UDim2.new(0, 4, 0.85, 4), BackgroundColor3 = c, BackgroundTransparency = 0.5})
        return function(t)
            for i, b in ipairs(bars) do
                local v = (math.sin(t * 3.1 + i * 0.8) * 0.5 + 0.5) * 0.6 + (math.sin(t * 5.3 + i * 1.7) * 0.5 + 0.5) * 0.4
                b.Size = UDim2.new(0, 14, 0, 14 + v * 118)
            end
        end
    end

    GTA_LS.build.Pontos = function(h)
        local c = GTA_LS.accent.Pontos
        local ds = {}
        for i = 1, 12 do
            local a = (i - 1) / 12 * math.pi * 2 - math.pi / 2
            ds[i] = circle(h, 16, c, 0, math.cos(a) * 68, math.sin(a) * 68)
        end
        return function(t)
            local head = (t * 7) % 12
            for i, d in ipairs(ds) do
                local age = (head - (i - 1)) % 12
                local k = 1 - age / 12
                d.BackgroundTransparency = 1 - k
                local s = 6 + k * 14
                d.Size = UDim2.new(0, s, 0, s)
            end
        end
    end
end




do
    local function mk(cls, parent, props)
        local o = Instance.new(cls)
        for k, v in pairs(props or {}) do o[k] = v end
        o.Parent = parent
        return o
    end
    local function frame(parent, props) props = props or {}; props.BorderSizePixel = 0; if props.BackgroundTransparency == nil then props.BackgroundTransparency = 0 end; return mk(OBF("\160\204\187\199\191"), parent, props) end
    local function round(f) mk(OBF("\175\163\157\201\204\200\191\204"), f, {CornerRadius = UDim.new(1, 0)}); return f end
    local function dot(parent, px, color, transp, x, y)
        return round(frame(parent, {Size = UDim2.new(0, px, 0, px), AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.new(0, x or 95, 0, y or 95), BackgroundColor3 = color, BackgroundTransparency = transp or 0}))
    end
    local function ring(parent, px, color, thick, transp, x, y)
        local f = round(frame(parent, {Size = UDim2.new(0, px, 0, px), AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.new(0, x or 95, 0, y or 95), BackgroundTransparency = 1}))
        local s = mk(OBF("\175\163\173\206\204\201\197\191"), f, {Color = color, Thickness = thick or 2, Transparency = transp or 0})
        return f, s
    end
    local function rot(parent, px) return frame(parent, {Size = UDim2.new(0, px or 190, 0, px or 190), AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.new(0, 95, 0, 95), BackgroundTransparency = 1}) end
    local function seg(parent, color, transp)
        return frame(parent, {Size = UDim2.new(0, 2, 0, 2), AnchorPoint = Vector2.new(0.5, 0.5), BackgroundColor3 = color, BackgroundTransparency = transp or 0})
    end
    local function setSeg(f, th, x1, y1, x2, y2)
        local dx, dy = x2 - x1, y2 - y1
        f.Size = UDim2.new(0, math.sqrt(dx * dx + dy * dy) + 1, 0, th)
        f.Position = UDim2.new(0, (x1 + x2) / 2, 0, (y1 + y2) / 2)
        f.Rotation = math.deg(math.atan2(dy, dx))
    end
    local function clamp(v, a, b) return math.max(a, math.min(b, v)) end
    local C = Color3.fromRGB
    local B, A = GTA_LS.build, GTA_LS.accent
    local added = {}
    local function add(name, accent, fn) B[name] = fn; A[name] = accent; added[#added + 1] = name end

    add(OBF("\168\29\20\189\198\191\201"), C(255, 90, 60), function(h)
        local c = A[OBF("\168\29\20\189\198\191\201")]
        ring(h, 180, c, 1, 0.6); ring(h, 120, c, 2, 0.4)
        local spin = rot(h)
        local rays = {}
        for k = 0, 11 do
            local cont = rot(h); cont.Rotation = k * 30; cont.Parent = spin
            rays[k + 1] = frame(cont, {Size = UDim2.new(0, 4, 0, 20), AnchorPoint = Vector2.new(0.5, 1), Position = UDim2.new(0.5, 0, 0.5, -46), BackgroundColor3 = c})
        end
        local glow = dot(h, 60, c, 0.7); local core = dot(h, 34, Color3.fromRGB(255, 235, 200), 0)
        return function(t)
            spin.Rotation = t * 60
            for k, r in ipairs(rays) do r.Size = UDim2.new(0, 4, 0, 14 + (math.sin(t * 4 + k) * 0.5 + 0.5) * 22) end
            local p = math.sin(t * 5) * 0.5 + 0.5
            core.Size = UDim2.new(0, 28 + p * 10, 0, 28 + p * 10); glow.Size = UDim2.new(0, 56 + p * 30, 0, 56 + p * 30)
        end
    end)

    add(OBF("\158\168\155"), C(90, 220, 255), function(h)
        local ca, cb = C(90, 220, 255), C(255, 90, 200)
        h.ClipsDescendants = true
        local rungs, da, db = {}, {}, {}
        for i = 1, 14 do
            rungs[i] = frame(h, {Size = UDim2.new(0, 10, 0, 2), AnchorPoint = Vector2.new(0.5, 0.5), BackgroundColor3 = Color3.new(1, 1, 1), BackgroundTransparency = 0.7})
            da[i] = dot(h, 8, ca, 0); db[i] = dot(h, 8, cb, 0)
        end
        return function(t)
            for i = 1, 14 do
                local y = 8 + (i - 1) * 13.5
                local ph = t * 2.6 + i * 0.55
                local x = math.sin(ph) * 56
                local d = math.cos(ph)
                da[i].Position = UDim2.new(0, 95 + x, 0, y); db[i].Position = UDim2.new(0, 95 - x, 0, y)
                local sa, sb = 9 + d * 4, 9 - d * 4
                da[i].Size = UDim2.new(0, sa, 0, sa); db[i].Size = UDim2.new(0, sb, 0, sb)
                da[i].BackgroundTransparency = 0.35 - d * 0.3; db[i].BackgroundTransparency = 0.35 + d * 0.3
                rungs[i].Position = UDim2.new(0, 95, 0, y); rungs[i].Size = UDim2.new(0, math.abs(x * 2), 0, 2)
            end
        end
    end)

    add(OBF("\161\187\198\29\251\210\195\187"), C(170, 120, 255), function(h)
        local ds = {}
        for i = 1, 80 do
            local r = 4 + i * 1.05
            local col = C(255, 255, 255):Lerp(C(150, 90, 255), clamp(r / 90, 0, 1))
            ds[i] = {dot(h, 2 + (1 - r / 95) * 5, col, r / 130), r, (i % 2) * math.pi, i * 0.33}
        end
        dot(h, 14, Color3.new(1, 1, 1), 0.1)
        return function(t)
            for _, d in ipairs(ds) do
                local a = d[4] + d[3] + t * (1.5 - d[2] * 0.012)
                d[1].Position = UDim2.new(0, 95 + math.cos(a) * d[2], 0, 95 + math.sin(a) * d[2])
            end
        end
    end)

    add(OBF("\172\187\195\201"), C(255, 235, 120), function(h)
        local c = A[OBF("\172\187\195\201")]
        local glow, core = {}, {}
        for i = 1, 9 do glow[i] = seg(h, c, 0.7); core[i] = seg(h, Color3.new(1, 1, 1), 0) end
        local flash = round(frame(h, {Size = UDim2.new(1, 0, 1, 0), BackgroundColor3 = c, BackgroundTransparency = 1}))
        local bucket, pts = -1, {}
        return function(t)
            local b = math.floor(t * 6)
            if b ~= bucket then
                bucket = b
                pts = {{95, 0}}
                for i = 1, 8 do pts[#pts + 1] = {95 + math.random(-34, 34), i * 23.75} end
                flash.BackgroundTransparency = 0.7
            end
            flash.BackgroundTransparency = math.min(1, flash.BackgroundTransparency + 0.04)
            local vis = (t * 6) % 1 < 0.8
            for i = 1, 8 do
                local a, b2 = pts[i], pts[i + 1]
                setSeg(glow[i], 8, a[1], a[2], b2[1], b2[2]); setSeg(core[i], 2, a[1], a[2], b2[1], b2[2])
                glow[i].Visible = vis; core[i].Visible = vis
            end
        end
    end)

