local function GTA_PickLoadingStyle(record)
    local function readf(name)
        local raw
        if type(readfile) == OBF("\192\207\200\189\206\195\201\200") then local ok, r = pcall(readfile, name); if ok and type(r) == OBF("\205\206\204\195\200\193") and #r > 0 then raw = r end end
        return raw
    end
    local choice = GTA_LOADING_STYLE
    pcall(function() if getgenv().GTAHubLoadStyle then choice = getgenv().GTAHubLoadStyle end end)
    local f = readf(OBF("\161\174\155\162\207\188\185\166\201\187\190\173\206\211\198\191\136\206\210\206"))
    if f then choice = f:gsub(OBF("\127\205\133\126"), "") end
    if choice ~= OBF("\155\198\191\187\206\29\13\204\195\201") and GTA_LS.build[choice] then return choice end
    if not GTA_LS.seeded then GTA_LS.seeded = true; pcall(function() math.randomseed(os.time() + math.floor(os.clock() * 1000)) end) end
    local hist = {used = {}, last = nil}
    local raw = readf(OBF("\161\174\155\162\207\188\185\166\201\187\190\162\195\205\206\201\204\211\136\196\205\201\200"))
    if not raw then pcall(function() raw = getgenv().GTAHubLoadHistory end) end
    if type(raw) == OBF("\205\206\204\195\200\193") then
        local ok, d = pcall(function() return game:GetService(OBF("\162\206\206\202\173\191\204\208\195\189\191")):JSONDecode(raw) end)
        if ok and type(d) == OBF("\206\187\188\198\191") and type(d.used) == OBF("\206\187\188\198\191") then hist = d end
    end
    local usedSet = {}
    for _, n in ipairs(hist.used) do usedSet[n] = true end
    local pool = {}
    for _, n in ipairs(GTA_LS.names) do if not usedSet[n] and n ~= hist.last then pool[#pool + 1] = n end end
    if #pool == 0 then   
        hist.used = {}
        for _, n in ipairs(GTA_LS.names) do if n ~= hist.last then pool[#pool + 1] = n end end
    end
    local pick = pool[math.random(1, #pool)]
    if record then
        hist.used[#hist.used + 1] = pick; hist.last = pick
        local ok, json = pcall(function() return game:GetService(OBF("\162\206\206\202\173\191\204\208\195\189\191")):JSONEncode(hist) end)
        if ok then
            pcall(function() getgenv().GTAHubLoadHistory = json end)
            if type(writefile) == OBF("\192\207\200\189\206\195\201\200") then pcall(writefile, OBF("\161\174\155\162\207\188\185\166\201\187\190\162\195\205\206\201\204\211\136\196\205\201\200"), json) end
        end
    end
    return pick
end

