local SearchQuery = ""
local ActiveContainer = nil

local function CollectVisibleText(instance)
    local parts = {}
    local ok, descendants = pcall(function()
        return instance:GetDescendants()
    end)
    if not ok then
        return ""
    end

    for _, desc in ipairs(descendants) do
        if desc:IsA(OBF("\174\191\210\206\166\187\188\191\198")) or desc:IsA(OBF("\174\191\210\206\156\207\206\206\201\200")) or desc:IsA(OBF("\174\191\210\206\156\201\210")) then
            local text = desc.Text
            if type(text) == OBF("\205\206\204\195\200\193") and text ~= "" then
                table.insert(parts, text)
            end
        end
    end

    table.insert(parts, instance.Name)
    return table.concat(parts, OBF("\122")):lower()
end

local FilteredContainers = setmetatable({}, {__mode = OBF("\197")})
local function ApplySearchFilter(container, query)
    if not container or not container.Parent then
        return
    end

    local needle = tostring(query or ""):lower():gsub(OBF("\184\127\205\133"), ""):gsub(OBF("\127\205\133\126"), "")
    
    if needle == "" then
        if not FilteredContainers[container] then return end
        FilteredContainers[container] = nil
    else
        FilteredContainers[container] = true
    end
    for _, child in ipairs(container:GetChildren()) do
        if child:IsA(OBF("\161\207\195\169\188\196\191\189\206")) then
            if needle == "" then
                child.Visible = true
            else
                child.Visible = CollectVisibleText(child):find(needle, 1, true) ~= nil
            end
        end
    end
end

