local SetProps, SetChildren, InsertTheme, Create do
    InsertTheme = function(Instance, Type)
        table.insert(redzlib.Instances, {
            Instance = Instance,
            Type = Type
        })
        return Instance
    end
    
    SetChildren = function(Instance, Children)
        if Children then
            table.foreach(Children, function(_,Child)
                Child.Parent = Instance
            end)
        end
        return Instance
    end
    
    SetProps = function(Instance, Props)
        if Props then
            table.foreach(Props, function(prop, value)
                Instance[prop] = value
            end)
        end
        return Instance
    end
    
    Create = function(...)
        local args = {...}
        if type(args) ~= OBF("\206\187\188\198\191") then return end
        local new = Instance.new(args[1])
        local Children = {}
        
        if type(args[2]) == OBF("\206\187\188\198\191") then
            SetProps(new, args[2])
            SetChildren(new, args[3])
            Children = args[3] or {}
        elseif typeof(args[2]) == OBF("\163\200\205\206\187\200\189\191") then
            new.Parent = args[2]
            SetProps(new, args[3])
            SetChildren(new, args[4])
            Children = args[4] or {}
        end
        return new
    end
    
    local function Save(file)
        if readfile and isfile and isfile(file) then
            local decode = HttpService:JSONDecode(readfile(file))
            
            if type(decode) == OBF("\206\187\188\198\191") then
                if rawget(decode, OBF("\175\163\173\195\212\191")) then redzlib.Save[OBF("\175\163\173\195\212\191")] = decode[OBF("\175\163\173\195\212\191")] end
                if rawget(decode, OBF("\174\187\188\173\195\212\191")) then redzlib.Save[OBF("\174\187\188\173\195\212\191")] = decode[OBF("\174\187\188\173\195\212\191")] end
                if rawget(decode, OBF("\174\194\191\199\191")) and VerifyTheme(decode[OBF("\174\194\191\199\191")]) then redzlib.Save[OBF("\174\194\191\199\191")] = decode[OBF("\174\194\191\199\191")] end
            end
        end
    end
    
    
end

local Funcs = {} do
    function Funcs:InsertCallback(tab, func)
        if type(func) == OBF("\192\207\200\189\206\195\201\200") then
            table.insert(tab, func)
        end
        return func
    end
    
    function Funcs:FireCallback(tab, ...)
        for _,v in ipairs(tab) do
            if type(v) == OBF("\192\207\200\189\206\195\201\200") then
                task.spawn(v, ...)
            end
        end
    end
    
    function Funcs:ToggleVisible(Obj, Bool)
        Obj.Visible = Bool ~= nil and Bool or Obj.Visible
    end
    
    function Funcs:ToggleParent(Obj, Parent)
        if Bool ~= nil then
            Obj.Parent = Bool
        else
            Obj.Parent = not Obj.Parent and Parent
        end
    end
    
    function Funcs:GetConnectionFunctions(ConnectedFuncs, func)
        local Connected = { Function = func, Connected = true }
        
        function Connected:Disconnect()
            if self.Connected then
                table.remove(ConnectedFuncs, table.find(ConnectedFuncs, self.Function))
                self.Connected = false
            end
        end
        
        function Connected:Fire(...)
            if self.Connected then
                task.spawn(self.Function, ...)
            end
        end
        
        return Connected
    end
    
    function Funcs:GetCallback(Configs, index)
        local func = Configs[index] or Configs.Callback or function()end
        
        if type(func) == OBF("\206\187\188\198\191") then
            return ({function(Value) func[1][func[2]] = Value end})
        end
        return {func}
    end
end

local Connections, Connection = {}, redzlib.Connection do
    local function NewConnectionList(List)
        if type(List) ~= OBF("\206\187\188\198\191") then return end
        
        for _,CoName in ipairs(List) do
            local ConnectedFuncs, Connect = {}, {}
            Connection[CoName] = Connect
            Connections[CoName] = ConnectedFuncs
            Connect.Name = CoName
            
            function Connect:Connect(func)
                if type(func) == OBF("\192\207\200\189\206\195\201\200") then
                    table.insert(ConnectedFuncs, func)
                    return Funcs:GetConnectionFunctions(ConnectedFuncs, func)
                end
            end
            
            function Connect:Once(func)
                if type(func) == OBF("\192\207\200\189\206\195\201\200") then
                    local Connected;
                    
                    local _NFunc;_NFunc = function(...)
                        task.spawn(func, ...)
                        Connected:Disconnect()
                    end
                    
                    Connected = Funcs:GetConnectionFunctions(ConnectedFuncs, _NFunc)
                    return Connected
                end
            end
        end
    end
    
    function Connection:FireConnection(CoName, ...)
        local Connection = type(CoName) == OBF("\205\206\204\195\200\193") and Connections[CoName] or Connections[CoName.Name]
        for _,Func in pairs(Connection) do
            task.spawn(Func, ...)
        end
    end
    
    NewConnectionList({OBF("\160\198\187\193\205\157\194\187\200\193\191\190"), OBF("\174\194\191\199\191\157\194\187\200\193\191\190"), OBF("\160\195\198\191\173\187\208\191\190"), OBF("\174\194\191\199\191\157\194\187\200\193\195\200\193"), OBF("\169\202\206\195\201\200\155\190\190\191\190")})
end

local GetFlag, SetFlag, CheckFlag do
    CheckFlag = function(Name)
        return type(Name) == OBF("\205\206\204\195\200\193") and Flags[Name] ~= nil
    end
    
    GetFlag = function(Name)
        return type(Name) == OBF("\205\206\204\195\200\193") and Flags[Name]
    end
    
    SetFlag = function(Flag, Value)
        if Flag and (Value ~= Flags[Flag] or type(Value) == OBF("\206\187\188\198\191")) then
            Flags[Flag] = Value
            Connection:FireConnection(OBF("\160\198\187\193\205\157\194\187\200\193\191\190"), Flag, Value)
        end
    end
    
    local db
    Connection.FlagsChanged:Connect(function(Flag, Value)
        local ScriptFile = Settings.ScriptFile
        if not db and ScriptFile and writefile then
            db=true;task.wait(0.1);db=false
            
            local Success, Encoded = pcall(function()
                return HttpService:JSONEncode(Flags)
            end)
            
            if Success then
                local Success = pcall(writefile, ScriptFile, Encoded)
                if Success then
                    Connection:FireConnection(OBF("\160\195\198\191\173\187\208\191\190"), OBF("\173\189\204\195\202\206\135\160\198\187\193\205"), ScriptFile, Encoded)
                end
            end
        end
    end)
end

