    }), OBF("\158\187\204\197\174\191\210\206"))

    local Frame = Make(OBF("\156\207\206\206\201\200"), Instance, {
        Size = UDim2.new(1, 0, 0, 25),
        AutomaticSize = OBF("\179"),
        Name = OBF("\169\202\206\195\201\200")
    })Make(OBF("\157\201\204\200\191\204"), Frame, UDim.new(0, 6))
    
    LabelHolder = Create(OBF("\160\204\187\199\191"), Frame, {
        AutomaticSize = OBF("\179"),
        BackgroundTransparency = 1,
        Size = HolderSize,
        Position = UDim2.new(0, 10, 0),
        AnchorPoint = Vector2.new(0, 0)
    }, {
        Create(OBF("\175\163\166\195\205\206\166\187\211\201\207\206"), {
            SortOrder = OBF("\166\187\211\201\207\206\169\204\190\191\204"),
