local GTA_ICON_MAP = {home=OBF("\74\249\233\250"), music=OBF("\74\249\232\15"), bomb=OBF("\74\249\236\253"), paper=OBF("\74\249\237\222"), car=OBF("\74\249\244\241"), baby=OBF("\74\249\235\16"), user=OBF("\74\249\235\254"), tp=OBF("\74\249\230\218"), portal=OBF("\74\249\230\218"), backpack=OBF("\74\249\232\236"), plane=OBF("\60\246\226"), info=OBF("\60\222\19")}
function redzlib:GetIcon(index)
    if type(index) ~= OBF("\205\206\204\195\200\193") then return "" end
    local m = GTA_ICON_MAP[index:lower()]
    if m then return m end
    if index:find(OBF("\204\188\210\187\205\205\191\206\195\190")) then return OBF("\60\218\252") end
    return index
end

function redzlib:SetTheme(NewTheme)
    if not VerifyTheme(NewTheme) then return end
    
    redzlib.Save.Theme = NewTheme
    SaveJson(OBF("\157\201\200\192\195\193\136\196\205\201\200"), redzlib.Save)
    Theme = redzlib.Themes[NewTheme]
    
    Connection:FireConnection(OBF("\174\194\191\199\191\157\194\187\200\193\191\190"), NewTheme)
    table.foreach(redzlib.Instances, function(_,Val)
        if Val.Type == OBF("\161\204\187\190\195\191\200\206") then
            Val.Instance.Color = Theme[OBF("\157\201\198\201\204\122\162\207\188\122\139")]
        elseif Val.Type == OBF("\160\204\187\199\191") then
            Val.Instance.BackgroundColor3 = Theme[OBF("\157\201\198\201\204\122\162\207\188\122\140")]
        elseif Val.Type == OBF("\173\206\204\201\197\191") then
            Val.Instance[GetColor(Val.Instance)] = Theme[OBF("\157\201\198\201\204\122\173\206\204\201\197\191")]
        elseif Val.Type == OBF("\174\194\191\199\191") then
            Val.Instance[GetColor(Val.Instance)] = Theme[OBF("\157\201\198\201\204\122\174\194\191\199\191")]
        elseif Val.Type == OBF("\174\191\210\206") then
            pcall(function()
                Val.Instance[GetColor(Val.Instance)] = Theme[OBF("\157\201\198\201\204\122\174\191\210\206")]
            end)
        elseif Val.Type == OBF("\158\187\204\197\174\191\210\206") then
            pcall(function()
                Val.Instance[GetColor(Val.Instance)] = Theme[OBF("\157\201\198\201\204\122\158\187\204\197\122\174\191\210\206")]
            end)
        elseif Val.Type == OBF("\173\189\204\201\198\198\156\187\204") then
            pcall(function()
                Val.Instance[GetColor(Val.Instance)] = Theme[OBF("\157\201\198\201\204\122\174\194\191\199\191")]
            end)
        end
    end)
end

function redzlib:SetScale(NewScale)
    NewScale = ViewportSize.Y / math.clamp(NewScale, 300, 2000)
    UIScale, ScreenGui.Scale.Scale = NewScale, NewScale
end

