            local ScrollSize, WaitClick = 5
            local function Disable()
                WaitClick = true
                CreateTween({Arrow, OBF("\172\201\206\187\206\195\201\200"), 0, 0.2})
                CreateTween({DropFrame, OBF("\173\195\212\191"), UDim2.new(0, 152, 0, 0), 0.2, true})
