                    Arrow.Image = OBF("\204\188\210\187\205\205\191\206\195\190\148\137\137\139\138\145\138\147\145\147\139\143\140\141")
                    CreateTween({Arrow, OBF("\163\199\187\193\191\157\201\198\201\204\141"), Color3.fromRGB(255, 255, 255), 0.2})
                    CreateTween({DropFrame, OBF("\173\195\212\191"), UDim2.new(0, 152, 0, 0), 0.2, true})
