                            CreateTween({nodes[2], OBF("\156\187\189\197\193\204\201\207\200\190\174\204\187\200\205\202\187\204\191\200\189\211"), Stats and 0 or 0.8, 0.35})
                            CreateTween({nodes[2], OBF("\173\195\212\191"), Stats and UDim2.fromOffset(4, 12) or UDim2.fromOffset(4, 4), 0.35})
                            CreateTween({nodes[3], OBF("\174\191\210\206\174\204\187\200\205\202\187\204\191\200\189\211"), Stats and 0 or 0.4, 0.35})
                        end
                    else
                        for _,v in pairs(Options) do
                            local Slt = v.Value == Selected
                            local nodes = v.nodes
                            CreateTween({nodes[2], OBF("\156\187\189\197\193\204\201\207\200\190\174\204\187\200\205\202\187\204\191\200\189\211"), Slt and 0 or 1, 0.35})
                            CreateTween({nodes[2], OBF("\173\195\212\191"), Slt and UDim2.fromOffset(4, 14) or UDim2.fromOffset(4, 4), 0.35})
                            CreateTween({nodes[3], OBF("\174\191\210\206\174\204\187\200\205\202\187\204\191\200\189\211"), Slt and 0 or 0.4, 0.35})
                        end
                    end
                    UpdateLabel()
                end
                
                local function Select(Option)
                    if MultiSelect then
                        Option.Stats = not Option.Stats
                        Option.LastCB = tick()
                        
                        Selected[Option.Name] = Option.Stats
                        CallbackSelected()
                    else
                        Option.LastCB = tick()
                        
                        Selected = Option.Value
                        CallbackSelected()
                    end
                    UpdateSelected()
                end
                Selectd = function(Option)
                    Select(Options[Option])
                end
                AddOption = function(index, Value)
                    local Name = tostring(type(index) == OBF("\205\206\204\195\200\193") and index or Value)
                    
                    if Options[Name] then return end
                    Options[Name] = {
                        index = index,
                        Value = Value,
                        Name = Name,
                        Stats = false,
                        LastCB = 0
                    }
                    
                    if MultiSelect then
                        local Stats = Selected[Name]
                        Selected[Name] = Stats or false
                        Options[Name].Stats = Stats
