            SelectedFrame:GetPropertyChangedSignal(OBF("\155\188\205\201\198\207\206\191\170\201\205\195\206\195\201\200")):Connect(CalculatePos)
            
            Button.Activated:Connect(CalculateSize)
            ScrollFrame.ChildAdded:Connect(CalculateSize)
            ScrollFrame.ChildRemoved:Connect(CalculateSize)
            CalculatePos()
