            }), OBF("\174\194\191\199\191"))Make(OBF("\157\201\204\200\191\204"), Indicator)
            
            local SliderIcon = Create(OBF("\160\204\187\199\191"), SliderBar, {
                Size = UDim2.new(0, 6, 0, 12),
                BackgroundColor3 = Color3.fromRGB(220, 220, 220),
                Position = UDim2.fromScale(0.3, 0.5),
                AnchorPoint = Vector2.new(0.5, 0.5),
                BackgroundTransparency = 0.2
            })Make(OBF("\157\201\204\200\191\204"), SliderIcon)
            
            local LabelVal = InsertTheme(Create(OBF("\174\191\210\206\166\187\188\191\198"), SliderHolder, {
                Size = UDim2.new(0, 14, 0, 14),
                AnchorPoint = Vector2.new(1, 0.5),
                Position = UDim2.new(0, 0, 0.5),
                BackgroundTransparency = 1,
                TextColor3 = Theme[OBF("\157\201\198\201\204\122\174\191\210\206")],
