            LabelVal:GetPropertyChangedSignal(OBF("\174\191\210\206")):Connect(function()
                UIScale.Scale = 0.3
                CreateTween({UIScale, OBF("\173\189\187\198\191"), 1.2, 0.1})
                CreateTween({LabelVal, OBF("\172\201\206\187\206\195\201\200"), math.random(-1, 1) * 5, 0.15, true})
                CreateTween({UIScale, OBF("\173\189\187\198\191"), 1, 0.2})
                CreateTween({LabelVal, OBF("\172\201\206\187\206\195\201\200"), 0, 0.1})
            end)
            
            function SetSlider(NewValue, Instant)
                if type(NewValue) ~= OBF("\200\207\199\188\191\204") then return end
                
