function UI:Notify(title, text, dur)
    if ActiveWindow and ActiveWindow.MakeNotify then
        return ActiveWindow:MakeNotify({
            Title = title,
            Text = text,
            Time = dur or 3
        })
    end
    warn((OBF("\181\127\205\183\122\127\205")):format(tostring(title), tostring(text)))
end


Hub.NotifyToggles = true
Hub.NoticeReady = false
Hub.QuietToggles = {ESP = true, [OBF("\157\201\199\202\187\204\187\204\122\189\201\199\122\208\195\205\207\187\198\122\201\204\195\193\195\200\187\198")] = true}
local noticeQueue, noticeScheduled = {}, false
function Hub:QueueToggleNotice(name, enabled)
    if not Hub.NoticeReady or not Hub.NotifyToggles or (Hub.Bulk or 0) > 0 or Hub.QuietToggles[name] then return end
    noticeQueue[#noticeQueue + 1] = {name, enabled}
    if noticeScheduled then return end
    noticeScheduled = true
    task.delay(0.3, function()
        noticeScheduled = false
        local queue = noticeQueue
        noticeQueue = {}
        if #queue == 1 then
            UI:Notify(queue[1][1], queue[1][2] and OBF("\155\206\195\208\187\190\201\122\60\246\223") or OBF("\158\191\205\187\206\195\208\187\190\201\122\60\245\238"), 1.8)
        elseif #queue > 1 then
            UI:Notify(OBF("\173\195\205\206\191\199\187"), #queue .. OBF("\122\187\196\207\205\206\191\205\122\187\198\206\191\204\187\190\201\205\136"), 2)
        end
    end)
end




local Libary = redzlib
local GTA_PL = {list = {}}
do
    local Plrs = game:GetService(OBF("\170\198\187\211\191\204\205"))
    
    GTA_PL.roles = _G.GTA_ROLES_PRELOAD or {}
    GTA_PL.roles[OBF("\193\206\187\205\187\140\142\142\187\190\199\140\139")] = GTA_PL.roles[OBF("\193\206\187\205\187\140\142\142\187\190\199\140\139")] or {}
    GTA_PL.roles[OBF("\193\206\187\205\187\140\142\142\187\190\199\140\139")].D = true
    local ROLE_BY_ID, ROLE_ORDER = {}, {}
    for i, r in ipairs(_G.GTA_ROLE_DEFS or {}) do ROLE_BY_ID[r.id] = r; ROLE_ORDER[r.id] = i end
    function GTA_PL.tagsOf(p)
        local n = typeof(p) == OBF("\163\200\205\206\187\200\189\191") and p.Name or tostring(p or "")
        local byId = typeof(p) == OBF("\163\200\205\206\187\200\189\191") and p:IsA(OBF("\170\198\187\211\191\204")) and GTA_PL.roles[tostring(p.UserId)] or nil
        return GTA_PL.roles[n:lower()] or byId or {}
    end
    function GTA_PL.hasRole(p, tag) return GTA_PL.tagsOf(p)[tag] == true end
    function GTA_PL.rolesOf(p)  
        local out = {}
        for tag in pairs(GTA_PL.tagsOf(p)) do out[#out + 1] = tag end
        table.sort(out, function(a, b) return (ROLE_ORDER[a] or 999) < (ROLE_ORDER[b] or 999) end)
        return out
    end
    function GTA_PL.roleOf(p)  
        local r = GTA_PL.rolesOf(p)
        return r[1]
    end
    function GTA_PL.isImmune(p) for tag in pairs(GTA_PL.tagsOf(p)) do if ROLE_BY_ID[tag] and ROLE_BY_ID[tag].immune then return true end end return false end
    
    
    
    
    
    GTA_PL.ADMIN_CAN_TARGET_ADMIN = false
    GTA_PL.KICK_REASON = OBF("\174\191\200\206\201\207\122\199\187\206\187\204\122\207\199\122\187\190\199\195\200")
    function GTA_PL.isOwner(p) return GTA_PL.isImmune(p) end
    _G.GTA_PL_TOAST = function(...) if GTA_PL.toast then return GTA_PL.toast(...) end end
    function GTA_PL.isAdmin(p)
        for tag in pairs(GTA_PL.tagsOf(p)) do if ROLE_BY_ID[tag] and ROLE_BY_ID[tag].admin then return true end end
        return false
    end
    function GTA_PL.canTarget(viewer, target)
        if typeof(target) ~= OBF("\163\200\205\206\187\200\189\191") then return true end
        if viewer == target then return true end
        if GTA_PL.isOwner(target) then return false end
        if GTA_PL.isAdmin(target) then
            if GTA_PL.isOwner(viewer) then return true end
            return GTA_PL.ADMIN_CAN_TARGET_ADMIN == true and GTA_PL.isAdmin(viewer)
        end
        return true
    end
    function GTA_PL.canHit(p) return GTA_PL.canTarget(Plrs.LocalPlayer, p) end
    function GTA_PL.filter(list)
        local out = {}
        for _, p in ipairs(list) do if GTA_PL.canHit(p) then out[#out + 1] = p end end
        return out
    end
    function GTA_PL.punishSelf(reason)  
        if GTA_PL._punished then return end
        GTA_PL._punished = true
        _G.GTA_KEY_OK = false
        pcall(function() if GTA_PL.toast then GTA_PL.toast(GTA_PL.KICK_REASON .. OBF("\122\130") .. tostring(reason) .. OBF("\131"), Color3.fromRGB(255, 40, 40)) end end)
        task.spawn(function()
            task.wait(1.2)
            local lp = Plrs.LocalPlayer
            pcall(function() lp:Kick(GTA_PL.KICK_REASON) end)
            task.wait(3)
            if lp.Parent then  
                local ok = pcall(function() game:GetService(OBF("\174\191\198\191\202\201\204\206\173\191\204\208\195\189\191")):Teleport(game.PlaceId, lp) end)
                if not ok then pcall(function() game:Shutdown() end) end
            end
        end)
    end
    function GTA_PL.violation(target, how)
        local lp = Plrs.LocalPlayer
        if GTA_PL.isAdmin(lp) and not GTA_PL.isOwner(target) then  
            pcall(function() if GTA_PL.toast then GTA_PL.toast(OBF("\187\190\199\195\200\122\200\187\201\122\202\201\190\191\122\199\195\204\187\204\122\191\199\122\201\207\206\204\201\122\187\190\199\195\200"), Color3.fromRGB(220, 80, 80)) end end)
            return
        end
        GTA_PL.punishSelf(how or OBF("\199\195\204\201\207\122\191\199\122\202\204\201\206\191\193\195\190\201"))
    end
    function GTA_PL.guardPlayer(p)  
        if typeof(p) ~= OBF("\163\200\205\206\187\200\189\191") or not p:IsA(OBF("\170\198\187\211\191\204")) then return true end
        if GTA_PL.canHit(p) then return true end
        GTA_PL.violation(p, OBF("\206\191\200\206\201\207\122\199\195\204\187\204\122\191\199\122") .. p.Name)
        return false
    end
    function GTA_PL.guardName(n)
        if type(n) ~= OBF("\205\206\204\195\200\193") or n == "" then return true end
        return GTA_PL.guardPlayer(Plrs:FindFirstChild(n))
    end
    function GTA_PL.checkTyped(q)  
        q = tostring(q or ""):lower()
        if q == "" then return end
        for _, p in ipairs(Plrs:GetPlayers()) do
            if p ~= Plrs.LocalPlayer and not GTA_PL.canHit(p) and (p.Name:lower() == q or p.DisplayName:lower() == q) then
                GTA_PL.violation(p, OBF("\190\195\193\195\206\201\207\122\201\122\200\201\199\191\122\190\191\122") .. p.Name)
                return
            end
        end
    end
    function GTA_PL.names(includeSelf, leaving)
        local t = {}
        for _, p in ipairs(Plrs:GetPlayers()) do
            if p ~= leaving and (includeSelf or p ~= Plrs.LocalPlayer) and (p == Plrs.LocalPlayer or GTA_PL.canHit(p)) then t[#t + 1] = p.Name end
        end
        table.sort(t)
        return t
    end
    GTA_PL.sel = {}
    function GTA_PL.register(dd, includeSelf)  
        if not (dd and dd.Refresh) then return end
        for _, e in ipairs(GTA_PL.list) do if e.dd == dd then return end end
        GTA_PL.list[#GTA_PL.list + 1] = {dd = dd, self = includeSelf or false}
        GTA_PL.sel[#GTA_PL.sel + 1] = dd
        pcall(dd.Refresh, dd, GTA_PL.names(includeSelf or false))
    end
    function GTA_PL.track(dd, includeSelf)  
        if dd and dd.Refresh then
            local known = false
            for _, e in ipairs(GTA_PL.list) do if e.dd == dd then known = true end end
            if not known then
                GTA_PL.list[#GTA_PL.list + 1] = {dd = dd, self = includeSelf}
                GTA_PL.sel[#GTA_PL.sel + 1] = dd
                pcall(dd.Refresh, dd, GTA_PL.names(includeSelf or false))
            end
        end
    end
    function GTA_PL.selectAll(name)  
        local n = 0
        for _, dd in ipairs(GTA_PL.sel) do
            if dd.Has and dd:Has(name) and pcall(dd.Set, dd, name) then n = n + 1 end
        end
        return n
    end
    function GTA_PL.find(q)  
        q = tostring(q or ""):lower()
        if q == "" then return nil end
        GTA_PL.checkTyped(q)
        local best
        for _, p in ipairs(Plrs:GetPlayers()) do
            if p ~= Plrs.LocalPlayer and GTA_PL.canHit(p) then
                local a, b = p.Name:lower(), p.DisplayName:lower()
                if a == q or b == q then return p.Name end
                if not best and (a:find(q, 1, true) or b:find(q, 1, true)) then best = p.Name end
            end
        end
        return best
    end
    local function note(m) pcall(function() redzlib:MakeNotify({Title = OBF("\161\174\155\122\162\207\188"), Text = m, Time = 2}) end) end
    function GTA_PL.pick(name)
        if not name then note(OBF("\170\198\187\211\191\204\122\200\29\253\201\122\191\200\189\201\200\206\204\187\190\201")) return end
        local p = Plrs:FindFirstChild(name)
        if p and not GTA_PL.canHit(p) then
            GTA_PL.violation(p, OBF("\206\191\200\206\201\207\122\205\191\198\191\189\195\201\200\187\204\122") .. name)
            return
        end
        GTA_PL.selectAll(name)
        note(OBF("\173\191\198\191\189\195\201\200\187\190\201\148\122") .. name)
    end
    local TOOL = OBF("\173\191\198\191\189\206\122\170\198\187\211\191\204\122\130\161\174\155\131")
    function GTA_PL.giveSelectTool()
        local lp = Plrs.LocalPlayer
        local bp = lp:FindFirstChildOfClass(OBF("\156\187\189\197\202\187\189\197"))
        if not bp or bp:FindFirstChild(TOOL) or (lp.Character and lp.Character:FindFirstChild(TOOL)) then return end
        local tool = Instance.new(OBF("\174\201\201\198"))
        tool.Name, tool.RequiresHandle, tool.CanBeDropped, tool.ToolTip = TOOL, false, false, OBF("\189\198\195\203\207\191\122\200\207\199\122\202\198\187\211\191\204\122\202\204\187\122\205\191\198\191\189\195\201\200\187\204")
        tool.Activated:Connect(function()
            local node, plr = lp:GetMouse().Target, nil
            while node and node ~= workspace do
