local GTA_FreeCam = {on = false, speed = 40}
do
    local UIS = game:GetService(OBF("\175\205\191\204\163\200\202\207\206\173\191\204\208\195\189\191"))
    local RS = game:GetService(OBF("\172\207\200\173\191\204\208\195\189\191"))
    local CAS = game:GetService(OBF("\157\201\200\206\191\210\206\155\189\206\195\201\200\173\191\204\208\195\189\191"))
    local LP = game:GetService(OBF("\170\198\187\211\191\204\205")).LocalPlayer
    local conn, saved, pitch, yaw, pos
    local KEYS = {Enum.KeyCode.W, Enum.KeyCode.A, Enum.KeyCode.S, Enum.KeyCode.D, Enum.KeyCode.Q, Enum.KeyCode.E, Enum.KeyCode.Space, Enum.KeyCode.LeftShift}
    local function hrp() return LP.Character and LP.Character:FindFirstChild(OBF("\162\207\199\187\200\201\195\190\172\201\201\206\170\187\204\206")) end
    function GTA_FreeCam.set(on)
        on = on and true or false
        if on == GTA_FreeCam.on then return end
        local cam = workspace.CurrentCamera
        if on then
            GTA_FreeCam.on = true
            saved = {type = cam.CameraType, subject = cam.CameraSubject, anchored = hrp() and hrp().Anchored or false}
            local rx, ry = cam.CFrame:ToOrientation()
            pitch, yaw, pos = math.deg(rx), math.deg(ry), cam.CFrame.Position
            if hrp() then hrp().Anchored = true end
            pcall(function()
                CAS:BindActionAtPriority(OBF("\161\174\155\160\204\191\191\157\187\199\173\195\200\197"), function() return Enum.ContextActionResult.Sink end, false, Enum.ContextActionPriority.High.Value + 1, unpack(KEYS))
            end)
            conn = RS.RenderStepped:Connect(function(dt)
                cam = workspace.CurrentCamera
                cam.CameraType = Enum.CameraType.Scriptable
                local rmb = UIS:IsMouseButtonPressed(Enum.UserInputType.MouseButton2)
                UIS.MouseBehavior = rmb and Enum.MouseBehavior.LockCurrentPosition or Enum.MouseBehavior.Default
                if rmb then
                    local d = UIS:GetMouseDelta()
                    yaw = yaw - d.X * 0.25
                    pitch = math.clamp(pitch - d.Y * 0.25, -89, 89)
                end
                local rot = CFrame.Angles(0, math.rad(yaw), 0) * CFrame.Angles(math.rad(pitch), 0, 0)
                local mv = Vector3.new(0, 0, 0)
                if UIS:IsKeyDown(Enum.KeyCode.W) then mv = mv + Vector3.new(0, 0, -1) end
                if UIS:IsKeyDown(Enum.KeyCode.S) then mv = mv + Vector3.new(0, 0, 1) end
                if UIS:IsKeyDown(Enum.KeyCode.A) then mv = mv + Vector3.new(-1, 0, 0) end
                if UIS:IsKeyDown(Enum.KeyCode.D) then mv = mv + Vector3.new(1, 0, 0) end
                if UIS:IsKeyDown(Enum.KeyCode.E) or UIS:IsKeyDown(Enum.KeyCode.Space) then mv = mv + Vector3.new(0, 1, 0) end
                if UIS:IsKeyDown(Enum.KeyCode.Q) then mv = mv + Vector3.new(0, -1, 0) end
                local sp = GTA_FreeCam.speed * (UIS:IsKeyDown(Enum.KeyCode.LeftShift) and 3 or 1)
                pos = pos + (rot * mv) * sp * dt
                cam.CFrame = CFrame.new(pos) * rot
            end)
        else
            GTA_FreeCam.on = false
            if conn then conn:Disconnect(); conn = nil end
            pcall(function() CAS:UnbindAction(OBF("\161\174\155\160\204\191\191\157\187\199\173\195\200\197")) end)
            UIS.MouseBehavior = Enum.MouseBehavior.Default
            if saved then
                cam.CameraType = saved.type or Enum.CameraType.Custom
                if saved.subject then cam.CameraSubject = saved.subject end
                if hrp() then hrp().Anchored = saved.anchored end
            end
        end
    end
end




local GTA_XY = {}
do
    local function clean(s)
        s = tostring(s or "")
        s = s:gsub(OBF("\61\218\230"), ""):gsub(OBF("\61\218\231"), "")
        return (s:gsub(OBF("\184\127\205\133"), ""):gsub(OBF("\127\205\133\126"), ""))
    end
    local function copy(c)
        local n = {}
        for k, v in pairs(c or {}) do n[k] = v end
        return n
    end
    local ICONS = {Carnival = OBF("\74\249\232\251"), You = OBF("\74\249\1\231"), Fun = OBF("\74\249\232\227"), House = OBF("\74\249\233\250"), [OBF("\157\187\204\137\156\201\187\206\137\156\195\197\191")] = OBF("\74\249\244\241"), Teleport = OBF("\74\249\230\218"), [OBF("\174\201\193\193\198\191\122\157\201\204\191")] = OBF("\60\244\243"), People = OBF("\74\249\235\255"), ESP = OBF("\74\249\235\219"), Skin = OBF("\74\249\232\7"), Troll = OBF("\74\249\242\226")}
    local function wrapTab(tab)
        local P = {}
        function P:AddSection(c)
            return tab:AddSection({Name = clean(type(c) == OBF("\206\187\188\198\191") and (c.Name or c[1]) or c)})
        end
        function P:AddParagraph(a, b)
            if type(a) == OBF("\206\187\188\198\191") then
                return tab:AddParagraph({clean(a.Title or a.Name or a[1]), tostring(a.Content or a.Text or a[2] or "")})
            end
            return tab:AddParagraph({clean(a), tostring(b or "")})
        end
        function P:AddLabel(a)
            return tab:AddParagraph({clean(type(a) == OBF("\206\187\188\198\191") and (a.Name or a[1]) or a), ""})
        end
        function P:AddButton(c)
            local n = copy(c); n.Name = clean(n.Name or n[1])
            return tab:AddButton(n)
        end
        function P:AddToggle(c)
            local n = copy(c); n.Name = clean(n.Name or n[1]); n.Default = (c.Default == true)
            return tab:AddToggle(n)
        end
        function P:AddDropdown(c)
            local n = copy(c); n.Name = clean(n.Name or n[1])
            local ready, cb = false, c.Callback
            n.Callback = function(...)
                if not ready then return end   
                if cb then return cb(...) end
            end
            local obj = tab:AddDropdown(n)
            ready = true
            return obj
        end
        function P:AddTextbox(c)
            local n = copy(c); n.Name = clean(n.Name or n[1]); n.ClearText = c.TextDisappear
            return tab:AddTextBox(n)
        end
        P.AddTextBox = P.AddTextbox
        function P:AddSlider(c)
            local n = copy(c); n.Name = clean(n.Name or n[1]); n.Increase = c.Increment or c.Increase or 1
            return tab:AddSlider(n)
        end
        return setmetatable(P, {__index = function(_, k) return tab[k] end})
    end
    function GTA_XY.window()
        local W = {}
        function W:MakeTab(c)
            local name = clean(c.Name or c.Title or c[1])
            return wrapTab(ActiveWindow:MakeTab({Title = name, Icon = ICONS[name] or OBF("\60\218\252")}))
        end
        return W
    end
    GTA_XY.lib = {
        MakeNotification = function(_, c) return redzlib:MakeNotification(c) end,
        Init = function() end,
    }
end





GTA_PL.PS = {}
do
    local PS = GTA_PL.PS
    local Players = game:GetService(OBF("\170\198\187\211\191\204\205"))
    local LP = Players.LocalPlayer
    local RS = game:GetService(OBF("\172\207\200\173\191\204\208\195\189\191"))
    local UIS = game:GetService(OBF("\175\205\191\204\163\200\202\207\206\173\191\204\208\195\189\191"))
    local CoreGui = game:GetService(OBF("\157\201\204\191\161\207\195"))
    local kScanInterval, kGatherTime, kAppearRadius, kReleaseTime = 2.0, 8.0, 18, 2.6
    local kOrbitRadius, kOrbitRadiusVar, kOrbitSpeed, kOrbitSpeedVar, kOrbitHeightVar = 2.6, 1.2, 2.0, 1.0, 2.6
    local kSelfHeightOffset, kVoidY, kVoidSpread, kVoidSpinSpeed = -3.2, -600, 14, 28
    local kVoidTrembleSpeed, kVoidTrembleAmp = 999191991919199199, 0.22
    local kPredictLead, kPredictSmoothing, kPredictMaxLead, kNetworkRate = 0.12, 12, 6, 1 / 20
    local smoothedVel = Vector3.new(0, 0, 0)
    PS.mode, PS.target = OBF("\169\160\160"), nil
    PS.park = OBF("\176\169\163\158")  
    local kTopY, kTopSpin, kFlingSpin = 2500, 55, 80  
    local props, lastScan, connected = {}, 0, false
    local function myRoot() return LP.Character and LP.Character:FindFirstChild(OBF("\162\207\199\187\200\201\195\190\172\201\201\206\170\187\204\206")) end
    local function parkStep(d, dt, kind, spin)
        local r = myRoot()
        if not r then return end
        if kind == OBF("\160\172\169\168\174") then
            d.pos = (r.CFrame * CFrame.new(0, 0, -5)).Position
            local _, ry = r.CFrame:ToOrientation()
            d.angle = ry
        elseif kind == OBF("\174\169\170") then
            d.pos = Vector3.new(r.Position.X, kTopY, r.Position.Z)
            d.angle = (d.angle + (spin or kTopSpin) * dt) % (2 * math.pi)  
        end
    end
    local ui = {}

    local function getRemote(inst)
        if inst:IsA(OBF("\156\187\205\191\170\187\204\206")) or inst:IsA(OBF("\167\201\190\191\198")) then return inst:FindFirstChild(OBF("\173\191\206\157\207\204\204\191\200\206\157\160\204\187\199\191")) end
    end
    local function currentPos(inst)
        if inst:IsA(OBF("\167\201\190\191\198")) then
            local ok, cf = pcall(function() return inst:GetPivot() end)
            if ok and cf then return cf.Position end
            if inst.PrimaryPart then return inst.PrimaryPart.Position end
        elseif inst:IsA(OBF("\156\187\205\191\170\187\204\206")) then
            return inst.Position
        end
    end
    local function scanProps()
        local wanted = OBF("\170\204\201\202") .. LP.Name
        for _, v in ipairs(workspace:GetDescendants()) do
            if not props[v] and v.Name:find(wanted, 1, true) then
                local remote = getRemote(v)
                local pos = remote and currentPos(v)
                if remote and pos then
                    props[v] = {
                        remote = remote, phase = OBF("\176\169\163\158"), phaseStart = tick(), phaseFrom = pos, pos = pos,
                        angle = math.random() * math.pi * 2,
                        radius = kOrbitRadius + math.random() * kOrbitRadiusVar,
                        speed = (kOrbitSpeed + math.random() * kOrbitSpeedVar) * (math.random() < 0.5 and -1 or 1),
                        heightOff = (math.random() - 0.5) * kOrbitHeightVar,
                        voidAngle = math.random() * math.pi * 2, voidRadius = math.random() * kVoidSpread,
                        lastNet = 0,
                    }
                end
            end
        end
    end
    local function stepProp(d, t, dt, shouldShow, center, hardTP)
        if shouldShow and center then
            if d.phase == OBF("\176\169\163\158") then
                d.phase, d.phaseStart, d.phaseFrom = (hardTP and OBF("\169\172\156\163\174") or OBF("\161\155\174\162\159\172")), t, d.pos
                if not hardTP then
                    d.startRadius = kAppearRadius
                    d.startHeight = (math.random() - 0.5) * kOrbitHeightVar
                    d.angle = math.random() * math.pi * 2
                end
            end
        elseif d.phase == OBF("\169\172\156\163\174") or d.phase == OBF("\161\155\174\162\159\172") then
            d.phase, d.phaseStart, d.phaseFrom = OBF("\172\159\166\159\155\173\159"), t, d.pos
            local vc = center or d.pos
            d.releaseTarget = Vector3.new(vc.X + math.cos(d.voidAngle) * d.voidRadius, kVoidY, vc.Z + math.sin(d.voidAngle) * d.voidRadius)
            if hardTP then  
                d.phase = OBF("\176\169\163\158")
                d.pos = d.releaseTarget
            end
        end
        if d.phase == OBF("\176\169\163\158") then d.angle = d.angle + kVoidSpinSpeed * dt else d.angle = d.angle + d.speed * dt end
        if center and d.phase == OBF("\161\155\174\162\159\172") then
            local p = math.clamp((t - d.phaseStart) / kGatherTime, 0, 1)
            local ease = 1 - (1 - p) * (1 - p)
            local r = d.startRadius + (d.radius - d.startRadius) * ease
            local h = d.startHeight + (d.heightOff - d.startHeight) * ease
            d.pos = center + Vector3.new(math.cos(d.angle) * r, h, math.sin(d.angle) * r)
            if p >= 1 then d.phase = OBF("\169\172\156\163\174") end
        elseif center and d.phase == OBF("\169\172\156\163\174") then
            d.pos = center + Vector3.new(math.cos(d.angle) * d.radius, d.heightOff, math.sin(d.angle) * d.radius)
        elseif d.phase == OBF("\172\159\166\159\155\173\159") and d.releaseTarget then
            local p = math.clamp((t - d.phaseStart) / kReleaseTime, 0, 1)
            local wobble = Vector3.new(math.cos(d.angle), 0, math.sin(d.angle)) * (d.radius * (1 - p) * 0.6)
            d.pos = d.phaseFrom:Lerp(d.releaseTarget, p) + wobble
            if p >= 1 then d.phase = OBF("\176\169\163\158") d.pos = d.releaseTarget end
        end
        if d.phase == OBF("\176\169\163\158") then
            local tt = t * kVoidTrembleSpeed
            d.pos = d.pos + Vector3.new(math.sin(tt) * kVoidTrembleAmp, math.sin(tt * 1.3) * kVoidTrembleAmp, math.cos(tt * 0.7) * kVoidTrembleAmp)
        end
    end
    local function connect()
        if connected then return end
        connected = true
        RS.Heartbeat:Connect(function(dt)
            local t = tick()
            if PS.mode ~= OBF("\169\160\160") and t - lastScan > kScanInterval then lastScan = t scanProps() end
            local center, shouldShow, hardTP = nil, false, false
            local seatSeated = false
            if (PS.mode == OBF("\173\159\155\174") or PS.mode == OBF("\160\166\163\168\161")) and PS.target then
                local h = PS.target.Character and PS.target.Character:FindFirstChildOfClass(OBF("\162\207\199\187\200\201\195\190"))
                seatSeated = h ~= nil and h.Sit
                if PS.mode == OBF("\160\166\163\168\161") and seatSeated then PS.flingUp = true end
                if PS.mode == OBF("\173\159\155\174") then
                    if seatSeated then PS.standSince = nil
                    elseif PS.hadSeat then
                        PS.standSince = PS.standSince or t
                        if t - PS.standSince > 1.5 then PS.setMode(OBF("\169\160\160")) end  
                    end
                end
            end
            if PS.mode == OBF("\173\159\166\160") then
                local root = LP.Character and LP.Character:FindFirstChild(OBF("\162\207\199\187\200\201\195\190\172\201\201\206\170\187\204\206"))
                if root then center, shouldShow = root.Position + Vector3.new(0, kSelfHeightOffset, 0), true end
            elseif PS.mode == OBF("\174\155\172\161\159\174") and PS.target then
                local char = PS.target.Character
                local hum = char and char:FindFirstChildOfClass(OBF("\162\207\199\187\200\201\195\190"))
                local root = char and char:FindFirstChild(OBF("\162\207\199\187\200\201\195\190\172\201\201\206\170\187\204\206"))
                shouldShow = hum ~= nil and hum.Health > 0 and not hum.Sit
                hardTP = true
                if shouldShow and root then
                    local rv = root.AssemblyLinearVelocity or Vector3.new()
                    smoothedVel = smoothedVel:Lerp(rv, math.clamp(dt * kPredictSmoothing, 0, 1))
                    local lead = Vector3.new(smoothedVel.X, 0, smoothedVel.Z) * kPredictLead
                    if lead.Magnitude > kPredictMaxLead then lead = lead.Unit * kPredictMaxLead end
                    center = root.Position + lead
                else
                    smoothedVel = Vector3.new()
                end
            end
            local tracked = 0
            for inst, d in pairs(props) do
                if not inst.Parent then
                    props[inst] = nil
                else
                    tracked = tracked + 1
                    if PS.mode == OBF("\160\166\163\168\161") then
                        if PS.flingUp then
                            d.phase = OBF("\176\169\163\158"); parkStep(d, dt, OBF("\174\169\170"), kFlingSpin)  
                        else
                            local tr = PS.target and PS.target.Character and PS.target.Character:FindFirstChild(OBF("\162\207\199\187\200\201\195\190\172\201\201\206\170\187\204\206"))
                            d.phase = OBF("\169\172\156\163\174")
                            if tr then d.pos = tr.Position end
                            d.angle = d.angle + 5000 * dt  
                        end
                    elseif PS.mode == OBF("\174\169\170\160\166\163\168\161") then
                        d.phase = OBF("\176\169\163\158"); parkStep(d, dt, OBF("\174\169\170"))
                    elseif PS.mode == OBF("\173\159\155\174") then
                        if seatSeated then
                            PS.hadSeat = true
                            d.phase = OBF("\160\172\169\168\174"); parkStep(d, dt, OBF("\160\172\169\168\174"))
                        elseif not PS.hadSeat then
                            local tr = PS.target and PS.target.Character and PS.target.Character:FindFirstChild(OBF("\162\207\199\187\200\201\195\190\172\201\201\206\170\187\204\206"))
                            d.phase = OBF("\169\172\156\163\174")
                            if tr then d.pos = tr.Position end  
                        else
                            local r = myRoot()
                            d.phase = OBF("\176\169\163\158")
                            if r then
                                local tt = t * kVoidTrembleSpeed
                                d.pos = Vector3.new(r.Position.X, kVoidY, r.Position.Z) + Vector3.new(math.sin(tt) * kVoidTrembleAmp, math.sin(tt * 1.3) * kVoidTrembleAmp, math.cos(tt * 0.7) * kVoidTrembleAmp)
                            end
                        end
                    else
                        stepProp(d, t, dt, shouldShow, center, hardTP)
                        if PS.mode == OBF("\174\155\172\161\159\174") and d.phase == OBF("\176\169\163\158") and PS.park ~= OBF("\176\169\163\158") then parkStep(d, dt, PS.park) end
                    end
                    if t - d.lastNet >= kNetworkRate then
                        d.lastNet = t
                        local cf = CFrame.new(d.pos) * CFrame.Angles(0, d.angle, 0)
                        local remote = d.remote
                        task.spawn(function() pcall(function() remote:InvokeServer(cf) end) end)
                    end
                end
            end
            if ui.status then ui.status.Text = OBF("\170\172\169\170\173\148\122") .. tracked .. OBF("\122\174\172\155\157\165\159\158\122\214\122\167\169\158\159\148\122") .. PS.mode end
        end)
    end
    function PS.setMode(m)
        PS.mode = m
        PS.hadSeat, PS.flingUp, PS.standSince = false, false, nil
        if m ~= OBF("\169\160\160") then lastScan = 0 connect() end
        if ui.selfBtn then
            ui.selfBtn.Text = OBF("\173\177\155\166\166\169\177\122\167\159\148\122") .. ((m == OBF("\173\159\166\160")) and OBF("\169\168") or OBF("\169\160\160"))
            ui.selfBtn.TextColor3 = (m == OBF("\173\159\166\160")) and Color3.fromRGB(255, 210, 0) or Color3.fromRGB(255, 230, 130)
            ui.targetBtn.Text = OBF("\160\169\166\166\169\177\122\174\155\172\161\159\174\148\122") .. ((m == OBF("\174\155\172\161\159\174")) and OBF("\169\168") or OBF("\169\160\160"))
            ui.targetBtn.TextColor3 = (m == OBF("\174\155\172\161\159\174")) and Color3.fromRGB(255, 210, 0) or Color3.fromRGB(255, 230, 130)
        end
    end
    function PS.setTarget(plr)
        if plr and not GTA_PL.canHit(plr) then
            GTA_PL.violation(plr, OBF("\206\191\200\206\201\207\122\205\191\198\191\189\195\201\200\187\204\122") .. plr.Name)
            plr = nil
        end
        PS.target = plr
        if ui.targetBox then ui.targetBox.Text = plr and (OBF("\174\155\172\161\159\174\148\122") .. plr.DisplayName) or OBF("\174\155\172\161\159\174\148\122\168\169\168\159\122\130\157\166\163\157\165\122\173\159\166\159\157\174\131") end
        if not plr and (PS.mode == OBF("\174\155\172\161\159\174") or PS.mode == OBF("\173\159\155\174")) then PS.setMode(OBF("\169\160\160")) end
    end
    Players.PlayerRemoving:Connect(function(plr) if plr == PS.target then PS.setTarget(nil) end end)

    
