        end)
        local selecting = false
        selectBtn.MouseButton1Click:Connect(function()
            selecting = not selecting
            selectBtn.Text = OBF("\157\166\163\157\165\122\173\159\166\159\157\174\148\122") .. (selecting and OBF("\169\168") or OBF("\169\160\160"))
            selectBtn.TextColor3 = selecting and YELLOW or TXT
        end)
        local mouse = LP:GetMouse()
        UIS.InputBegan:Connect(function(input, gp)
            if gp or not selecting or not sg.Parent then return end
            if input.UserInputType ~= Enum.UserInputType.MouseButton1 and input.UserInputType ~= Enum.UserInputType.Touch then return end
            task.spawn(function()
                RS.RenderStepped:Wait()
                local node, plr = mouse.Target, nil
                while node and node ~= workspace do
                    plr = Players:GetPlayerFromCharacter(node)
                    if plr then break end
                    node = node.Parent
                end
                if not plr or plr == LP then PS.setTarget(nil) else PS.setTarget(plr) end
            end)
        end)
    end
end




