    local NoCollide = (function()
        local NC_Players     = game:GetService(OBF("\170\198\187\211\191\204\205"))
        local NC_RunService  = game:GetService(OBF("\172\207\200\173\191\204\208\195\189\191"))
        local NC_LocalPlayer = NC_Players.LocalPlayer

        local ENABLED         = false
        local RESCAN_INTERVAL = 2

        local originals      = {}
        local characterParts = {}
        local characterConns = {}

        local removeCharacter

        local function addCharacter(c)
            if not c or not c:IsA(OBF("\167\201\190\191\198")) then return end
            if c == NC_LocalPlayer.Character then return end
            if characterParts[c] then return end

            local list = {}
            characterParts[c] = list

            local function collect(descendant)
                if descendant:IsA(OBF("\156\187\205\191\170\187\204\206")) then
                    list[#list + 1] = descendant
                end
            end

            for _, descendant in ipairs(c:GetDescendants()) do
                collect(descendant)
            end

            characterConns[c] = {
                c.DescendantAdded:Connect(collect),

                c.DescendantRemoving:Connect(function(descendant)
                    if descendant:IsA(OBF("\156\187\205\191\170\187\204\206")) then
                        local index = table.find(list, descendant)
                        if index then
                            table.remove(list, index)
                        end
                        originals[descendant] = nil
                    end
                end),

                c.AncestryChanged:Connect(function()
                    if not c.Parent then
                        removeCharacter(c)
                    end
                end),
            }
        end

        removeCharacter = function(c)
            local conns = characterConns[c]
            if conns then
                for i = 1, #conns do
                    conns[i]:Disconnect()
                end
                characterConns[c] = nil
            end

            local list = characterParts[c]
            if list then
                for i = 1, #list do
                    originals[list[i]] = nil
                end
                characterParts[c] = nil
            end
        end

        local function enforce()
            for _, list in pairs(characterParts) do
                for i = 1, #list do
                    local part = list[i]
                    if part.CanCollide then
                        originals[part] = true
                        part.CanCollide = false
                    elseif originals[part] == nil then
                        originals[part] = false
                    end
                end
            end
        end

        local function restoreAll()
            for part, original in pairs(originals) do
                if part.Parent and part.CanCollide ~= original then
                    part.CanCollide = original
                end
            end
            table.clear(originals)
        end

        local function setEnabled(state)
            ENABLED = state and true or false
            if not ENABLED then
                restoreAll()
            end
        end

        
        NC_RunService.Stepped:Connect(function()
            if not ENABLED then return end
            enforce()
        end)

        local function scanWorkspace()
            for _, descendant in ipairs(workspace:GetDescendants()) do
                if descendant:IsA(OBF("\162\207\199\187\200\201\195\190")) then
                    addCharacter(descendant.Parent)
                end
            end
        end

        workspace.DescendantAdded:Connect(function(descendant)
            if descendant:IsA(OBF("\162\207\199\187\200\201\195\190")) then
                addCharacter(descendant.Parent)
            end
        end)

        task.spawn(function()
            while true do
                task.wait(RESCAN_INTERVAL)

                local dead
                for c in pairs(characterParts) do
                    if not c.Parent then
                        dead = dead or {}
                        dead[#dead + 1] = c
                    end
                end
                if dead then
                    for i = 1, #dead do
                        removeCharacter(dead[i])
                    end
                end

                for _, child in ipairs(workspace:GetChildren()) do
                    if child:IsA(OBF("\167\201\190\191\198")) and child:FindFirstChildOfClass(OBF("\162\207\199\187\200\201\195\190")) then
                        addCharacter(child)
                    end
                end
            end
        end)

        scanWorkspace()

        return {
            Enable  = function() setEnabled(true)  end,
            Disable = function() setEnabled(false) end,
        }
    end)()

    
    
    
    
    
    local Fly = (function()
        local enabled = false
        local speed   = CONFIG.FlySpeed
        local conn, bv, bg
        local saved   = {} 

        local function destroyForces()
            if bv then bv:Destroy() bv = nil end
            if bg then bg:Destroy() bg = nil end
        end

        local function ensureForces()
            if not bv or bv.Parent ~= rootPart then
                if bv then bv:Destroy() end
                bv = Instance.new(OBF("\156\201\190\211\176\191\198\201\189\195\206\211"))
                bv.MaxForce = Vector3.new(1e8, 1e8, 1e8)
                bv.Velocity = Vector3.zero
                bv.Parent   = rootPart
            end
            if not bg or bg.Parent ~= rootPart then
                if bg then bg:Destroy() end
                bg = Instance.new(OBF("\156\201\190\211\161\211\204\201"))
                bg.MaxTorque = Vector3.new(1e8, 1e8, 1e8)
                bg.P         = 20000
                bg.CFrame    = rootPart.CFrame
                bg.Parent    = rootPart
            end
        end

        local function step()
            if not enabled or not character or not humanoid or not humanoid.Parent
                or not rootPart or not rootPart.Parent then
                return
            end

            for _, p in ipairs(character:GetDescendants()) do
                if p:IsA(OBF("\156\187\205\191\170\187\204\206")) and p.CanCollide then
                    if saved[p] == nil then saved[p] = true end
                    p.CanCollide = false
                end
            end

            humanoid.PlatformStand = true
            ensureForces()

            local cf  = Camera.CFrame
            local md  = humanoid.MoveDirection
            local dir = Vector3.zero

            if md.Magnitude > 0 then
                local flatL = Vector3.new(cf.LookVector.X, 0, cf.LookVector.Z)
                local flatR = Vector3.new(cf.RightVector.X, 0, cf.RightVector.Z)
                flatL = flatL.Magnitude > 0 and flatL.Unit or Vector3.zero
                flatR = flatR.Magnitude > 0 and flatR.Unit or Vector3.zero
                dir = cf.LookVector * md:Dot(flatL) + cf.RightVector * md:Dot(flatR)
            end

            if UserInputService:IsKeyDown(Enum.KeyCode.Space) then
                dir += Vector3.yAxis
            end
            if UserInputService:IsKeyDown(Enum.KeyCode.LeftShift)
                or UserInputService:IsKeyDown(Enum.KeyCode.Q) then
                dir -= Vector3.yAxis
            end

            bv.Velocity = dir.Magnitude > 0 and dir.Unit * speed or Vector3.zero
            bg.CFrame   = CFrame.new(rootPart.Position, rootPart.Position + cf.LookVector)
        end

        return {
            Enable = function()
                if enabled then return end
                enabled = true
                conn = RunService.RenderStepped:Connect(step)
            end,
            Disable = function()
                if not enabled then return end
                enabled = false
                if conn then conn:Disconnect() conn = nil end
                destroyForces()
                for p, orig in pairs(saved) do
                    if p.Parent then p.CanCollide = orig end
                end
                table.clear(saved)
                if humanoid and humanoid.Parent then
                    humanoid.PlatformStand = false
                end
            end,
            SetSpeed = function(n) speed = n end,
            GetSpeed = function() return speed end,
        }
    end)()

    
    
    
    local ownCharDescConn = nil
    local sitEventConn    = nil

    local function isTrackedPart(obj)
        return (obj:IsA(OBF("\156\187\205\191\170\187\204\206")) or obj:IsA(OBF("\158\191\189\187\198")) or obj:IsA(OBF("\174\191\210\206\207\204\191")))
    end

    local function setupCharacter()
        character = LocalPlayer.Character or LocalPlayer.CharacterAdded:Wait()
        humanoid  = character:WaitForChild(OBF("\162\207\199\187\200\201\195\190"))
        rootPart  = character:WaitForChild(OBF("\162\207\199\187\200\201\195\190\172\201\201\206\170\187\204\206"))

        task.wait(0.2)

        parts = {}
        for _, obj in pairs(character:GetDescendants()) do
            if isTrackedPart(obj) and obj.Transparency == 0 then
                table.insert(parts, obj)
            end
        end

        if ownCharDescConn then ownCharDescConn:Disconnect() end
        ownCharDescConn = character.DescendantAdded:Connect(function(desc)
            if not isTrackedPart(desc) then return end
            if desc.Transparency ~= 0 then return end
            table.insert(parts, desc)
            if invisible then
                desc.Transparency = 0.5
            end
        end)

        if sitEventConn then sitEventConn:Disconnect() end
        sitEventConn = humanoid.Seated:Connect(function()
            if updateToggleVisual then
                updateToggleVisual(State.Invisible, true)
            end
        end)
    end

    
    
    
    local function applyHidden(state, nudge)
        invisible = state

        for _, part in pairs(parts) do
            if part and part.Parent then
                part.Transparency = invisible and 0.5 or 0
            end
        end

        if invisible and nudge and rootPart and rootPart.Parent then
            rootPart.CFrame = rootPart.CFrame * CFrame.new(0, -0.3, 0)
        end
    end

    local function recomputeHidden(nudge)
        applyHidden(State.Invisible or State.Fly, nudge)
    end

    local function setInvisible(state)
        State.Invisible = state
        recomputeHidden(state)
    end

    
    
    
    local function create(className, props, children)
        local instance = Instance.new(className)
        local parent

        for key, value in pairs(props or {}) do
            if key == OBF("\170\187\204\191\200\206") then
                parent = value
            else
                instance[key] = value
            end
        end

        for _, child in ipairs(children or {}) do
            child.Parent = instance
        end

        if parent then
            instance.Parent = parent
        end

        return instance
    end

    local function tween(instance, properties, duration, style, direction)
        local info = TweenInfo.new(
            duration or 0.2,
            style or Enum.EasingStyle.Quad,
            direction or Enum.EasingDirection.Out
        )
        local animation = TweenService:Create(instance, info, properties)
        animation:Play()
        return animation
    end

    local function setInstant(instance, properties)
        for key, value in pairs(properties) do
            instance[key] = value
        end
    end

    local function addFeedback(button, config)
        config = config or {}

        local scale = create(OBF("\175\163\173\189\187\198\191"), { Scale = 1, Parent = button })

        local normalBg = config.Normal or button.BackgroundColor3
        local hoverBg  = config.Hover or normalBg
        local targets  = config.Targets or {}

        local function applyHover(isHovered)
            local duration = isHovered and TWEEN.Hover or (TWEEN.Hover + 0.03)
            tween(button, { BackgroundColor3 = isHovered and hoverBg or normalBg }, duration)
            for _, entry in ipairs(targets) do
                local object, property = entry[1], entry[2]
                local normalValue, hoverValue = entry[3], entry[4]
                tween(object, { [property] = isHovered and hoverValue or normalValue }, duration)
            end
        end

        button.MouseEnter:Connect(function() applyHover(true) end)
        button.MouseLeave:Connect(function()
            applyHover(false)
            tween(scale, { Scale = 1 }, 0.16, Enum.EasingStyle.Back, Enum.EasingDirection.Out)
        end)
        button.MouseButton1Down:Connect(function()
            tween(scale, { Scale = 0.88 }, TWEEN.Press)
        end)
        button.MouseButton1Up:Connect(function()
            tween(scale, { Scale = 1 }, 0.16, Enum.EasingStyle.Back, Enum.EasingDirection.Out)
        end)
        button.InputBegan:Connect(function(input)
            if input.UserInputType == Enum.UserInputType.Touch then
                tween(scale, { Scale = 0.88 }, TWEEN.Press)
            end
        end)
        button.InputEnded:Connect(function(input)
            if input.UserInputType == Enum.UserInputType.Touch then
                tween(scale, { Scale = 1 }, 0.16, Enum.EasingStyle.Back, Enum.EasingDirection.Out)
            end
        end)

        return scale
    end

    
    
    
