local function ForcePart(v)
    if v:IsA(OBF("\170\187\204\206")) and not v.Anchored and not v.Parent:FindFirstChild(OBF("\162\207\199\187\200\201\195\190")) and not v.Parent:FindFirstChild(OBF("\162\191\187\190")) and v.Name ~= OBF("\162\187\200\190\198\191") then
        for _, x in next, v:GetChildren() do
            if x:IsA(OBF("\156\201\190\211\155\200\193\207\198\187\204\176\191\198\201\189\195\206\211")) or x:IsA(OBF("\156\201\190\211\160\201\204\189\191")) or x:IsA(OBF("\156\201\190\211\161\211\204\201")) or x:IsA(OBF("\156\201\190\211\170\201\205\195\206\195\201\200")) or x:IsA(OBF("\156\201\190\211\174\194\204\207\205\206")) or x:IsA(OBF("\156\201\190\211\176\191\198\201\189\195\206\211")) or x:IsA(OBF("\172\201\189\197\191\206\170\204\201\202\207\198\205\195\201\200")) then
                x:Destroy()
            end
        end
        if v:FindFirstChild(OBF("\155\206\206\187\189\194\199\191\200\206")) then
            v:FindFirstChild(OBF("\155\206\206\187\189\194\199\191\200\206")):Destroy()
        end
        if v:FindFirstChild(OBF("\155\198\195\193\200\170\201\205\195\206\195\201\200")) then
            v:FindFirstChild(OBF("\155\198\195\193\200\170\201\205\195\206\195\201\200")):Destroy()
        end
        if v:FindFirstChild(OBF("\174\201\204\203\207\191")) then
            v:FindFirstChild(OBF("\174\201\204\203\207\191")):Destroy()
        end
        v.CanCollide = false
        
        local Torque = Instance.new(OBF("\174\201\204\203\207\191"), v)
        Torque.Torque = Vector3.new(1000000, 1000000, 1000000)
        local AlignPosition = Instance.new(OBF("\155\198\195\193\200\170\201\205\195\206\195\201\200"), v)
        local Attachment2 = Instance.new(OBF("\155\206\206\187\189\194\199\191\200\206"), v)
        Torque.Attachment0 = Attachment2
        AlignPosition.MaxForce = math.huge
        AlignPosition.MaxVelocity = math.huge
        AlignPosition.Responsiveness = 500
        AlignPosition.Attachment0 = Attachment2
        AlignPosition.Attachment1 = Attachment1
    end
end

local function toggleBlackHole()
    blackHoleActive = not blackHoleActive
    if blackHoleActive then
        for _, v in next, Workspace:GetDescendants() do
            ForcePart(v)
        end

        Workspace.DescendantAdded:Connect(function(v)
            if blackHoleActive then
                ForcePart(v)
            end
        end)

        spawn(function()
            while blackHoleActive and RunService.RenderStepped:Wait() do
                angle = angle + math.rad(2)

                local offsetX = math.cos(angle) * radius
                local offsetZ = math.sin(angle) * radius

                Attachment1.WorldCFrame = humanoidRootPart.CFrame * CFrame.new(offsetX, 0, offsetZ)
            end
        end)
    else
        Attachment1.WorldCFrame = CFrame.new(0, -1000, 0)
    end
end

