local function ForcePart(v)
	if v:IsA(OBF("\156\187\205\191\170\187\204\206")) and not v.Anchored and not v.Parent:FindFirstChildOfClass(OBF("\162\207\199\187\200\201\195\190")) and not v.Parent:FindFirstChild(OBF("\162\191\187\190")) and v.Name ~= OBF("\162\187\200\190\198\191") then
		for _, x in ipairs(v:GetChildren()) do
			if x:IsA(OBF("\156\201\190\211\167\201\208\191\204")) or x:IsA(OBF("\172\201\189\197\191\206\170\204\201\202\207\198\205\195\201\200")) then
				x:Destroy()
			end
		end
		if v:FindFirstChild(OBF("\155\206\206\187\189\194\199\191\200\206")) then
			v:FindFirstChild(OBF("\155\206\206\187\189\194\199\191\200\206")):Destroy()
		end
		if v:FindFirstChild(OBF("\155\198\195\193\200\170\201\205\195\206\195\201\200")) then
			v:FindFirstChild(OBF("\155\198\195\193\200\170\201\205\195\206\195\201\200")):Destroy()
		end
		if v:FindFirstChild(OBF("\174\201\204\203\207\191")) then
			v:FindFirstChild(OBF("\174\201\204\203\207\191")):Destroy()
		end
		v.CanCollide = false
		local Torque = Instance.new(OBF("\174\201\204\203\207\191"), v)
		Torque.Torque = Vector3.new(100000, 100000, 100000)
		local AlignPosition = Instance.new(OBF("\155\198\195\193\200\170\201\205\195\206\195\201\200"), v)
		local Attachment2 = Instance.new(OBF("\155\206\206\187\189\194\199\191\200\206"), v)
		Torque.Attachment0 = Attachment2
		AlignPosition.MaxForce = math.huge
		AlignPosition.MaxVelocity = math.huge
		AlignPosition.Responsiveness = 200
		AlignPosition.Attachment0 = Attachment2
		AlignPosition.Attachment1 = Attachment1
	end
end

local blackHoleActive = false
local DescendantAddedConnection

local function toggleBlackHole()
	blackHoleActive = not blackHoleActive
	if blackHoleActive then
		Button.Text = OBF("\156\204\195\200\193\122\170\187\204\206\205\122\214\122\169\200")
		for _, v in ipairs(Workspace:GetDescendants()) do
			ForcePart(v)
		end

		DescendantAddedConnection = Workspace.DescendantAdded:Connect(function(v)
			if blackHoleActive then
				ForcePart(v)
			end
		end)

		spawn(function()
			while blackHoleActive and RunService.RenderStepped:Wait() do
				Attachment1.WorldCFrame = humanoidRootPart.CFrame
			end
		end)
	else
		Button.Text = OBF("\156\204\195\200\193\122\170\187\204\206\205\122\214\122\169\192\192")
		if DescendantAddedConnection then
			DescendantAddedConnection:Disconnect()
		end
	end
end

local function getPlayer(name)
	GTA_PL.checkTyped(name) local lowerName = string.lower(name)
	for _, p in pairs(GTA_PL.filter(Players:GetPlayers())) do
		local lowerPlayer = string.lower(p.Name)
		if string.find(lowerPlayer, lowerName) then
			return p
		elseif string.find(string.lower(p.DisplayName), lowerName) then
			return p
		end
	end
end

