local function changeColor(color)
    local args = { color }
    game:GetService(OBF("\172\191\202\198\195\189\187\206\191\190\173\206\201\204\187\193\191")):WaitForChild(OBF("\172\191\199\201\206\191\205")):WaitForChild(OBF("\157\194\187\200\193\191\156\201\190\211\157\201\198\201\204")):FireServer(unpack(args))
end

local function toggleRGBCharacter(enabled)
    rgbEnabled = enabled
    if rgbEnabled then
        while rgbEnabled do
            for _, color in ipairs(colors) do
                if not rgbEnabled then return end
                changeColor(color)
                wait(0.5)
            end
        end
    end
end

