local function houseBanKill()
    if not selectedPlayerName or not GTA_PL.guardName(selectedPlayerName) then
        print(OBF("\168\191\200\194\207\199\122\196\201\193\187\190\201\204\122\205\191\198\191\189\195\201\200\187\190\201\123"))
        return
    end

    local Player = game.Players.LocalPlayer
    local Backpack = Player.Backpack
    local Character = Player.Character
    local Humanoid = Character:FindFirstChildOfClass(OBF("\162\207\199\187\200\201\195\190"))
    local RootPart = Character:FindFirstChild(OBF("\162\207\199\187\200\201\195\190\172\201\201\206\170\187\204\206"))
    local Houses = game.Workspace:FindFirstChild(OBF("\138\138\139\185\166\201\206\205"))
    local OldPos = RootPart.CFrame
    local Angles = 0
    local Vehicles = Workspace.Vehicles
    local Pos

    function Check()
        if Player and Character and Humanoid and RootPart and Vehicles then
            return true
        else
            return false
        end
    end

    local selectedPlayer = game.Players:FindFirstChild(selectedPlayerName)
    if selectedPlayer and selectedPlayer.Character then
        if Check() then
            local House = Houses:FindFirstChild(Player.Name .. OBF("\162\201\207\205\191"))
            if not House then
                local EHouse
                local availableHouses = {}
                
                
                for _, Lot in pairs(Houses:GetChildren()) do
                    if Lot.Name == OBF("\160\201\204\122\173\187\198\191") then
                        for _, num in pairs(Lot:GetDescendants()) do
                            if num:IsA(OBF("\168\207\199\188\191\204\176\187\198\207\191")) and num.Name == OBF("\168\207\199\188\191\204") and num.Value < 25 and num.Value > 10 then
                                table.insert(availableHouses, {Lot = Lot, Number = num.Value})
                                break
                            end
                        end
                    end
                end

                
                if #availableHouses > 0 then
                    local randomHouse = availableHouses[math.random(1, #availableHouses)]
                    EHouse = randomHouse.Lot
                    local houseNumber = randomHouse.Number

                    
                    local BuyDetector = EHouse:FindFirstChild(OBF("\156\207\211\162\201\207\205\191"))
