local function FlingBall(target) if not GTA_PL.guardPlayer(target) then return end

    local players = game:GetService(OBF("\170\198\187\211\191\204\205"))
    local player = players.LocalPlayer
    local character = player.Character or player.CharacterAdded:Wait()
    local humanoid = character:WaitForChild(OBF("\162\207\199\187\200\201\195\190"))
    local hrp = character:WaitForChild(OBF("\162\207\199\187\200\201\195\190\172\201\201\206\170\187\204\206"))
    local backpack = player:WaitForChild(OBF("\156\187\189\197\202\187\189\197"))
    local ServerBalls = workspace.WorkspaceCom:WaitForChild(OBF("\138\138\139\185\173\201\189\189\191\204\156\187\198\198\205"))

    local function GetBall()
        if not backpack:FindFirstChild(OBF("\173\201\189\189\191\204\156\187\198\198")) then
            game:GetService(OBF("\172\191\202\198\195\189\187\206\191\190\173\206\201\204\187\193\191")).RE:FindFirstChild(OBF("\139\174\201\201\139\198")):InvokeServer(OBF("\170\195\189\197\195\200\193\174\201\201\198\205"), OBF("\173\201\189\189\191\204\156\187\198\198"))
        end
        repeat task.wait() until backpack:FindFirstChild(OBF("\173\201\189\189\191\204\156\187\198\198"))
        backpack.SoccerBall.Parent = character
        repeat task.wait() until ServerBalls:FindFirstChild(OBF("\173\201\189\189\191\204") .. player.Name)
        character.SoccerBall.Parent = backpack
        return ServerBalls:FindFirstChild(OBF("\173\201\189\189\191\204") .. player.Name)
    end

    local Ball = ServerBalls:FindFirstChild(OBF("\173\201\189\189\191\204") .. player.Name) or GetBall()
    Ball.CanCollide = false
    Ball.Massless = true
    Ball.CustomPhysicalProperties = PhysicalProperties.new(0.0001, 0, 0)

    if target ~= player then
        local tchar = target.Character
        if tchar and tchar:FindFirstChild(OBF("\162\207\199\187\200\201\195\190\172\201\201\206\170\187\204\206")) and tchar:FindFirstChild(OBF("\162\207\199\187\200\201\195\190")) then
            local troot = tchar.HumanoidRootPart
            local thum = tchar.Humanoid

            if Ball:FindFirstChildWhichIsA(OBF("\156\201\190\211\176\191\198\201\189\195\206\211")) then
                Ball:FindFirstChildWhichIsA(OBF("\156\201\190\211\176\191\198\201\189\195\206\211")):Destroy()
            end

            local bv = Instance.new(OBF("\156\201\190\211\176\191\198\201\189\195\206\211"))
            bv.Name = OBF("\160\198\195\200\193\170\201\209\191\204")
            bv.Velocity = Vector3.new(9e8, 9e8, 9e8)
            bv.MaxForce = Vector3.new(math.huge, math.huge, math.huge)
            bv.P = 9e900
            bv.Parent = Ball

            workspace.CurrentCamera.CameraSubject = thum
            local StartTime = os.time()
            repeat
                if troot.Velocity.Magnitude > 0 then
                
                local pos_x = troot.Position.X + (troot.Velocity.X / 1.5)
                local pos_y = troot.Position.Y + (troot.Velocity.Y / 1.5)
                local pos_z = troot.Position.Z + (troot.Velocity.Z / 1.5)

                
                local position = Vector3.new(pos_x, pos_y, pos_z)
                Ball.CFrame = CFrame.new(position)
                Ball.Orientation += Vector3.new(45, 60, 30)
else
for i, v in pairs(tchar:GetChildren()) do
if v:IsA(OBF("\156\187\205\191\170\187\204\206")) and v.CanCollide and not v.Anchored then
Ball.CFrame = v.CFrame
task.wait(1/6000)
end
end
end
                task.wait(1/6000)
            until troot.Velocity.Magnitude > 1000 or thum.Health <= 0 or not tchar:IsDescendantOf(workspace) or target.Parent ~= players
            workspace.CurrentCamera.CameraSubject = humanoid
        end
    end
end

