local ControlledDoors = {}


local function SetupPart(part)
	if not part:IsA(OBF("\156\187\205\191\170\187\204\206")) or part.Anchored or not string.find(part.Name, OBF("\158\201\201\204")) then return end
	if part:FindFirstChild(OBF("\161\174\155\185\155\206\206\187\189\194\191\190")) then return end

	part.CanCollide = false

	for _, obj in ipairs(part:GetChildren()) do
		if obj:IsA(OBF("\155\198\195\193\200\170\201\205\195\206\195\201\200")) or obj:IsA(OBF("\174\201\204\203\207\191")) or obj:IsA(OBF("\155\206\206\187\189\194\199\191\200\206")) then
			obj:Destroy()
		end
	end

	local marker = Instance.new(OBF("\156\201\201\198\176\187\198\207\191"), part)
	marker.Name = OBF("\161\174\155\185\155\206\206\187\189\194\191\190")

	local a1 = Instance.new(OBF("\155\206\206\187\189\194\199\191\200\206"), part)

	local align = Instance.new(OBF("\155\198\195\193\200\170\201\205\195\206\195\201\200"), part)
	align.Attachment0 = a1
	align.Attachment1 = baseAttachment
	align.MaxForce = 1e20
	align.MaxVelocity = math.huge
	align.Responsiveness = 99999

	local torque = Instance.new(OBF("\174\201\204\203\207\191"), part)
	torque.Attachment0 = a1
	torque.RelativeTo = Enum.ActuatorRelativeTo.World
	torque.Torque = Vector3.new(
		math.random(-10e5, 10e5) * 10000,
		math.random(-10e5, 10e5) * 10000,
		math.random(-10e5, 10e5) * 10000
	)

	table.insert(ControlledDoors, {Part = part, Align = align})
end


