local function FlingPlayer(player) if not GTA_PL.guardPlayer(player) then return end
	local char = player.Character
	if not char then return end
	local targetHRP = char:FindFirstChild(OBF("\162\207\199\187\200\201\195\190\172\201\201\206\170\187\204\206"))
	if not targetHRP then return end

	local targetAttachment = targetHRP:FindFirstChild(OBF("\173\162\168\167\155\178\185\174\187\204\193\191\206\155\206\206\187\189\194\199\191\200\206"))
	if not targetAttachment then
		targetAttachment = Instance.new(OBF("\155\206\206\187\189\194\199\191\200\206"), targetHRP)
		targetAttachment.Name = OBF("\173\162\168\167\155\178\185\174\187\204\193\191\206\155\206\206\187\189\194\199\191\200\206")
	end

	for _, data in ipairs(ControlledDoors) do
		if data.Align then
			data.Align.Attachment1 = targetAttachment
		end
	end

	local start = tick()
	local flingDetected = false

	while tick() - start < 5 do
		if targetHRP.Velocity.Magnitude >= 20 then
			flingDetected = true
			break
		end
		RunService.Heartbeat:Wait()
	end

	
	for _, data in ipairs(ControlledDoors) do
		if data.Align then
			data.Align.Attachment1 = baseAttachment
		end
	end
end


UserInputService.TouchTap:Connect(function(touchPositions, processed)
	if processed then return end
	local pos = touchPositions[1]
	local camera = Workspace.CurrentCamera
	local unitRay = camera:ScreenPointToRay(pos.X, pos.Y)
	local raycast = Workspace:Raycast(unitRay.Origin, unitRay.Direction * 1000)

	if raycast and raycast.Instance then
		local hit = raycast.Instance
		local player = Players:GetPlayerFromCharacter(hit:FindFirstAncestorOfClass(OBF("\167\201\190\191\198")))
		if player and player ~= LocalPlayer then
			FlingPlayer(player)
		end
	end
end)
  end
})


