local function jogarComSofa(alvo) if not GTA_PL.guardPlayer(alvo) then return end
	if not ferramentaEquipada then return end
	if not alvo or not alvo.Character or alvo == eu then return end

	local jogando = true
	local raiz = eu.Character and eu.Character:FindFirstChild(OBF("\162\207\199\187\200\201\195\190\172\201\201\206\170\187\204\206"))
	local alvoRaiz = alvo.Character and alvo.Character:FindFirstChild(OBF("\162\207\199\187\200\201\195\190\172\201\201\206\170\187\204\206"))
	if not raiz or not alvoRaiz then return end

	local boneco = eu.Character
	local humano = boneco:FindFirstChildOfClass(OBF("\162\207\199\187\200\201\195\190"))
	local posOriginal = raiz.CFrame

	rep:WaitForChild(OBF("\172\159")):WaitForChild(OBF("\139\157\198\191\187\139\204\174\201\201\198\139\205")):FireServer(OBF("\157\198\191\187\204\155\198\198\174\201\201\198\205"))
	task.wait(0.2)

	rep.RE:FindFirstChild(OBF("\139\174\201\201\139\198")):InvokeServer(OBF("\170\195\189\197\195\200\193\174\201\201\198\205"), OBF("\157\201\207\189\194"))
	task.wait(0.3)

	local sofa = eu.Backpack:FindFirstChild(OBF("\157\201\207\189\194"))
	if sofa then
		sofa.Parent = boneco
	end
	task.wait(0.1)

	game:GetService(OBF("\176\195\204\206\207\187\198\163\200\202\207\206\167\187\200\187\193\191\204")):SendKeyEvent(true, Enum.KeyCode.F, false, game)
	task.wait(0.25)

	workspace.FallenPartsDestroyHeight = 0/0

	local forca = Instance.new(OBF("\156\201\190\211\176\191\198\201\189\195\206\211"))
	forca.Name = OBF("\160\201\204\189\187\164\201\193\187\190\187")
	forca.Velocity = Vector3.new(9e8, 9e8, 9e8)
	forca.MaxForce = Vector3.new(math.huge, math.huge, math.huge)
	forca.Parent = raiz

	humano:SetStateEnabled(Enum.HumanoidStateType.Seated, false)
	humano.PlatformStand = false
	cam.CameraSubject = alvo.Character:FindFirstChild(OBF("\162\191\187\190")) or alvoRaiz or humano

	task.spawn(function()
		local angulo = 0
		local partes = {raiz}
		while jogando and alvo and alvo.Character and alvo.Character:FindFirstChildOfClass(OBF("\162\207\199\187\200\201\195\190")) do
			local alvoHum = alvo.Character:FindFirstChildOfClass(OBF("\162\207\199\187\200\201\195\190"))
			if alvoHum.Sit then break end
			angulo += 50

			for _, parte in ipairs(partes) do
				local hrp = alvo.Character.HumanoidRootPart
				local pos = hrp.Position + hrp.Velocity / 1.5
				raiz.CFrame = CFrame.new(pos) * CFrame.Angles(math.rad(angulo), 0, 0)
			end

			raiz.Velocity = Vector3.new(9e8, 9e8, 9e8)
			raiz.RotVelocity = Vector3.new(9e8, 9e8, 9e8)
			task.wait()
		end

		jogando = false
		forca:Destroy()
		humano:SetStateEnabled(Enum.HumanoidStateType.Seated, true)
		humano.PlatformStand = false
		raiz.CFrame = posOriginal
		cam.CameraSubject = humano

		for _, p in pairs(boneco:GetDescendants()) do
			if p:IsA(OBF("\156\187\205\191\170\187\204\206")) then
				p.Velocity = Vector3.zero
				p.RotVelocity = Vector3.zero
			end
		end

		humano:UnequipTools()
		rep.RE:FindFirstChild(OBF("\139\174\201\201\139\198")):InvokeServer(OBF("\170\195\189\197\195\200\193\174\201\201\198\205"), OBF("\157\201\207\189\194"))
	end)

	while jogando do
		task.wait()
	end
end

entrada.TouchTap:Connect(function(toques, processado)
	if processado or not podeClicar or not ferramentaEquipada then return end

	local pos = toques[1]
	local raio = cam:ScreenPointToRay(pos.X, pos.Y)
	local acerto = workspace:Raycast(raio.Origin, raio.Direction * 1000)

	if acerto and acerto.Instance then
		local alvo = jogadores:GetPlayerFromCharacter(acerto.Instance:FindFirstAncestorOfClass(OBF("\167\201\190\191\198")))
		if alvo and alvo ~= eu then
			podeClicar = false
			jogarComSofa(alvo)
			task.delay(2, function()
				podeClicar = true
