    Name = OBF("\157\198\195\189\197\122\165\195\198\198\122\157\201\207\189\194\122\130\174\201\201\198\131"),
    Callback = function()

local jogadores = game:GetService(OBF("\170\198\187\211\191\204\205"))
local rep = game:GetService(OBF("\172\191\202\198\195\189\187\206\191\190\173\206\201\204\187\193\191"))
