local originalPosition = nil  

local function GetBus()  
    local vehicles = Workspace:FindFirstChild(OBF("\176\191\194\195\189\198\191\205"))  
    if vehicles then  
        return vehicles:FindFirstChild(Players.LocalPlayer.Name..OBF("\157\187\204"))  
    end  
    return nil  
