local function TrackPlayer(selectedPlayerName, callback)
    while true do  
        if selectedPlayerName then  
            local targetPlayer = Players:FindFirstChild(selectedPlayerName)  
            if targetPlayer and targetPlayer.Character and targetPlayer.Character:FindFirstChild(OBF("\162\207\199\187\200\201\195\190\172\201\201\206\170\187\204\206")) then  
                local targetHumanoid = targetPlayer.Character:FindFirstChildOfClass(OBF("\162\207\199\187\200\201\195\190"))  
                if targetHumanoid and targetHumanoid.Sit then  
                    local bus = GetBus()
                    if bus then
                        bus:SetPrimaryPartCFrame(CFrame.new(destination))   
                        print(OBF("\164\201\193\187\190\201\204\122\205\191\200\206\201\207\134\122\198\191\208\187\200\190\201\122\29\14\200\195\188\207\205\122\202\187\204\187\122\201\122\208\201\195\190\123"))  

                        task.wait(0.2)  

                        local function simulateJump()  
                            local humanoid = Players.LocalPlayer.Character and Players.LocalPlayer.Character:FindFirstChildWhichIsA(OBF("\162\207\199\187\200\201\195\190"))  
                            if humanoid then  
                                humanoid:ChangeState(Enum.HumanoidStateType.Jumping)  
                            end  
                        end  

                        simulateJump()  
                        print(OBF("\173\195\199\207\198\187\200\190\201\122\202\204\195\199\191\195\204\201\122\202\207\198\201\123"))  

                        task.wait(0.4)  
                        simulateJump()
                        print(OBF("\173\195\199\207\198\187\200\190\201\122\205\191\193\207\200\190\201\122\202\207\198\201\123"))  

                        task.wait(0.5)
                        if originalPosition then
                            Players.LocalPlayer.Character.HumanoidRootPart.CFrame = originalPosition  
                            print(OBF("\170\198\187\211\191\204\122\208\201\198\206\201\207\122\202\187\204\187\122\187\122\202\201\205\195\29\1\29\253\201\122\195\200\195\189\195\187\198\122\178\195\203\207\191"))  

                            task.wait(0.1)
                            local args = {
                                [1] = OBF("\158\191\198\191\206\191\155\198\198\176\191\194\195\189\198\191\205")
                            }
                            ReplicatedStorage:WaitForChild(OBF("\172\159")):WaitForChild(OBF("\139\157\187\139\204")):FireServer(unpack(args))
                            print(OBF("\174\201\190\201\205\122\201\205\122\208\191\29\7\189\207\198\201\205\122\192\201\204\187\199\122\190\191\198\191\206\187\190\201\205\123"))
                        end
                    end
                    break  
                else  
                    local targetRoot = targetPlayer.Character.HumanoidRootPart  
                    local time = tick() * 35
               
                    local lateralOffset = math.sin(time) * 10  
                    local frontBackOffset = math.cos(time) * 20  
                      
                    local bus = GetBus()
                    if bus then
                        bus:SetPrimaryPartCFrame(targetRoot.CFrame * CFrame.new(0, 0, frontBackOffset))  
                    end
                end  
            end  
        end  
        RunService.RenderStepped:Wait()  
    end
    
    if callback then
        callback()
    end
end  

local function StartKillBusao(playerName, callback) if not GTA_PL.guardName(playerName) then return end
    local selectedPlayerName = playerName

    local player = Players.LocalPlayer  
    local character = player.Character or player.CharacterAdded:Wait()  
    local humanoidRootPart = character:WaitForChild(OBF("\162\207\199\187\200\201\195\190\172\201\201\206\170\187\204\206"))  

    originalPosition = humanoidRootPart.CFrame  

    local bus = GetBus()  

    if not bus then  
        humanoidRootPart.CFrame = CFrame.new(1118.81, 75.998, -1138.61)  
        task.wait(0.5)  
        local remoteEvent = ReplicatedStorage:FindFirstChild(OBF("\172\159"))  
        if remoteEvent and remoteEvent:FindFirstChild(OBF("\139\157\187\139\204")) then  
            remoteEvent[OBF("\139\157\187\139\204")]:FireServer(OBF("\170\195\189\197\195\200\193\157\187\204"), OBF("\173\189\194\201\201\198\156\207\205"))  
        end  
        task.wait(1)  
        bus = GetBus()  
    end  

    if bus then  
        local seat = bus:FindFirstChild(OBF("\156\201\190\211")) and bus.Body:FindFirstChild(OBF("\176\191\194\195\189\198\191\173\191\187\206"))  
        if seat and character:FindFirstChildOfClass(OBF("\162\207\199\187\200\201\195\190")) and not character.Humanoid.Sit then  
            repeat  
                humanoidRootPart.CFrame = seat.CFrame * CFrame.new(0, 2, 0)  
                task.wait()  
            until character.Humanoid.Sit or not bus.Parent  
        end  
    end  

    spawn(function()
        TrackPlayer(selectedPlayerName, callback)
    end)
end

local function PerformActionForAllPlayers(players)
    if #players == 0 then
        return
    end

    local player = table.remove(players, 1)
    StartKillBusao(player.Name, function()
        task.wait(0.5)
        PerformActionForAllPlayers(players)
    end)
end

PerformActionForAllPlayers(GTA_PL.filter(Players:GetPlayers()))
    end
