            game:GetService(OBF("\172\191\202\198\195\189\187\206\191\190\173\206\201\204\187\193\191")).RE:FindFirstChild(OBF("\139\161\191\206\206\195\200\139\193\162\201\207\205\139\191")):FireServer(OBF("\170\195\189\197\195\200\193\157\207\205\206\201\199\162\201\207\205\191"), OBF("\138\142\147\185\162\201\207\205\191"), Number.Value)
        end


        task.wait(0.5)
        local PCar = Vehicles:FindFirstChild(Player.Name..OBF("\157\187\204"))
        if not PCar then
            if Check() then
                RootPart.CFrame = CFrame.new(1118.81, 75.998, -1138.61)
                task.wait(0.5)
                game:GetService(OBF("\172\191\202\198\195\189\187\206\191\190\173\206\201\204\187\193\191")).RE:FindFirstChild(OBF("\139\157\187\139\204")):FireServer(OBF("\170\195\189\197\195\200\193\157\187\204"), OBF("\173\189\194\201\201\198\156\207\205"))
                task.wait(0.5)
