local isHouseRGBActive = false


local function changeColor()
    local replicatedStorage = game:GetService(OBF("\172\191\202\198\195\189\187\206\191\190\173\206\201\204\187\193\191"))
    local remoteEvent = replicatedStorage:FindFirstChild(OBF("\172\159")) and replicatedStorage.RE:FindFirstChild(OBF("\139\170\198\187\211\191\204\139\205\162\201\207\205\139\191"))
    
    if not remoteEvent then
        warn(OBF("\172\191\199\201\206\191\159\208\191\200\206\122\129\139\170\198\187\211\191\204\139\205\162\201\207\205\139\191\129\122\200\29\253\201\122\191\200\189\201\200\206\204\187\190\201\136"))
        return
    end

    while isHouseRGBActive do
        for _, color in ipairs(colors) do
            if not isHouseRGBActive then return end
            local args = {
                [1] = OBF("\157\201\198\201\204\170\195\189\197\162\201\207\205\191"),
                [2] = color
            }
            pcall(function()
                remoteEvent:FireServer(unpack(args))
            end)
            task.wait(0.8)
        end
    end
end

local function toggleHouseRGB(state)
    isHouseRGBActive = state
    if isHouseRGBActive then
        print(OBF("\162\201\207\205\191\122\172\161\156\122\155\189\206\195\208\187\206\191\190"))
        spawn(changeColor)
    else
        print(OBF("\162\201\207\205\191\122\172\161\156\122\158\191\187\189\206\195\208\187\206\191\190"))
    end
end


