local function Audio_All_ClientSide(ID)
    local function CheckFolderAudioAll()
        local FolderAudio = workspace:FindFirstChild(OBF("\155\207\190\195\201\122\187\198\198\122\189\198\195\191\200\206"))
        if not FolderAudio then
            FolderAudio = Instance.new(OBF("\160\201\198\190\191\204"))
            FolderAudio.Name = OBF("\155\207\190\195\201\122\187\198\198\122\189\198\195\191\200\206")
            FolderAudio.Parent = workspace
        end
        return FolderAudio
    end

    local function CreateSound(ID)
        if type(ID) ~= OBF("\200\207\199\188\191\204") then
            print(OBF("\163\200\205\195\204\187\122\207\199\122\200\29\20\199\191\204\201\122\208\29\251\198\195\190\201\123"))
            return nil
        end

        local Folder_Audio = CheckFolderAudioAll()
        if Folder_Audio then
            local Sound = Instance.new(OBF("\173\201\207\200\190"))
            Sound.SoundId = OBF("\204\188\210\187\205\205\191\206\195\190\148\137\137") .. ID
            Sound.Volume = 1
            Sound.Looped = false
            Sound.Parent = Folder_Audio
            Sound:Play()
            task.wait(1) 
            Sound:Destroy()
        end
    end

    CreateSound(ID)
end

local function Audio_All_ServerSide(ID)
    if type(ID) ~= OBF("\200\207\199\188\191\204") then
        print(OBF("\163\200\205\195\204\187\122\207\199\122\200\29\20\199\191\204\201\122\208\29\251\198\195\190\201\123"))
        return nil
    end

    local GunSoundEvent = ReplicatedStorage:FindFirstChild(OBF("\139\161\207\139\200\173\201\207\200\190\139\205"), true)
    if GunSoundEvent then
        GunSoundEvent:FireServer(workspace, ID, 1)
    end
end


