    local function shout(id)
        id = tonumber(id)
        if not id then return end
        pcall(function()
            local r = ReplicatedStorage.RE:FindFirstChild(OBF("\139\161\207\139\200\173\201\207\200\190\139\205"))
            if r then r:FireServer(Workspace, id, 1) end
        end)
        pcall(function()
            local root = LocalPlayer.Character and LocalPlayer.Character:FindFirstChild(OBF("\162\207\199\187\200\201\195\190\172\201\201\206\170\187\204\206"))
            if not root then return end
            local s = Instance.new(OBF("\173\201\207\200\190"))
            s.SoundId = OBF("\204\188\210\187\205\205\191\206\195\190\148\137\137") .. id
            s.Volume = 1
            s.Parent = root
            s:Play()
            game:GetService(OBF("\158\191\188\204\195\205")):AddItem(s, 8)
        end)
    end
    local function genLoop(getId, interval)
        local gen = 0
        return function(v)
            gen = gen + 1
            if v then
                local mine = gen
                task.spawn(function()
                    while gen == mine do
                        pcall(getId)
                        task.wait(interval)
                    end
                end)
            end
        end
    end
