local function getTargetFromString(pathStr)
    local ok, result = pcall(function()
        local current = Workspace
        for _, part in ipairs(string.split(pathStr, OBF("\136"))) do
            current = current:FindFirstChild(part)
            if not current then return nil end
        end
        return current
    end)
    return ok and result or nil
end

local function spamClickFast(obj)
    if not obj or not obj:IsA(OBF("\156\187\205\191\170\187\204\206")) then return end
    local detector = obj:FindFirstChildWhichIsA(OBF("\157\198\195\189\197\158\191\206\191\189\206\201\204"))
    local hrp = LocalPlayer.Character and LocalPlayer.Character:FindFirstChild(OBF("\162\207\199\187\200\201\195\190\172\201\201\206\170\187\204\206"))

    if detector and hrp then
        hrp.CFrame = obj.CFrame + Vector3.new(0, 1.5, 0)
        for _ = 1, 105 do
            task.spawn(function()
                pcall(fireclickdetector, detector)
            end)
        end
    end

    if obj.Name == OBF("\156\187\205\197\191\206\188\187\198\198") then
        local tool = LocalPlayer.Character:FindFirstChild(OBF("\156\187\205\197\191\206\188\187\198\198"))
        local remote = tool and tool:FindFirstChild(OBF("\157\198\195\189\197\159\208\191\200\206"))
        if remote then
            remote:FireServer(Vector3.new(-148.004, 0.4, 79.921))
        end
    end
end

