local function playCarMusic(musicId)
    if musicId and musicId ~= "" then
        local carArgs = {
            [1] = OBF("\170\195\189\197\195\200\193\157\187\204\167\207\205\195\189\174\191\210\206"),
            [2] = musicId
        }
        game:GetService(OBF("\172\191\202\198\195\189\187\206\191\190\173\206\201\204\187\193\191")).RE:FindFirstChild(OBF("\139\170\198\187\211\191\204\139\205\157\187\139\204")):FireServer(unpack(carArgs))
    end
end

