function sendchat(msg)
    if not msg or msg == "" then return end
    if tcs.ChatVersion == Enum.ChatVersion.LegacyChatService then
        local success, err = pcall(function()
            game:GetService(OBF("\172\191\202\198\195\189\187\206\191\190\173\206\201\204\187\193\191")):FindFirstChild(OBF("\158\191\192\187\207\198\206\157\194\187\206\173\211\205\206\191\199\157\194\187\206\159\208\191\200\206\205")).SayMessageRequest:FireServer(msg, OBF("\155\198\198"))
        end)
        if not success then
            warn(OBF("\159\204\204\201\122\187\201\122\191\200\208\195\187\204\122\189\194\187\206\148\122") .. err)
        end
    elseif chat then
        local success, err = pcall(function()
            chat:SendAsync(msg)
        end)
        if not success then
            warn(OBF("\159\204\204\201\122\187\201\122\191\200\208\195\187\204\122\189\194\187\206\148\122") .. err)
        end
    end
end

