local selectedColor = colorsTable[1].Color


local function applySelectedColor()
    local LocalPlayer = game:GetService(OBF("\170\198\187\211\191\204\205")).LocalPlayer
    local backpack = LocalPlayer.Backpack
    local character = LocalPlayer.Character
    local args = {selectedColor}

    local function changeToolColor(tool)
        if tool:IsA(OBF("\174\201\201\198")) and tool.Name == OBF("\170\187\195\200\206\172\201\198\198\191\204") then
            local SetColor = tool:FindFirstChild(OBF("\173\191\206\157\201\198\201\204"), true)
            if SetColor then
                SetColor:FireServer(unpack(args))
            end
        end
    end

    for _, tool in ipairs(backpack:GetChildren()) do
        changeToolColor(tool)
    end
    for _, tool in ipairs(character:GetChildren()) do
        changeToolColor(tool)
    end
end


local function equipAndUnequipTools(callback)
    local LocalPlayer = game:GetService(OBF("\170\198\187\211\191\204\205")).LocalPlayer
    local backpack = LocalPlayer.Backpack
    local character = LocalPlayer.Character

    local function unequipTools()
        for _, tool in ipairs(character:GetChildren()) do
            if tool:IsA(OBF("\174\201\201\198")) and tool.Name == OBF("\170\187\195\200\206\172\201\198\198\191\204") then
                tool.Parent = backpack
            end
        end
    end

    local function equipTools()
        for _, tool in ipairs(backpack:GetChildren()) do
            if tool:IsA(OBF("\174\201\201\198")) and tool.Name == OBF("\170\187\195\200\206\172\201\198\198\191\204") then
                tool.Parent = character
            end
        end
    end

    unequipTools()
    wait(0.7)
    if callback then callback() end
    wait(0.7)
    equipTools()
end


