  function getClosest()
    all = getBalloons()

    if #all == 0 then
      return nil
    end

    best = nil
    bestDist = math.huge
    pos = camera.CFrame.Position

    for key2, value2 in pairs(all) do
      if value2.part and value2.part.Parent then
        dist = (value2.part.Position - pos).Magnitude

        if dist < bestDist then
          bestDist = dist
          best = value2
        end
      end
    end

    return best
  end

  function alive()
    c = player.Character

    if not c then
      return false
    end

    h = c:FindFirstChild(OBF("\162\207\199\187\200\201\195\190"))
    return h and h.Health > 0
  end

  function getBalloonCount()
    all = getBalloons()
    return #all
  end

  function switchTarget()
    target = getClosest()
  end

  function isAimbotActive()
    return enabled
  end

  RunService.RenderStepped:Connect(function()
    if not enabled or not alive() then
      return
    end

    if target and (not target.part or not target.part.Parent) then
      target = getClosest()
    end

    if not target then
      target = getClosest()
    end

    if target and target.part and target.part.Parent then
      camera.CFrame = camera.CFrame:Lerp(
        CFrame.new(camera.CFrame.Position, target.part.Position), smooth
      )
    end
  end)

