local function tabProps()
    local T = ActiveWindow:MakeTab({Title = OBF("\170\204\201\202\205\133"), Icon = OBF("\188\201\210")})
    local PROPS = {
        {OBF("\156\198\201\189\201\205"), {OBF("\171\207\187\204\206\191\204\160\198\201\201\204"), OBF("\156\207\195\198\190\195\200\193")}}, {OBF("\156\207\200\197\191\204\205"), {OBF("\156\195\193\161\207\200\156\207\200\197\191\204"), OBF("\156\207\195\198\190\195\200\193")}},
        {OBF("\160\201\193\201"), {OBF("\174\201\204\189\194\160\195\204\191\166\201\200\193"), OBF("\174\201\204\189\194")}}, {OBF("\166\207\212\191\205"), {OBF("\158\187\200\189\191\167\187\189\194\195\200\191\157\201\207\202\198\191"), OBF("\166\195\193\194\206\205")}},
        {OBF("\156\201\200\191\189\201\122\190\191\122\168\191\208\191"), {OBF("\157\194\204\195\205\206\199\187\205\173\200\201\209\199\187\200"), OBF("\157\194\204\195\205\206\199\187\205")}}, {OBF("\174\204\187\199\202\201\198\195\199"), {OBF("\173\207\199\199\191\204\140\138\140\144\174\204\187\199\202\201\198\195\200\191"), OBF("\157\187\204\200\195\208\187\198")}},
        {OBF("\157\187\208\187\198\201"), {OBF("\162\201\204\205\191\156\195\193\156\204\201\209\200"), OBF("\162\201\204\205\191")}},
    }
    local propSel, count, speed, radius, height, mode, onSelf, targetName = PROPS[1][1], 8, 2, 8, 3, OBF("\169\204\188\195\206"), true, nil
    local running = false

    local function myProps()
        local out = {}
        local f = WS:FindFirstChild(OBF("\177\201\204\197\205\202\187\189\191\157\201\199")) and WS.WorkspaceCom:FindFirstChild(OBF("\138\138\139\185\174\204\187\192\192\195\189\157\201\200\191\205"))
        if not f then return out end
        for _, p in ipairs(f:GetChildren()) do
            if p.Name == OBF("\170\204\201\202") .. LP.Name then out[#out + 1] = p end
        end
        return out
    end
    local function spawnProps()
        local def = lookup(PROPS, propSel); if not def then return end
        local c = char(); local r = hrp(); local h = hum(); if not (c and r and h) then return end
        local home = r.CFrame
        pcall(function() RE[OBF("\139\157\198\191\187\139\204\174\201\201\198\139\205")]:FireServer(OBF("\157\198\191\187\204\155\198\198\170\204\201\202\205")) end)
        task.wait(0.8)
        if not findTool(OBF("\170\204\201\202\167\187\197\191\204")) then getTool(OBF("\170\204\201\202\167\187\197\191\204")) task.wait(0.5) end
        local pm = findTool(OBF("\170\204\201\202\167\187\197\191\204")); if pm then h:EquipTool(pm) end
        task.wait(0.4)
        pcall(function() RE[OBF("\139\157\198\191\187\139\204\174\201\201\198\139\205")]:FireServer(OBF("\172\191\203\207\191\205\206\195\200\193\170\204\201\202\168\187\199\191"), def[1], def[2]) end)
        task.wait(0.4)
        for _ = 1, count do
            if not running then break end
            local t = c:FindFirstChild(OBF("\170\204\201\202\167\187\197\191\204")) and c.PropMaker:FindFirstChild(OBF("\174\201\201\198\185\170\204\201\202\167\187\197\191"))
            if t then pcall(function() t:FireServer(WS:FindFirstChild(OBF("\167\201\190\191\198")) and WS.Model:FindFirstChild(OBF("\157\201\204\200\191\204\162\195\198\198\205")), home.Position) end) end
            task.wait(0.9)
        end
        r.CFrame = home
    end
    local function targetRoot()
        if onSelf then return hrp() end
        local p = targetName and Plrs:FindFirstChild(targetName)
        return p and p.Character and p.Character:FindFirstChild(OBF("\162\207\199\187\200\201\195\190\172\201\201\206\170\187\204\206"))
    end
    local function offsetFor(i, n, t)
        local a = (i / n) * math.pi * 2
        if mode == OBF("\169\204\188\195\206") then
            return CFrame.new(math.cos(a + t * speed) * radius, height, math.sin(a + t * speed) * radius)
        elseif mode == OBF("\174\201\204\200\187\190\201") then
            local k = i / n
            local rr = radius * (0.3 + k)
            return CFrame.new(math.cos(a * 2 + t * speed * 2) * rr, height * 2 * k * 3, math.sin(a * 2 + t * speed * 2) * rr)
        elseif mode == OBF("\177\195\200\193\205") then
            local side = (i % 2 == 0) and 1 or -1
            local k = math.ceil(i / 2) / math.ceil(n / 2)
            return CFrame.new(side * (2 + k * radius * 0.6), height + math.sin(t * speed * 3 + k * 2) * 2, 1.5 + k * 1.5)
        elseif mode == OBF("\173\206\187\204\205") then
            local rr = radius * (0.6 + 0.4 * math.sin(t * speed + i))
            return CFrame.new(math.cos(a - t * speed) * rr, height + math.sin(t * speed * 2 + i) * 1.5, math.sin(a - t * speed) * rr)
        elseif mode == OBF("\157\201\188\204\187") then
            return CFrame.new(math.sin(t * speed * 2 + i * 0.5) * 3, height + i * 1.2, -2 - i * 0.6)
        else 
            return CFrame.new(0, height + math.sin(a) * radius * 0.6, -radius + math.cos(a) * radius * 0.6) * CFrame.Angles(0, 0, t * speed)
        end
    end
    local function loop()
        local t0 = tick()
        while running do
            local root = targetRoot()
            local ps = myProps()
            if root and #ps > 0 then
                for i, p in ipairs(ps) do
                    local sc = p:FindFirstChild(OBF("\173\191\206\157\207\204\204\191\200\206\157\160\204\187\199\191"))
                    if sc then
                        local cf = root.CFrame * offsetFor(i, #ps, tick() - t0)
                        task.spawn(function() pcall(function() sc:InvokeServer(cf) end) end)
                    end
                end
            end
            task.wait(0.1)
        end
    end

    T:AddSection({OBF("\155\207\204\187\122\190\191\122\170\204\201\202\205")})
    T:AddDropdown({Name = OBF("\170\204\201\202"), Options = names(PROPS), Default = propSel, Callback = function(v) propSel = v end})
    T:AddDropdown({Name = OBF("\155\207\204\187"), Options = {OBF("\169\204\188\195\206"), OBF("\174\201\204\200\187\190\201"), OBF("\177\195\200\193\205"), OBF("\173\206\187\204\205"), OBF("\157\201\188\204\187"), OBF("\170\201\204\206\187\198")}, Default = OBF("\169\204\188\195\206"), Callback = function(v) mode = v end})
    T:AddSlider({Name = OBF("\171\207\187\200\206\195\190\187\190\191"), Min = 2, Max = 15, Increase = 1, Default = 8, Callback = function(v) count = v end})
    T:AddSlider({Name = OBF("\176\191\198\201\189\195\190\187\190\191"), Min = 1, Max = 10, Increase = 1, Default = 2, Callback = function(v) speed = v end})
    T:AddSlider({Name = OBF("\172\187\195\201"), Min = 3, Max = 25, Increase = 1, Default = 8, Callback = function(v) radius = v end})
    T:AddSlider({Name = OBF("\155\198\206\207\204\187"), Min = -5, Max = 15, Increase = 1, Default = 3, Callback = function(v) height = v end})
    T:AddToggle({Name = OBF("\159\199\122\199\195\199"), Default = true, Callback = function(v) onSelf = v end})
    local dd = T:AddDropdown({Name = OBF("\159\199\122\201\207\206\204\201\122\202\198\187\211\191\204"), Options = {}, Default = "", Callback = function(v) targetName = v onSelf = false end})
    pcall(function() if GTA_PL then GTA_PL.track(dd, false) end end)
    T:AddToggle({Name = OBF("\166\195\193\187\204\122\187\207\204\187"), Default = false, Callback = function(v)
        running = v
        if v then task.spawn(function() spawnProps() if running then loop() end end) end
    end})
    T:AddButton({Name = OBF("\166\195\199\202\187\204\122\206\201\190\201\205\122\201\205\122\202\204\201\202\205"), Callback = function()
        running = false
        pcall(function() RE[OBF("\139\157\198\191\187\139\204\174\201\201\198\139\205")]:FireServer(OBF("\157\198\191\187\204\155\198\198\170\204\201\202\205")) end)
    end})
end


local function tabProtect()
    local T = ActiveWindow:MakeTab({Title = OBF("\170\204\201\206\191\29\1\29\253\201\133"), Icon = OBF("\205\194\195\191\198\190")})
    local conn
    T:AddSection({OBF("\155\200\206\195\135\160\198\195\200\193")})
    T:AddToggle({Name = OBF("\155\200\206\195\135\160\198\195\200\193\122\130\205\191\199\122\189\201\198\195\205\29\253\201\122\133\122\205\191\199\122\208\191\198\201\189\195\190\187\190\191\122\187\188\205\207\204\190\187\131"), Default = false, Callback = function(v)
        if conn then conn:Disconnect() conn = nil end
        if v then
            conn = RunS.Stepped:Connect(function()
                for _, p in ipairs(Plrs:GetPlayers()) do
                    if p ~= LP and p.Character then
                        for _, part in ipairs(p.Character:GetChildren()) do
                            if part:IsA(OBF("\156\187\205\191\170\187\204\206")) then part.CanCollide = false end
                        end
                    end
                end
                local r = hrp()
                if r then
                    if r.AssemblyLinearVelocity.Magnitude > 120 then r.AssemblyLinearVelocity = Vector3.zero end
                    if r.AssemblyAngularVelocity.Magnitude > 60 then r.AssemblyAngularVelocity = Vector3.zero end
                end
            end)
        end
    end})

    local S = ActiveWindow:MakeTab({Title = OBF("\173\189\204\195\202\206\205\133"), Icon = OBF("\205\189\204\201\198\198")})
    S:AddSection({OBF("\158\191\205\191\199\202\191\200\194\201")})
    S:AddButton({Name = OBF("\160\170\173\122\156\201\201\205\206\191\204\122\130\200\187\206\195\208\201\122\161\174\155\131"), Callback = function()
        pcall(function() settings().Rendering.QualityLevel = Enum.QualityLevel.Level01 end)
        local L = game:GetService(OBF("\166\195\193\194\206\195\200\193"))
        L.GlobalShadows = false L.FogEnd = 9e9
        for _, o in ipairs(L:GetChildren()) do
            if o:IsA(OBF("\156\198\207\204\159\192\192\191\189\206")) or o:IsA(OBF("\173\207\200\172\187\211\205\159\192\192\191\189\206")) or o:IsA(OBF("\156\198\201\201\199\159\192\192\191\189\206")) or o:IsA(OBF("\158\191\202\206\194\169\192\160\195\191\198\190\159\192\192\191\189\206")) or o:IsA(OBF("\157\201\198\201\204\157\201\204\204\191\189\206\195\201\200\159\192\192\191\189\206")) then o.Enabled = false end
        end
        for _, o in ipairs(WS:GetDescendants()) do
            if o:IsA(OBF("\170\187\204\206\195\189\198\191\159\199\195\206\206\191\204")) or o:IsA(OBF("\174\204\187\195\198")) or o:IsA(OBF("\173\199\201\197\191")) or o:IsA(OBF("\160\195\204\191")) or o:IsA(OBF("\173\202\187\204\197\198\191\205")) then o.Enabled = false
            elseif o:IsA(OBF("\158\191\189\187\198")) or o:IsA(OBF("\174\191\210\206\207\204\191")) then o.Transparency = 1
            elseif o:IsA(OBF("\156\187\205\191\170\187\204\206")) then o.Material = Enum.Material.SmoothPlastic o.CastShadow = false end
        end
        note(OBF("\161\174\155\122\162\207\188"), OBF("\160\170\173\122\156\201\201\205\206\191\204\122\187\202\198\195\189\187\190\201"))
    end})
end


