    local PA = {sel = nil, running = false, count = 8}
    local VOID = CFrame.new(5000000, -9999999, -5000000)
    local function myProps()
        local out = {}
        local f = WS:FindFirstChild(OBF("\177\201\204\197\205\202\187\189\191\157\201\199")) and WS.WorkspaceCom:FindFirstChild(OBF("\138\138\139\185\174\204\187\192\192\195\189\157\201\200\191\205"))
        if f then
            for _, p in ipairs(f:GetChildren()) do
                if p.Name:find(OBF("\170\204\201\202") .. LP.Name, 1, true) and p:FindFirstChild(OBF("\173\191\206\157\207\204\204\191\200\206\157\160\204\187\199\191")) then out[#out + 1] = p end
            end
        end
        return out
    end
    local function sendCF(p, cf)
        local sc = p:FindFirstChild(OBF("\173\191\206\157\207\204\204\191\200\206\157\160\204\187\199\191"))
        if sc then task.spawn(function() pcall(function() sc:InvokeServer(cf) end) end) end
    end
    local function ensureProps()
        if #myProps() >= PA.count then return myProps() end
        local c, r, h = char(), hrp(), hum()
        if not (c and r and h) then return {} end
        local home = r.CFrame
        pcall(function() RE[OBF("\139\157\198\191\187\139\204\174\201\201\198\139\205")]:FireServer(OBF("\157\198\191\187\204\155\198\198\170\204\201\202\205")) end)
        task.wait(0.8)
        if not findTool(OBF("\170\204\201\202\167\187\197\191\204")) then getTool(OBF("\170\204\201\202\167\187\197\191\204")) task.wait(0.5) end
        local pm = findTool(OBF("\170\204\201\202\167\187\197\191\204")); if pm then h:EquipTool(pm) end
        task.wait(0.4)
        pcall(function() RE[OBF("\139\157\198\191\187\139\204\174\201\201\198\139\205")]:FireServer(OBF("\172\191\203\207\191\205\206\195\200\193\170\204\201\202\168\187\199\191"), OBF("\156\195\193\161\207\200\156\207\200\197\191\204"), OBF("\156\195\193")) end)
        task.wait(0.4)
        for _ = 1, PA.count do
            if not PA.running then break end
            local t = c:FindFirstChild(OBF("\170\204\201\202\167\187\197\191\204")) and c.PropMaker:FindFirstChild(OBF("\174\201\201\198\185\170\204\201\202\167\187\197\191"))
            if t then pcall(function() t:FireServer(WS:FindFirstChild(OBF("\167\201\190\191\198")) and WS.Model:FindFirstChild(OBF("\157\201\204\200\191\204\162\195\198\198\205")), home.Position) end) end
            task.wait(0.9)
        end
        r.CFrame = home
        return myProps()
    end
    local function targetRoot()
        local p = PA.sel and Plrs:FindFirstChild(PA.sel)
        if p and not GTA_PL.canHit(p) then return nil end
        return p and p.Character and p.Character:FindFirstChild(OBF("\162\207\199\187\200\201\195\190\172\201\201\206\170\187\204\206"))
    end
    
    local function spin(props, getRoot, dur, radius)
        local t0 = tick()
        while PA.running and (dur == nil or tick() - t0 < dur) do
            local tr = getRoot()
            if tr then
                local t = tick() - t0
                for i, p in ipairs(props) do
                    local a = (i / #props) * math.pi * 2 + t * 40
                    local pos
                    if radius <= 0 then  
                        pos = tr.Position + Vector3.new(math.sin(t * 50 + i) * 0.4, math.sin(t * 37 + i) * 0.4, math.cos(t * 43 + i) * 0.4)
                    else
                        pos = tr.Position + Vector3.new(math.cos(a) * radius, math.sin(t * 25 + i) * 2, math.sin(a) * radius)
                    end
                    sendCF(p, CFrame.new(pos) * CFrame.Angles(t * 90 + i, t * 70, t * 110))
                end
            end
            RunS.Heartbeat:Wait()
        end
    end
    local function run(job)
        if PA.running then PA.running = false task.wait(0.3) end
        PA.running = true
        task.spawn(function()
            local props = ensureProps()
            if #props == 0 then note(OBF("\161\174\155\122\162\207\188"), OBF("\168\29\253\201\122\189\201\200\205\191\193\207\195\122\205\202\187\209\200\187\204\122\202\204\201\202\205")) PA.running = false return end
            pcall(job, props)
            PA.running = false
        end)
    end
