    TP:AddButton({Name = OBF("\156\204\195\200\193\122\189\201\199\122\170\204\201\202\122\130\193\195\204\187\122\191\122\206\204\187\212\122\187\206\29\3\122\208\201\189\29\4\131"), Callback = function()
