        end)
    end})
    local function doTrazer()
        run(function(props)
            local hadSeated, standSince = false, nil
            while PA.running do
                local pl = PA.sel and Plrs:FindFirstChild(PA.sel)
                local tr = targetRoot()
                local th = pl and pl.Character and pl.Character:FindFirstChildOfClass(OBF("\162\207\199\187\200\201\195\190"))
                local r = hrp()
                if not (tr and th and r) then break end
                if th.Sit then
                    hadSeated, standSince = true, nil
                    for _, p in ipairs(props) do sendCF(p, r.CFrame * CFrame.new(0, 0, -4)) end
                elseif not hadSeated then
                    for _, p in ipairs(props) do sendCF(p, tr.CFrame) end
                else
                    standSince = standSince or tick()
                    for _, p in ipairs(props) do sendCF(p, VOID) end
                    if tick() - standSince > 1.5 then break end
                end
                RunS.Heartbeat:Wait()
            end
            if PA.running then stopAll() end
        end)
    end
    TP:AddButton({Name = OBF("\174\204\187\212\191\204\122\202\198\187\211\191\204\122\130\205\201\192\29\251\122\208\187\195\122\200\201\122\187\198\208\201\122\135\152\122\205\191\200\206\187\122\135\152\122\208\191\199\122\200\187\122\206\207\187\122\192\204\191\200\206\191\122\135\152\122\198\191\208\187\200\206\201\207\122\151\122\208\201\195\190\131"), Callback = doTrazer})
    local function doFling()
        run(function(props)
            local up, last = false, tick()
            local ax, ay, az = 0, 0, 0  
            while PA.running do
                local now = tick(); local dt = math.min(now - last, 0.1); last = now
                local pl = PA.sel and Plrs:FindFirstChild(PA.sel)
                local tr = targetRoot()
                local th = pl and pl.Character and pl.Character:FindFirstChildOfClass(OBF("\162\207\199\187\200\201\195\190"))
                local r = hrp()
                if not (tr and th and r) then break end
                if th.Sit then up = true end
                ax = (ax + 90 * dt) % (2 * math.pi)  
                ay = (ay + 70 * dt) % (2 * math.pi)
                az = (az + 110 * dt) % (2 * math.pi)
                if not up then
                    for i, p in ipairs(props) do sendCF(p, tr.CFrame * CFrame.new(math.sin(ax + i) * 1.5, 0, math.cos(ax + i) * 1.5) * CFrame.Angles(ax, ay, az)) end
                else
                    for i, p in ipairs(props) do sendCF(p, CFrame.new(r.Position.X + i * 0.4, 2500, r.Position.Z) * CFrame.Angles(ax, ay, az)) end
                end
                RunS.Heartbeat:Wait()
            end
            if PA.running then stopAll() end
        end)
    end
