    local function antiGroup(label, filter)
        local on = false
        PR:AddToggle({Name = label, Default = false, Callback = function(v)
            on = v
            if v then task.spawn(function()
                while on do
                    local mine = hum() and hum().SeatPart and hum().SeatPart:FindFirstAncestorOfClass(OBF("\167\201\190\191\198"))
                    for _, o in ipairs(WS:GetDescendants()) do
                        if o:IsA(OBF("\156\187\205\191\170\187\204\206")) and o.CanCollide and filter(o) and not (mine and o:IsDescendantOf(mine)) then
                            o.CanCollide = false
                        end
                    end
                    task.wait(3)
                end
            end) end
        end})
    end
