    local original = setmetatable({}, {__mode = OBF("\197")})

    local function put(anim, id)
        if id and anim and anim:IsA(OBF("\155\200\195\199\187\206\195\201\200")) then
            if original[anim] == nil then original[anim] = anim.AnimationId end
            anim.AnimationId = OBF("\204\188\210\187\205\205\191\206\195\190\148\137\137") .. id
        end
    end
    local function withAnimate(char, fn)
        local hum = char:WaitForChild(OBF("\162\207\199\187\200\201\195\190"), 5)
        local animate = char:WaitForChild(OBF("\155\200\195\199\187\206\191"), 5)
        if not (hum and animate) then return false end
        animate.Disabled = true
        for _, tr in ipairs(hum:GetPlayingAnimationTracks()) do tr:Stop() end
        fn(animate)
        hum:ChangeState(Enum.HumanoidStateType.Jumping)
        animate.Disabled = false
        return true
    end
    local function applyPack(char, ids)
        withAnimate(char, function(animate)
            local idle = animate:FindFirstChild(OBF("\195\190\198\191"))
            if idle then
                put(idle:FindFirstChild(OBF("\155\200\195\199\187\206\195\201\200\139")), ids.idle1)
                put(idle:FindFirstChild(OBF("\155\200\195\199\187\206\195\201\200\140")), ids.idle2)
            end
            for _, s in ipairs({OBF("\209\187\198\197"), OBF("\204\207\200"), OBF("\196\207\199\202"), OBF("\189\198\195\199\188"), OBF("\192\187\198\198"), OBF("\205\209\195\199")}) do
                local f = animate:FindFirstChild(s)
                if f then
                    for _, a in ipairs(f:GetChildren()) do put(a, ids[s]) end
                end
            end
            local sw = animate:FindFirstChild(OBF("\205\209\195\199\195\190\198\191")) or animate:FindFirstChild(OBF("\205\209\195\199\163\190\198\191"))
            if sw then
                for _, a in ipairs(sw:GetChildren()) do put(a, ids.swimidle) end
            end
        end)
    end
    local function restoreDefault(char)
        withAnimate(char, function()
            for anim, id in pairs(original) do pcall(function() anim.AnimationId = id end) end
        end)
        original = setmetatable({}, {__mode = OBF("\197")})
    end

    lp.CharacterAdded:Connect(function(char)
        if not current then return end
        task.wait(0.5)
        applyPack(char, current)
    end)

    T:AddSection({OBF("\170\187\189\201\206\191\205\122\190\191\122\187\200\195\199\187\29\1\29\253\201")})
    for _, p in ipairs(PACKS) do
        T:AddButton({Name = p[1] .. OBF("\122\155\200\195\199\187\206\195\201\200"), Callback = function()
            current = p[2]
            local ch = lp.Character
            if ch then applyPack(ch, current) end
            if GTA_PL and GTA_PL.toast then GTA_PL.toast(p[1] .. OBF("\122\155\200\195\199\187\206\195\201\200\122\187\202\198\195\189\187\190\187"), Color3.fromRGB(80, 180, 255)) end
        end})
    end
    T:AddSection({OBF("\170\187\190\204\29\253\201")})
    T:AddButton({Name = OBF("\172\191\205\206\187\207\204\187\204\122\187\200\195\199\187\29\1\29\253\201\122\202\187\190\204\29\253\201"), Callback = function()
        current = nil
        local ch = lp.Character
        if ch then restoreDefault(ch) end
    end})
end


