local function toNumList(t)
    local o = {}
    if type(t) == OBF("\206\187\188\198\191") then for _, v in ipairs(t) do local n = tonumber(v); if n and n ~= 0 then o[#o + 1] = n end end end
    return o
end

local function packToJson(p)
    local o = { key = p.key, name = p.name }
    for _, f in ipairs(PACK_FIELDS) do o[f] = tostring(p[f] or 0) end
    return o
end
local function packFromJson(d)
    if type(d) ~= OBF("\206\187\188\198\191") or type(d.key) ~= OBF("\205\206\204\195\200\193") then return nil end
    local p = { key = d.key, name = tostring(d.name or d.key), saved = true }
    for _, f in ipairs(PACK_FIELDS) do p[f] = tonumber(d[f]) or 0 end
    return p
end

local function save()
    if not writefile then return end
    local function strs(t) local o = {}; for i, v in ipairs(t) do o[i] = tostring(v) end; return o end
    local cp = {}; for k, v in pairs(S.customPack) do cp[k] = tostring(v) end
    local st = {}; for k, v in pairs(S.stats) do st[tostring(k)] = v end
    local sp = {}; for i, p in ipairs(S.savedPacks) do sp[i] = packToJson(p) end
    local ut = {}; for i, t in ipairs(S.userTabs) do ut[i] = { id = t.id, name = t.name, ids = strs(t.ids) } end
    local af = { on = S.afk.on, secs = S.afk.secs, emote = tostring(S.afk.emote) }
    local spw = { on = S.spawn.on, join = S.spawn.join, emote = tostring(S.spawn.emote), delay = S.spawn.delay }
    local evs = {}; for k, v in pairs(S.ev) do evs[k] = { on = v.on, emote = tostring(v.emote) } end
    local tg = {}; for id, t in pairs(S.tags) do tg[tostring(id)] = { n = t.n, c = t.c } end
    local data = {
        theme = S.theme, sound = S.sound, autoReload = S.autoReload, lastEmote = tostring(S.lastEmote),
        speed = S.speed, loop = S.loop, reverse = S.reverse, walkEmote = S.walkEmote, pack = S.pack, parts = S.parts, toggleKey = S.toggleKey, real = S.real,
        hidden = S.hidden, fab = S.fab, fabPos = S.fabPos, winPos = S.winPos, page = S.page, emoteKey = S.emoteKey,
        favs = strs(S.favs), packFavs = S.packFavs, customEmotes = strs(S.customEmotes), wheel = strs(S.wheel),
        playlist = strs(S.playlist), recents = strs(S.recents), customPack = cp, stats = st, savedPacks = sp,
        fx = S.fx, fp = S.fp, userTabs = ut, mini = S.mini, miniPos = S.miniPos, antiAfk = S.antiAfk, afk = af,
        sh = S.sh, spawn = spw, ev = evs, evCd = S.evCd, evLandMin = S.evLandMin, evRunMin = S.evRunMin, tags = tg,
        perf = S.perf, hud = S.hud, hudPos = S.hudPos, seenLog = S.seenLog, pingpong = S.pingpong,
    }
    pcall(function() writefile(CFG.SaveFile, HttpService:JSONEncode(data)) end)
end

local function loadSave()
    if not (readfile and isfile and isfile(CFG.SaveFile)) then return end
    local ok, d = pcall(function() return HttpService:JSONDecode(readfile(CFG.SaveFile)) end)
    if not ok or type(d) ~= OBF("\206\187\188\198\191") then return end
    S.theme      = math.clamp(tonumber(d.theme) or 1, 1, #THEMES)
    if d.sound ~= nil then S.sound = d.sound end
    S.autoReload = d.autoReload == true
    S.lastEmote  = tonumber(d.lastEmote) or 0
    S.speed      = tonumber(d.speed) or 1
    if d.loop ~= nil then S.loop = d.loop end
    S.reverse    = d.reverse == true
    S.walkEmote  = d.walkEmote == true
    S.pack       = type(d.pack) == OBF("\205\206\204\195\200\193") and d.pack or OBF("\200\201\200\191")
    if type(d.toggleKey) == OBF("\205\206\204\195\200\193") then
        local okk, kc = pcall(function() return Enum.KeyCode[d.toggleKey] end)
        if okk and kc then S.toggleKey = d.toggleKey end
    end
    if type(d.real) == OBF("\206\187\188\198\191") then
        for k, v in pairs(S.real) do
            if type(d.real[k]) == type(v) then S.real[k] = d.real[k] end
        end
        S.real.reach = math.clamp(S.real.reach, 0.3, 2)
        S.real.leanAmt = math.clamp(S.real.leanAmt, 0.2, 2)
        S.real.camAmt = math.clamp(S.real.camAmt, 0.2, 2)
    end
    if type(d.parts) == OBF("\206\187\188\198\191") then
        for g, k in pairs(d.parts) do if GROUPS[g] and type(k) == OBF("\205\206\204\195\200\193") then S.parts[g] = k end end
    end
    S.hidden     = d.hidden == true
    if d.fab ~= nil then S.fab = d.fab end
    if type(d.fabPos) == OBF("\206\187\188\198\191") and #d.fabPos == 4 then S.fabPos = d.fabPos end
    if type(d.winPos) == OBF("\206\187\188\198\191") and #d.winPos == 4 then S.winPos = d.winPos end
    if type(d.page) == OBF("\205\206\204\195\200\193") then S.page = d.page end
    if type(d.emoteKey) == OBF("\205\206\204\195\200\193") then S.emoteKey = d.emoteKey end
    S.favs         = toNumList(d.favs)
    S.customEmotes = toNumList(d.customEmotes)
    S.wheel        = toNumList(d.wheel)
    S.playlist     = toNumList(d.playlist)
    S.recents      = toNumList(d.recents)
    if type(d.packFavs) == OBF("\206\187\188\198\191") then S.packFavs = d.packFavs end
    if type(d.customPack) == OBF("\206\187\188\198\191") then
        for _, f in ipairs(PACK_FIELDS) do S.customPack[f] = tonumber(d.customPack[f]) or 0 end
    end
    if type(d.stats) == OBF("\206\187\188\198\191") then for k, v in pairs(d.stats) do S.stats[tonumber(k) or k] = v end end
    if type(d.savedPacks) == OBF("\206\187\188\198\191") then
        for _, pd in ipairs(d.savedPacks) do local p = packFromJson(pd); if p then S.savedPacks[#S.savedPacks + 1] = p end end
    end
    if type(d.fx) == OBF("\206\187\188\198\191") then
        for k, v in pairs(S.fx) do if type(d.fx[k]) == type(v) then S.fx[k] = d.fx[k] end end
        for _, k in ipairs({ OBF("\204"), OBF("\193"), OBF("\188") }) do S.fx[k] = math.clamp(S.fx[k], 0, 1) end
    end
    if type(d.fp) == OBF("\206\187\188\198\191") then
        for k, v in pairs(S.fp) do if type(d.fp[k]) == type(v) then S.fp[k] = d.fp[k] end end
        S.fp.fov = math.clamp(S.fp.fov, 60, 110); S.fp.depth = math.clamp(S.fp.depth, 0, 1.2)
        S.fp.followAmt = math.clamp(S.fp.followAmt, 0, 1); S.fp.motion = math.clamp(S.fp.motion, 0, 2)
    end
    S.mini = d.mini == true
    if d.antiAfk ~= nil then S.antiAfk = d.antiAfk == true end
    if type(d.miniPos) == OBF("\206\187\188\198\191") and #d.miniPos == 4 then S.miniPos = d.miniPos end
    if type(d.afk) == OBF("\206\187\188\198\191") then
        S.afk.on = d.afk.on == true
        S.afk.secs = math.clamp(tonumber(d.afk.secs) or 60, CFG.AfkMinSecs, 3600)
        S.afk.emote = tonumber(d.afk.emote) or 0
    end
    if type(d.sh) == OBF("\206\187\188\198\191") then
        for k, v in pairs(S.sh) do if type(d.sh[k]) == type(v) then S.sh[k] = d.sh[k] end end
        S.sh.side = (S.sh.side < 0) and -1 or 1
        S.sh.x = math.clamp(S.sh.x, 0.3, 3.5); S.sh.y = math.clamp(S.sh.y, -1.5, 1.5)
        S.sh.dist = math.clamp(S.sh.dist, 3, 15); S.sh.fov = math.clamp(S.sh.fov, 45, 100)
    end
    if type(d.spawn) == OBF("\206\187\188\198\191") then
        S.spawn.on = d.spawn.on == true; S.spawn.join = d.spawn.join == true
        S.spawn.emote = tonumber(d.spawn.emote) or 0
        S.spawn.delay = math.clamp(tonumber(d.spawn.delay) or 1.5, 0.3, 8)
    end
    if type(d.ev) == OBF("\206\187\188\198\191") then
        for k, v in pairs(S.ev) do
            local e = d.ev[k]
            if type(e) == OBF("\206\187\188\198\191") then v.on = e.on == true; v.emote = tonumber(e.emote) or 0 end
        end
    end
    S.evCd = math.clamp(tonumber(d.evCd) or 3, 1, 20)
    S.evLandMin = math.clamp(tonumber(d.evLandMin) or 60, 20, 150)
    S.evRunMin = math.clamp(tonumber(d.evRunMin) or 14, 6, 30)
    if type(d.tags) == OBF("\206\187\188\198\191") then
        for k, t in pairs(d.tags) do
            local id = tonumber(k)
            if id and type(t) == OBF("\206\187\188\198\191") then
                local c = tonumber(t.c)
                if c and (c < 1 or c > #TAG_COLORS) then c = nil end
                local n = type(t.n) == OBF("\205\206\204\195\200\193") and t.n:sub(1, 18) or nil
                if n or c then S.tags[id] = { n = n, c = c } end
            end
        end
    end
    if type(d.perf) == OBF("\206\187\188\198\191") then S.perf.on = d.perf.on == true; S.perf.min = math.clamp(tonumber(d.perf.min) or 25, 10, 60) end
    S.hud = d.hud == true
    if type(d.hudPos) == OBF("\206\187\188\198\191") and #d.hudPos == 4 then S.hudPos = d.hudPos end
    S.seenLog = tonumber(d.seenLog) or 0
    S.pingpong = d.pingpong == true
    if type(d.userTabs) == OBF("\206\187\188\198\191") then
        for _, t in ipairs(d.userTabs) do
            if type(t) == OBF("\206\187\188\198\191") and type(t.id) == OBF("\205\206\204\195\200\193") and type(t.name) == OBF("\205\206\204\195\200\193") and #S.userTabs < CFG.MaxUserTabs then
                S.userTabs[#S.userTabs + 1] = { id = t.id, name = t.name, ids = toNumList(t.ids) }
            end
        end
    end
end
