local UI = { conns = {}, themed = {}, paints = {}, refreshers = {}, orders = {}, revealed = false, firstShow = {} }
local E  = { track = nil, token = 0, orig = {}, viaEmote = {}, animOf = {}, wasMoving = false, seqId = 0 }
local WH = { wasVisible = false }
local FP = { off = Vector3.zero, begun = false, first = false, tok = 0, body = {}, hide = {}, dirty = true,
             nativeCF = nil, bob = Vector3.zero, roll = 0, ph = 0 }
local SH = { off = Vector3.zero, active = false }            
local CAMFX = { roll = 0, amp = 0, t = 0 }                   
function CAMFX.kick(fall) 
    local k = math.clamp((fall - 32) / 70, 0, 1)
    if k > CAMFX.amp then CAMFX.amp = k end
end

local function parseId(raw)
    if not raw then return 0 end
    local s = tostring(raw):gsub(OBF("\127\205\133"), "")
    if s == "" or s == OBF("\138") then return 0 end
    if s:match(OBF("\184\127\190\133\126")) then return tonumber(s) end
    local patterns = {
        OBF("\204\188\210\187\205\205\191\206\195\190\148\137\137\130\127\190\133\131"), OBF("\187\205\205\191\206\137\127\153\195\190\151\130\127\190\133\131"), OBF("\137\205\206\201\204\191\137\187\205\205\191\206\137\130\127\190\133\131"), OBF("\137\189\187\206\187\198\201\193\137\130\127\190\133\131"),
        OBF("\137\198\195\188\204\187\204\211\137\130\127\190\133\131"), OBF("\137\188\207\200\190\198\191\205\137\130\127\190\133\131"), OBF("\137\187\200\195\199\187\206\195\201\200\205\137\130\127\190\133\131"), OBF("\137\187\205\205\191\206\137\130\127\190\133\131"), OBF("\181\153\128\183\195\190\151\130\127\190\133\131"),
    }
    for _, p in ipairs(patterns) do
        local m = s:match(p)
        if m then return tonumber(m) end
    end
    local f = s:match(OBF("\130\127\190\127\190\127\190\127\190\127\190\127\190\133\131"))
    return f and tonumber(f) or 0
end

local function notify(title, text) if UI.toast then UI.toast(title, text) end end

local function sound(name)
    if not S.sound or not SOUNDS[name] then return end
    pcall(function()
        local s = Instance.new(OBF("\173\201\207\200\190"))
        s.SoundId = OBF("\204\188\210\187\205\205\191\206\195\190\148\137\137") .. SOUNDS[name]; s.Volume = 0.4; s.Parent = SoundService
        s:Play(); Debris:AddItem(s, 3)
    end)
end

local function copyText(t)
    local fn = setclipboard or toclipboard or set_clipboard or (syn and syn.write_clipboard) or (Clipboard and Clipboard.set)
    if fn then
        local ok = pcall(fn, t)
        if ok then notify(OBF("\157\201\202\195\187\190\201"), t); return true end
    end
    if UI.idBox then UI.idBox.Text = t end
    notify(OBF("\173\191\199\122\189\198\195\202\188\201\187\204\190"), OBF("\163\158\122\189\201\198\201\189\187\190\201\122\200\187\122\189\187\195\210\187\148\122") .. t)
    return false
end

local function isFav(id) return table.find(S.favs, id) ~= nil end
local function toggleFav(id)
    local i = table.find(S.favs, id)
    if i then table.remove(S.favs, i) else table.insert(S.favs, 1, id) end
    save()
    return i == nil
