function E.fxColor()
    local o, F = E.fxObjs, S.fx
    if not o or F.rainbow then return end
    local col = Color3.new(F.r, F.g, F.b)
    pcall(function()
        if o.pe then o.pe.Color = ColorSequence.new(col) end
        if o.hl then o.hl.FillColor = col; o.hl.OutlineColor = col end
        if o.tr then o.tr.Color = ColorSequence.new(col) end
    end)
end

function E.fxApply()
    E.clearFx(); E.fxObjs = nil
    local F = S.fx
    if E.perf or not (F.particles or F.aura or F.trail) then return end
    local c = LP.Character
    local hrp = c and c:FindFirstChild(OBF("\162\207\199\187\200\201\195\190\172\201\201\206\170\187\204\206"))
    if not hrp then return end
    local o = {}
    pcall(function()
        if F.particles then
            local pe = Instance.new(OBF("\170\187\204\206\195\189\198\191\159\199\195\206\206\191\204"))
            pe.Name = OBF("\159\162\185\170\159"); pe.Texture = OBF("\204\188\210\187\205\205\191\206\195\190\148\137\137\144\139\138\139\140\144\139\140\140\144")
            pe.Rate = 28; pe.Lifetime = NumberRange.new(1.8); pe.Speed = NumberRange.new(6)
            pe.SpreadAngle = Vector2.new(180, 180); pe.LightEmission = 0.8
            pe.Size = NumberSequence.new({ NumberSequenceKeypoint.new(0, 0.4), NumberSequenceKeypoint.new(1, 0) })
            pe.Parent = hrp; o.pe = pe
        end
        if F.aura then
            local hl = Instance.new(OBF("\162\195\193\194\198\195\193\194\206"))
            hl.Name = OBF("\159\162\185\170\159"); hl.FillTransparency = 0.7; hl.OutlineTransparency = 0.05
            hl.DepthMode = Enum.HighlightDepthMode.Occluded
            hl.Parent = c; o.hl = hl
        end
        if F.trail then
            local a0 = Instance.new(OBF("\155\206\206\187\189\194\199\191\200\206")); a0.Name = OBF("\159\162\185\170\159"); a0.Position = Vector3.new(0, 1.2, 0); a0.Parent = hrp
            local a1 = Instance.new(OBF("\155\206\206\187\189\194\199\191\200\206")); a1.Name = OBF("\159\162\185\170\159"); a1.Position = Vector3.new(0, -1.6, 0); a1.Parent = hrp
            local tr = Instance.new(OBF("\174\204\187\195\198"))
            tr.Name = OBF("\159\162\185\170\159"); tr.Attachment0 = a0; tr.Attachment1 = a1; tr.Lifetime = 0.55; tr.LightEmission = 0.85
            tr.Transparency = NumberSequence.new({ NumberSequenceKeypoint.new(0, 0.15), NumberSequenceKeypoint.new(1, 1) })
            tr.WidthScale = NumberSequence.new({ NumberSequenceKeypoint.new(0, 1), NumberSequenceKeypoint.new(1, 0.2) })
            tr.Parent = hrp; o.tr = tr
        end
    end)
    E.fxObjs = o
    E.fxColor()
end


function E.fxQuick(color)
    local F = S.fx
    if not color then
        F.particles, F.aura, F.trail = false, false, false
    else
        F.r, F.g, F.b = color.R, color.G, color.B
        F.rainbow = false
        if not (F.particles or F.aura or F.trail) then F.particles = true end
    end
    save(); E.fxApply()
end

