function WH.root()
    local ok, w = pcall(function() return CoreGui.RobloxGui.EmotesMenu.Children.Main.EmotesWheel end)
    return ok and w or nil
end
function WH.front()
    local ok, r = pcall(function() return CoreGui.RobloxGui.EmotesMenu.Children.Main.EmotesWheel.Front.EmotesButtons end)
    return ok and r or nil
end

function WH.inject()
    if #S.wheel == 0 then return end
    local char = LP.Character; local hum = char and char:FindFirstChildOfClass(OBF("\162\207\199\187\200\201\195\190")); if not hum then return end
    if hum.RigType == Enum.HumanoidRigType.R6 then notify(OBF("\172\201\190\187"), OBF("\172\144\122\200\29\253\201\122\205\207\202\201\204\206\187\190\201\134\122\207\205\191\122\172\139\143")); return end
    local hd = hum:FindFirstChildOfClass(OBF("\162\207\199\187\200\201\195\190\158\191\205\189\204\195\202\206\195\201\200")) or hum:FindFirstChild(OBF("\162\207\199\187\200\201\195\190\158\191\205\189\204\195\202\206\195\201\200"))
    if not hd then return end
    local emoteTable, equipped = {}, {}
    for i = 1, math.min(#S.wheel, CFG.WheelMax) do
        local id = S.wheel[i]
        local base = (Names.cache[id] or (OBF("\159") .. id)):gsub(OBF("\181\184\127\209\127\205\185\127\135\183"), ""):sub(1, 30)
        local slot = OBF("\173") .. i .. OBF("\185") .. base
        emoteTable[slot] = { id }; equipped[i] = slot
    end
    pcall(function() hd:SetEmotes(emoteTable); hd:SetEquippedEmotes(equipped) end)
    task.delay(0.3, WH.connect)
end

local function sortSlots(buttons)
    local hasLayout = false
    for _, b in ipairs(buttons) do if b.LayoutOrder and b.LayoutOrder ~= 0 then hasLayout = true; break end end
    if hasLayout then
        table.sort(buttons, function(a, b) return (a.LayoutOrder or 999) < (b.LayoutOrder or 999) end)
        return
    end
    table.sort(buttons, function(a, b)
        local aa = math.atan2(a.Position.X.Scale - 0.5, -(a.Position.Y.Scale - 0.5))
        local bb = math.atan2(b.Position.X.Scale - 0.5, -(b.Position.Y.Scale - 0.5))
        if aa < 0 then aa += math.pi * 2 end
        if bb < 0 then bb += math.pi * 2 end
        return aa < bb
    end)
end

function WH.connect()
    local front = WH.front(); if not front then return end
    local buttons = {}
    for _, c in pairs(front:GetChildren()) do if c:IsA(OBF("\163\199\187\193\191\166\187\188\191\198")) then buttons[#buttons + 1] = c end end
    sortSlots(buttons)
    for i, img in ipairs(buttons) do
        local id = S.wheel[i]
        if id then
            local btn = img:FindFirstChild(OBF("\159\162\185\173\198\201\206"))
            if not btn then
                btn = Instance.new(OBF("\174\191\210\206\156\207\206\206\201\200")); btn.Name = OBF("\159\162\185\173\198\201\206")
                btn.Size = UDim2.new(1, 0, 1, 0); btn.BackgroundTransparency = 1; btn.Text = ""
                btn.ZIndex = img.ZIndex + 10; btn.Parent = img
            end
            btn:SetAttribute(OBF("\159\199\201\206\191\163\190"), id)
        else
            local btn = img:FindFirstChild(OBF("\159\162\185\173\198\201\206")); if btn then btn:Destroy() end
        end
    end
end

local function pointIn(px, py, obj)
    local p, s = obj.AbsolutePosition, obj.AbsoluteSize
    return px >= p.X and px <= p.X + s.X and py >= p.Y and py <= p.Y + s.Y
end

function WH.hover(px, py)
    local w = WH.root()
    if not w or not w.Visible then WH.last = nil; return end
    local front = WH.front(); if not front then return end
    local hovered
    for _, img in pairs(front:GetChildren()) do
        if img:IsA(OBF("\163\199\187\193\191\166\187\188\191\198")) then
            local b = img:FindFirstChild(OBF("\159\162\185\173\198\201\206"))
            if b and pointIn(px, py, img) then hovered = b; break end
        end
    end
    if hovered ~= WH.last then
        WH.last = hovered
        if hovered then
            local id = hovered:GetAttribute(OBF("\159\199\201\206\191\163\190"))
            if id and id ~= 0 then task.spawn(E.play, id) end
        end
    end
end

function WH.add(id)
    if table.find(S.wheel, id) then notify(OBF("\172\201\190\187"), OBF("\164\29\251\122\191\205\206\29\251\122\200\187\122\204\201\190\187")); return end
    if #S.wheel >= CFG.WheelMax then notify(OBF("\172\201\190\187\122\189\194\191\195\187"), OBF("\167\29\251\210\195\199\201\122") .. CFG.WheelMax .. OBF("\122\60\218\238\122\204\191\199\201\208\187\122\207\199\122\200\187\122\187\188\187\122\74\249\232\251\122\172\201\190\187")); sound(OBF("\191\204\204\201\204")); return end
    table.insert(S.wheel, id); save(); WH.inject()
    notify(OBF("\74\249\232\251\122\172\201\190\187"), OBF("\155\190\195\189\195\201\200\187\190\201\122\130") .. #S.wheel .. OBF("\137") .. CFG.WheelMax .. OBF("\131")); sound(OBF("\205\207\189\189\191\205\205"))
end
function WH.remove(id)
    local i = table.find(S.wheel, id)
    if i then table.remove(S.wheel, i); save(); WH.inject(); task.delay(0.35, WH.connect) end
end




local MAP = {
    walk = {OBF("\209\187\198\197"), 1}, run = {OBF("\204\207\200"), 1}, idle1 = {OBF("\195\190\198\191"), 1}, idle2 = {OBF("\195\190\198\191"), 2},
    jump = {OBF("\196\207\199\202"), 1}, fall = {OBF("\192\187\198\198"), 1}, climb = {OBF("\189\198\195\199\188"), 1}, swim = {OBF("\205\209\195\199"), 1}, swimidle = {OBF("\205\209\195\199\195\190\198\191"), 1},
}

local function packByKey(key)
    if key == OBF("\189\207\205\206\201\199") then
        local p = { key = OBF("\189\207\205\206\201\199"), name = OBF("\157\207\205\206\201\199") }
        for _, f in ipairs(PACK_FIELDS) do p[f] = S.customPack[f] end
        return p
    end
    for _, p in ipairs(PACKS) do if p.key == key then return p end end
    for _, p in ipairs(S.savedPacks) do if p.key == key then return p end end
    return nil
end

local function allPacks()
    local o = {}
    for _, p in ipairs(PACKS) do o[#o + 1] = p end
    for _, p in ipairs(S.savedPacks) do o[#o + 1] = p end
    return o
end

local function packIsEmpty(p)
    for _, f in ipairs(PACK_FIELDS) do if (p[f] or 0) ~= 0 then return false end end
    return true
end

local function packText(p)
    local t = {}
    for _, f in ipairs(PACK_FIELDS) do t[#t + 1] = f .. OBF("\151") .. tostring(p[f] or 0) end
    return p.name .. OBF("\148\122") .. table.concat(t, OBF("\122"))
end

function E.applyPack(char, quiet)
    char = char or LP.Character
    local animate = char and (char:FindFirstChild(OBF("\155\200\195\199\187\206\191")) or char:WaitForChild(OBF("\155\200\195\199\187\206\191"), 8))
    if not animate then return end
    local pack = packByKey(S.pack)
    for key, m in pairs(MAP) do
        local folder = animate:FindFirstChild(m[1])
        if folder then
            local list = {}
            for _, a in ipairs(folder:GetChildren()) do if a:IsA(OBF("\155\200\195\199\187\206\195\201\200")) then list[#list + 1] = a end end
            table.sort(list, function(a, b) return a.Name < b.Name end)
            local t = list[m[2]]
            if t then
                local ok = m[1] .. m[2]
                if not E.orig[ok] then E.orig[ok] = t.AnimationId end
                
                local ov = S.parts[FIELD_GROUP[key]]
                local src = (ov and packByKey(ov)) or pack
                local nid = src and src[key] or 0
                t.AnimationId = (nid ~= 0) and (OBF("\204\188\210\187\205\205\191\206\195\190\148\137\137") .. nid) or E.orig[ok]
            end
        end
    end
    pcall(function()
        animate.Disabled = true
        local _, _, an = E.parts()
        if an then for _, t in ipairs(an:GetPlayingAnimationTracks()) do if t ~= E.track then t:Stop(0) end end end
        task.wait()
        animate.Disabled = false
    end)
    if not quiet then
        local n = 0; for _ in pairs(S.parts) do n += 1 end
        notify(pack and pack.name or OBF("\169\204\195\193\195\200\187\198"), (pack and OBF("\170\187\189\197\122\187\202\198\195\189\187\190\201") or OBF("\155\200\195\199\187\29\1\29\15\191\205\122\204\191\205\206\187\207\204\187\190\187\205")) .. (n > 0 and (OBF("\122\28\17\122") .. n .. OBF("\122\202\187\204\206\191\130\205\131\122\206\204\201\189\187\190\187\130\205\131")) or ""))
    end
    if UI.updateStatus then UI.updateStatus() end
end

function E.setPack(key)
    S.pack = key; S.parts = {}; save() 
    task.spawn(E.applyPack)
end


function E.setPart(group, key)
    if not GROUPS[group] then return end
    S.parts[group] = key; save()
    task.spawn(E.applyPack)
end
function E.clearParts()
    S.parts = {}; save()
    task.spawn(E.applyPack)
end




local reqFn = (syn and syn.request) or http_request or request or (fluxus and fluxus.request) or (http and http.request)

local function getJSON(url, tries)
    tries = tries or 0
    if not reqFn then return nil, OBF("\191\210\191\189\207\206\201\204\122\205\191\199\122\204\191\203\207\191\205\206\130\131") end
    local ok, res = pcall(reqFn, { Url = url, Method = OBF("\161\159\174") })
    if not ok or not res then return nil, OBF("\204\191\203\207\191\205\206\122\192\187\198\194\201\207") end
    local code = res.StatusCode
    
    if code == 429 and tries < 2 then task.wait(1.5 * (tries + 1)); return getJSON(url, tries + 1) end
    if code and code ~= 200 then
        
        local msg
        pcall(function()
            local b = HttpService:JSONDecode(res.Body)
            msg = (b.errors and b.errors[1] and b.errors[1].message) or b.message
        end)
        return nil, OBF("\162\174\174\170\122") .. tostring(code) .. (msg and (OBF("\122\28\17\122") .. tostring(msg)) or "")
    end
    local ok2, data = pcall(function() return HttpService:JSONDecode(res.Body) end)
    if not ok2 then return nil, OBF("\164\173\169\168\122\195\200\208\29\251\198\195\190\201") end
    return data
end



local CATF = { sort = 0, agg = 5, price = 0 }
local function catfQuery()
    local q = ""
    if CATF.sort ~= 0 then q = q .. OBF("\128\173\201\204\206\174\211\202\191\151") .. CATF.sort end
    if CATF.sort == 1 or CATF.sort == 2 then q = q .. OBF("\128\173\201\204\206\155\193\193\204\191\193\187\206\195\201\200\151") .. CATF.agg end
    if CATF.price == 1 then q = q .. OBF("\128\167\195\200\170\204\195\189\191\151\138\128\167\187\210\170\204\195\189\191\151\138") elseif CATF.price == 2 then q = q .. OBF("\128\167\195\200\170\204\195\189\191\151\139") end
    return q
end


local SOURCES = {
    {
        name = OBF("\155\200\195\199\187\29\1\29\15\191\205\122\130\157\204\191\187\206\201\204\122\173\206\201\204\191\131"),
        fetch = function(kw, token)
            local page = tonumber(token) or 0
            local url = (OBF("\194\206\206\202\205\148\137\137\187\202\195\205\136\204\201\188\198\201\210\136\189\201\199\137\206\201\201\198\188\201\210\135\205\191\204\208\195\189\191\137\208\139\137\199\187\204\197\191\206\202\198\187\189\191\137\140\142\153\198\195\199\195\206\151\127\190\128\202\187\193\191\168\207\199\188\191\204\151\127\190\128\197\191\211\209\201\204\190\151\127\205"))
                :format(CFG.PageSize, page, HttpService:UrlEncode(kw))
            local d, err = getJSON(url)
            if not d then return nil, nil, err end
            local ids = {}
            for _, it in ipairs(d.data or {}) do if it.id then ids[#ids + 1] = it.id end end
            if #ids == 0 then return {}, nil end
            
            local out = {}
            for _, id in ipairs(ids) do out[#out + 1] = { id = id } end
            return out, (#ids >= CFG.PageSize) and (page + 1) or nil
        end,
    },
    {
        name = OBF("\157\187\206\29\251\198\201\193\201\122\130\191\199\201\206\191\205\131"),
        fetch = function(kw, token)
            local function fromToolbox(page)
                
                local url = (OBF("\194\206\206\202\205\148\137\137\187\202\195\205\136\204\201\188\198\201\210\136\189\201\199\137\206\201\201\198\188\201\210\135\205\191\204\208\195\189\191\137\208\139\137\199\187\204\197\191\206\202\198\187\189\191\137\144\139\153\198\195\199\195\206\151\127\190\128\202\187\193\191\168\207\199\188\191\204\151\127\190\128\197\191\211\209\201\204\190\151\127\205"))
                    :format(CFG.PageSize, page, HttpService:UrlEncode(kw))
                local d, err = getJSON(url)
                if not d then return nil, nil, err end
                local out = {}
                for _, it in ipairs(d.data or {}) do if it.id then out[#out + 1] = { id = it.id } end end
                return out, (#out >= CFG.PageSize) and (OBF("\206\148") .. (page + 1)) or nil
            end
            
            if token and tostring(token):sub(1, 2) == OBF("\206\148") then return fromToolbox(tonumber(tostring(token):sub(3)) or 0) end

            
            local function fromCatalog(limit)
                local url = OBF("\194\206\206\202\205\148\137\137\189\187\206\187\198\201\193\136\204\201\188\198\201\210\136\189\201\199\137\208\139\137\205\191\187\204\189\194\137\195\206\191\199\205\137\190\191\206\187\195\198\205\153\157\187\206\191\193\201\204\211\151\139\140\128\173\207\188\189\187\206\191\193\201\204\211\151\141\147\128\166\195\199\195\206\151") .. limit .. catfQuery()
                    .. (kw ~= "" and (OBF("\128\165\191\211\209\201\204\190\151") .. HttpService:UrlEncode(kw)) or "")
                    .. (token and (OBF("\128\157\207\204\205\201\204\151") .. HttpService:UrlEncode(token)) or "")
                local d, err = getJSON(url)
                if not d then return nil, nil, err end
                local out = {}
                for _, it in ipairs(d.data or {}) do
                    if it.id then out[#out + 1] = { id = it.id, name = it.name } end
                end
                local nxt = d.nextPageCursor
                if nxt == "" then nxt = nil end
                return out, nxt
            end
            local items, nxt, err = fromCatalog(CFG.CatalogLimit)
            if not items and err and err:find(OBF("\162\174\174\170\122\142\138\138")) and CFG.CatalogLimit ~= 30 then
                items, nxt, err = fromCatalog(30) 
            end
            if not items and not token then
                local i2, n2, e2 = fromToolbox(0) 
                if i2 then return i2, n2 end
                return nil, nil, tostring(err) .. OBF("\122\122\214\122\122\202\198\187\200\201\122\156\148\122") .. tostring(e2)
            end
            return items, nxt, err
        end,
    },
}


local FC = {}
local function cachedFetch(idx, kw, token)
    local k = idx .. OBF("\214") .. kw .. OBF("\214") .. tostring(token or "") .. OBF("\214") .. catfQuery()
    local hit = FC[k]
    if hit then return hit[1], hit[2] end
    local items, nxt, err = SOURCES[idx].fetch(kw, token)
    if items then FC[k] = { items, nxt } end
    return items, nxt, err
end


local Store = {}
local ASSET_FIELD = { [48] = OBF("\189\198\195\199\188"), [50] = OBF("\192\187\198\198"), [51] = OBF("\195\190\198\191"), [52] = OBF("\196\207\199\202"), [53] = OBF("\204\207\200"), [54] = OBF("\205\209\195\199"), [55] = OBF("\209\187\198\197") }

function Store.search(kw, cursor)
    
    local url = OBF("\194\206\206\202\205\148\137\137\189\187\206\187\198\201\193\136\204\201\188\198\201\210\136\189\201\199\137\208\139\137\205\191\187\204\189\194\137\195\206\191\199\205\137\190\191\206\187\195\198\205\153\157\187\206\191\193\201\204\211\151\139\140\128\173\207\188\189\187\206\191\193\201\204\211\151\141\146\128\166\195\199\195\206\151\141\138") .. catfQuery()
        .. (kw ~= "" and (OBF("\128\165\191\211\209\201\204\190\151") .. HttpService:UrlEncode(kw)) or "")
        .. (cursor and (OBF("\128\157\207\204\205\201\204\151") .. HttpService:UrlEncode(cursor)) or "")
    local d, err = getJSON(url)
    if not d then return nil, nil, err end
    local out = {}
    for _, it in ipairs(d.data or {}) do
        if it.id then out[#out + 1] = { id = it.id, name = it.name or (OBF("\156\207\200\190\198\191\122") .. it.id) } end
    end
    local nxt = d.nextPageCursor
    if nxt == "" then nxt = nil end
    return out, nxt
end


local function innerAnims(assetId)
    local out = {}
    local ok, objs = pcall(function() return game:GetObjects(OBF("\204\188\210\187\205\205\191\206\195\190\148\137\137") .. tostring(assetId)) end)
    if ok and objs then
        for _, o in ipairs(objs) do
            local function add(a) local n = parseId(a.AnimationId); if n ~= 0 then out[#out + 1] = { name = a.Name, id = n } end end
            if o:IsA(OBF("\155\200\195\199\187\206\195\201\200")) then add(o) end
            for _, d in ipairs(o:GetDescendants()) do if d:IsA(OBF("\155\200\195\199\187\206\195\201\200")) then add(d) end end
        end
    end
    table.sort(out, function(a, b) return a.name < b.name end)
    return out
end

function Store.resolve(bundleId, name)
    local d, err = getJSON(OBF("\194\206\206\202\205\148\137\137\189\187\206\187\198\201\193\136\204\201\188\198\201\210\136\189\201\199\137\208\139\137\188\207\200\190\198\191\205\137") .. tostring(bundleId) .. OBF("\137\190\191\206\187\195\198\205"))
    if not d then return nil, err end
    local pack = { key = OBF("\205") .. tostring(bundleId), name = name or d.name or (OBF("\156\207\200\190\198\191\122") .. bundleId), saved = true }
    for _, f in ipairs(PACK_FIELDS) do pack[f] = 0 end
    local got = 0
    for _, it in ipairs(d.items or {}) do
        if it.type == OBF("\155\205\205\191\206") then
            local ok, info = pcall(function() return MarketplaceService:GetProductInfo(it.id, Enum.InfoType.Asset) end)
            local field = ok and info and ASSET_FIELD[info.AssetTypeId]
            if field then
                local anims = innerAnims(it.id)
                if field == OBF("\195\190\198\191") then
                    pack.idle1 = anims[1] and anims[1].id or it.id
                    pack.idle2 = anims[2] and anims[2].id or pack.idle1
                elseif field == OBF("\205\209\195\199") then
                    for _, a in ipairs(anims) do
                        if a.name:lower():find(OBF("\195\190\198\191")) then pack.swimidle = a.id else pack.swim = a.id end
                    end
                    if pack.swim == 0 then pack.swim = it.id end
                else
                    pack[field] = anims[1] and anims[1].id or it.id
                end
                got += 1
            end
        end
    end
    if got == 0 then return nil, OBF("\188\207\200\190\198\191\122\205\191\199\122\187\200\195\199\187\29\1\29\15\191\205\122\190\191\122\199\201\208\195\199\191\200\206\201") end
    return pack
end




local TweenService = game:GetService(OBF("\174\209\191\191\200\173\191\204\208\195\189\191"))
local WHITE = Color3.new(1, 1, 1)

function UI.computeCol()
    local t = THEMES[S.theme]
    UI.col = {
        bg = t.bg,
        panel = t.bg:Lerp(WHITE, 0.055),
        card = t.bg:Lerp(WHITE, 0.10),
        card2 = t.bg:Lerp(WHITE, 0.17),   
        stroke = t.bg:Lerp(WHITE, 0.22),
        primary = t.primary, accent = t.accent,
        text = Color3.fromRGB(240, 242, 250), sub = Color3.fromRGB(140, 146, 172),
        danger = Color3.fromRGB(255, 82, 98), gold = Color3.fromRGB(255, 208, 70),
    }
end
UI.computeCol()

local function mk(class, props, parent)
    local o = Instance.new(class)
    for k, v in pairs(props) do o[k] = v end
    if parent then o.Parent = parent end
    return o
end
local function th(o, prop, key)
    UI.themed[#UI.themed + 1] = { o, prop, key }
    o[prop] = UI.col[key]
end
local function corner(o, r) return mk(OBF("\175\163\157\201\204\200\191\204"), { CornerRadius = UDim.new(0, r) }, o) end
local function nextOrder(p) UI.orders[p] = (UI.orders[p] or 0) + 1; return UI.orders[p] end

local function tw(o, props, t, style, dir)
    local ok, tween = pcall(function()
        return TweenService:Create(o, TweenInfo.new(t or 0.15, style or Enum.EasingStyle.Quad, dir or Enum.EasingDirection.Out), props)
    end)
    if ok and tween then tween:Play() end
    return tween
end


local function stroke(o, key, thick, transp)
    local s = mk(OBF("\175\163\173\206\204\201\197\191"), { Thickness = thick or 1, Transparency = transp or 0, ApplyStrokeMode = Enum.ApplyStrokeMode.Border }, o)
    th(s, OBF("\157\201\198\201\204"), key or OBF("\205\206\204\201\197\191"))
    return s
end


local function gradient(o, k0, k1, rot)
    o.BackgroundColor3 = WHITE
    local g = mk(OBF("\175\163\161\204\187\190\195\191\200\206"), { Rotation = rot or 90 }, o)
    local function paint() g.Color = ColorSequence.new(UI.col[k0], UI.col[k1]) end
    UI.paints[#UI.paints + 1] = paint
    paint()
    return g
end


local function hoverFx(b, key)
    local function base() return UI.col[key] end
    b.MouseEnter:Connect(function() tw(b, { BackgroundColor3 = base():Lerp(WHITE, 0.12) }, 0.12) end)
    b.MouseLeave:Connect(function() tw(b, { BackgroundColor3 = base() }, 0.14) end)
    b.Activated:Connect(function() task.delay(0.15, function() if b.Parent then tw(b, { BackgroundColor3 = base() }, 0.18) end end) end)
end

function UI.recolor()
    UI.computeCol()
    local keep = {}
    for _, e in ipairs(UI.themed) do
        if e[1] and e[1].Parent then
            keep[#keep + 1] = e
            pcall(function() e[1][e[2]] = UI.col[e[3]] end)
        end
    end
    UI.themed = keep 
    for _, p in ipairs(UI.paints) do pcall(p) end
    for _, r in ipairs(UI.refreshers) do pcall(r) end
end

local function label(parent, text, size, key, font, extra)
    local l = mk(OBF("\174\191\210\206\166\187\188\191\198"), {
        BackgroundTransparency = 1, Text = text, TextSize = size or 12, Font = font or Enum.Font.GothamMedium,
        TextXAlignment = Enum.TextXAlignment.Left, TextWrapped = true,
    }, parent)
    if extra then for k, v in pairs(extra) do l[k] = v end end
    th(l, OBF("\174\191\210\206\157\201\198\201\204\141"), key or OBF("\206\191\210\206"))
    return l
end

local function button(parent, text, size, onClick, key)
    key = key or OBF("\189\187\204\190")
    local b = mk(OBF("\174\191\210\206\156\207\206\206\201\200"), {
        Size = size, AutoButtonColor = false, Text = text, Font = Enum.Font.GothamBold, TextSize = 11, BorderSizePixel = 0,
    }, parent)
    th(b, OBF("\156\187\189\197\193\204\201\207\200\190\157\201\198\201\204\141"), key); th(b, OBF("\174\191\210\206\157\201\198\201\204\141"), OBF("\206\191\210\206")); corner(b, 8)
    if key == OBF("\202\204\195\199\187\204\211") then stroke(b, OBF("\187\189\189\191\200\206"), 1, 0.55) else stroke(b, OBF("\205\206\204\201\197\191"), 1, 0.4) end
    hoverFx(b, key)
    b.Activated:Connect(function() sound(OBF("\189\198\195\189\197")); onClick(b) end)
    return b
end

local function textbox(parent, placeholder, size, pos)
    local t = mk(OBF("\174\191\210\206\156\201\210"), {
        Size = size, Position = pos or UDim2.new(), PlaceholderText = placeholder, Text = "", ClearTextOnFocus = false,
        Font = Enum.Font.Gotham, TextSize = 11, BorderSizePixel = 0, TextXAlignment = Enum.TextXAlignment.Left,
    }, parent)
    th(t, OBF("\156\187\189\197\193\204\201\207\200\190\157\201\198\201\204\141"), OBF("\202\187\200\191\198")); th(t, OBF("\174\191\210\206\157\201\198\201\204\141"), OBF("\206\191\210\206")); th(t, OBF("\170\198\187\189\191\194\201\198\190\191\204\157\201\198\201\204\141"), OBF("\205\207\188"))
    corner(t, 8); mk(OBF("\175\163\170\187\190\190\195\200\193"), { PaddingLeft = UDim.new(0, 10), PaddingRight = UDim.new(0, 6) }, t)
    local st = stroke(t, OBF("\205\206\204\201\197\191"), 1, 0.2)
    t.Focused:Connect(function() st.Color = UI.col.accent; st.Transparency = 0 end)
    t.FocusLost:Connect(function() st.Color = UI.col.stroke; st.Transparency = 0.2 end)
    return t
end

local function chips(parent, names, onPick, initial)
    local sel = initial or 1
    local btns, strokes = {}, {}
    local function paint(instant)
        for i, b in ipairs(btns) do
            local on = (i == sel)
            local bg = on and UI.col.primary or UI.col.card
            if instant then b.BackgroundColor3 = bg else tw(b, { BackgroundColor3 = bg }, 0.15) end
            b.TextColor3 = on and UI.col.text or UI.col.sub
            strokes[i].Color = on and UI.col.accent or UI.col.stroke
            strokes[i].Transparency = on and 0.35 or 0.5
        end
    end
    for i, n in ipairs(names) do
        local b = mk(OBF("\174\191\210\206\156\207\206\206\201\200"), {
            Size = UDim2.new(0, 0, 1, 0), AutomaticSize = Enum.AutomaticSize.X, AutoButtonColor = false, Text = n,
            Font = Enum.Font.GothamBold, TextSize = 11, BorderSizePixel = 0, LayoutOrder = i,
        }, parent)
        mk(OBF("\175\163\170\187\190\190\195\200\193"), { PaddingLeft = UDim.new(0, 12), PaddingRight = UDim.new(0, 12) }, b)
        corner(b, 14)
        strokes[i] = mk(OBF("\175\163\173\206\204\201\197\191"), { Thickness = 1, ApplyStrokeMode = Enum.ApplyStrokeMode.Border }, b)
        b.MouseEnter:Connect(function() if i ~= sel then tw(b, { BackgroundColor3 = UI.col.card2 }, 0.1) end end)
        b.MouseLeave:Connect(function() if i ~= sel then tw(b, { BackgroundColor3 = UI.col.card }, 0.12) end end)
        b.Activated:Connect(function() sel = i; paint(); sound(OBF("\189\198\195\189\197")); onPick(i) end)
        btns[i] = b
    end
    UI.paints[#UI.paints + 1] = paint
    paint(true)
    return { get = function() return sel end, set = function(i) sel = i; paint() end }
end

