function UI.emoteCard(grid, id, name, onRemove)
    if name then Names.cache[id] = name end
    local c = mk(OBF("\174\191\210\206\156\207\206\206\201\200"), { AutoButtonColor = false, Text = "", BackgroundColor3 = UI.col.card, BorderSizePixel = 0 }, grid)
    corner(c, 11)
    local st = mk(OBF("\175\163\173\206\204\201\197\191"), { Color = UI.col.stroke, Thickness = 1, Transparency = 0.5, ApplyStrokeMode = Enum.ApplyStrokeMode.Border }, c)
    local img = mk(OBF("\163\199\187\193\191\166\187\188\191\198"), {
        Size = UDim2.new(1, -12, 0, 72), Position = UDim2.fromOffset(6, 6), BackgroundColor3 = UI.col.panel,
        Image = (OBF("\204\188\210\206\194\207\199\188\148\137\137\206\211\202\191\151\155\205\205\191\206\128\195\190\151\127\190\128\209\151\139\143\138\128\194\151\139\143\138")):format(id), ScaleType = Enum.ScaleType.Fit, BorderSizePixel = 0,
    }, c)
    corner(img, 8)
    
    local eye = mk(OBF("\174\191\210\206\156\207\206\206\201\200"), {
        Position = UDim2.new(1, -25, 0, 3), Size = UDim2.fromOffset(22, 22), BackgroundColor3 = UI.col.bg, BackgroundTransparency = 0.3,
        Text = OBF("\74\249\235\219"), TextSize = 12, Font = Enum.Font.GothamBold, TextColor3 = UI.col.text, BorderSizePixel = 0, AutoButtonColor = false,
    }, img)
    corner(eye, 7)
    eye.MouseEnter:Connect(function() tw(eye, { BackgroundTransparency = 0, BackgroundColor3 = UI.col.primary }, 0.1) end)
    eye.MouseLeave:Connect(function() tw(eye, { BackgroundTransparency = 0.3, BackgroundColor3 = UI.col.bg }, 0.12) end)
    eye.Activated:Connect(function() sound(OBF("\189\198\195\189\197")); UI.previewEmote(id, Names.cache[id]) end)
    local nm = mk(OBF("\174\191\210\206\166\187\188\191\198"), {
        Position = UDim2.fromOffset(8, 82), Size = UDim2.new(1, -16, 0, 14), BackgroundTransparency = 1, Text = OBF("\136\136\136"),
        TextColor3 = UI.col.text, Font = Enum.Font.GothamMedium, TextSize = 10, TextTruncate = Enum.TextTruncate.AtEnd,
        TextXAlignment = Enum.TextXAlignment.Left,
    }, c)
    
    local tagBar = mk(OBF("\160\204\187\199\191"), { Position = UDim2.fromOffset(0, 12), Size = UDim2.fromOffset(4, 54), BorderSizePixel = 0, Visible = false, BackgroundColor3 = WHITE }, c)
    corner(tagBar, 2)
    local function paintTag()
        if not nm.Parent then return end
        local t = S.tags[id]
        if t and t.c then tagBar.Visible = true; tagBar.BackgroundColor3 = TAG_COLORS[t.c] else tagBar.Visible = false end
        if t and t.n and t.n ~= "" then nm.Text = t.n elseif Names.cache[id] then nm.Text = Names.cache[id] end
    end
    Names.get(id, function() paintTag() end)
    paintTag()

    local hasTabs = #S.userTabs > 0
    local count = (onRemove and 4 or 3) + (hasTabs and 1 or 0)
    local strip = mk(OBF("\160\204\187\199\191"), { Position = UDim2.new(0, 6, 1, -28), Size = UDim2.new(1, -9, 0, 22), BackgroundTransparency = 1 }, c)
    mk(OBF("\175\163\166\195\205\206\166\187\211\201\207\206"), { FillDirection = Enum.FillDirection.Horizontal, Padding = UDim.new(0, 3), SortOrder = Enum.SortOrder.LayoutOrder }, strip)

    local bCopy = miniBtn(strip, OBF("\74\249\237\229"), 1, nil, count)
    bCopy.Activated:Connect(function() sound(OBF("\189\198\195\189\197")); copyText(tostring(id)) end)

    local function paintStar(b, on) b.Text = on and OBF("\60\242\223") or OBF("\60\242\224"); b.TextColor3 = on and UI.col.gold or UI.col.accent end
    local bFav = miniBtn(strip, OBF("\60\242\224"), 2, nil, count)
    paintStar(bFav, isFav(id))
    bFav.Activated:Connect(function()
        paintStar(bFav, toggleFav(id)); sound(OBF("\189\198\195\189\197"))
        if UI.emoteKey == OBF("\192\187\208") and UI.refreshEmotes then UI.refreshEmotes() end
    end)

    local bWheel = miniBtn(strip, OBF("\74\249\232\251"), 3, nil, count)
    bWheel.Activated:Connect(function() WH.add(id) end)

    if hasTabs then 
        local bTab = miniBtn(strip, OBF("\74\249\237\219"), 4, nil, count)
        bTab.Activated:Connect(function() sound(OBF("\189\198\195\189\197")); UI.tabPicker(bTab, id) end)
    end

    if onRemove then
        local bDel = miniBtn(strip, OBF("\60\246\239"), 5, nil, count)
        bDel.TextColor3 = UI.col.danger
        bDel.Activated:Connect(function() sound(OBF("\189\198\195\189\197")); onRemove(id) end)
    end
    if count >= 5 then 
        for _, b in ipairs(strip:GetChildren()) do if b:IsA(OBF("\174\191\210\206\156\207\206\206\201\200")) then b.TextSize = 10 end end
    end

    c.MouseEnter:Connect(function() tw(c, { BackgroundColor3 = UI.col.card2 }, 0.12); tw(st, { Transparency = 0.05, Color = UI.col.accent }, 0.12) end)
    c.MouseLeave:Connect(function() tw(c, { BackgroundColor3 = UI.col.card }, 0.14); tw(st, { Transparency = 0.5, Color = UI.col.stroke }, 0.14) end)
    local held, pressT, pressPos = false, nil, nil
    c.InputBegan:Connect(function(i)
        if i.UserInputType == Enum.UserInputType.MouseButton1 or i.UserInputType == Enum.UserInputType.Touch then
            held = false
            local my = os.clock(); pressT = my; pressPos = i.Position
            task.delay(0.55, function()
                if pressT == my and c.Parent then held = true; sound(OBF("\189\198\195\189\197")); UI.tagEditor(c, id, paintTag) end
            end)
        end
    end)
    c.InputChanged:Connect(function(i) 
        if pressT and pressPos and (i.UserInputType == Enum.UserInputType.MouseMovement or i.UserInputType == Enum.UserInputType.Touch)
            and (Vector2.new(i.Position.X, i.Position.Y) - Vector2.new(pressPos.X, pressPos.Y)).Magnitude > 14 then pressT = nil end
    end)
    c.InputEnded:Connect(function(i)
        if i.UserInputType == Enum.UserInputType.MouseButton1 or i.UserInputType == Enum.UserInputType.Touch then pressT = nil end
    end)
    c.Activated:Connect(function()
        if held then held = false; return end
        sound(OBF("\189\198\195\189\197")); task.spawn(E.play, id)
        
        st.Color = UI.col.primary; st.Thickness = 2
        task.delay(0.18, function() if st.Parent then st.Thickness = 1; st.Color = UI.col.accent end end)
    end)
    return c
end


