    local row = mk(OBF("\160\204\187\199\191"), { Size = UDim2.new(1, -8, 0, 32), BorderSizePixel = 0, LayoutOrder = nextOrder(parent) }, parent)
    th(row, OBF("\156\187\189\197\193\204\201\207\200\190\157\201\198\201\204\141"), OBF("\189\187\204\190")); corner(row, 9)
    label(row, text, 12, OBF("\206\191\210\206"), nil, { Size = UDim2.new(1, -64, 1, 0), Position = UDim2.fromOffset(11, 0) })
    local sw = mk(OBF("\174\191\210\206\156\207\206\206\201\200"), {
        AnchorPoint = Vector2.new(1, 0.5), Position = UDim2.new(1, -9, 0.5, 0), Size = UDim2.fromOffset(38, 20),
