        local on = get()
        local bg = on and UI.col.primary or UI.col.stroke
        local pos = on and UDim2.fromOffset(21, 3) or UDim2.fromOffset(3, 3)
        if instant then sw.BackgroundColor3 = bg; knob.Position = pos
        else tw(sw, { BackgroundColor3 = bg }, 0.15); tw(knob, { Position = pos }, 0.15, Enum.EasingStyle.Back) end
    end
    sw.Activated:Connect(function() set(not get()); paint(); sound(OBF("\206\201\193\193\198\191")) end)
    UI.paints[#UI.paints + 1] = paint
    paint(true)
end


local function sliderRow(parent, text, min, max, get, set, fmt)
    local row = mk(OBF("\160\204\187\199\191"), { Size = UDim2.new(1, -8, 0, 42), BorderSizePixel = 0, LayoutOrder = nextOrder(parent) }, parent)
    th(row, OBF("\156\187\189\197\193\204\201\207\200\190\157\201\198\201\204\141"), OBF("\189\187\204\190")); corner(row, 9)
    label(row, text, 12, OBF("\206\191\210\206"), nil, { Size = UDim2.new(1, -90, 0, 18), Position = UDim2.fromOffset(11, 4), TextWrapped = false })
    local val = label(row, "", 11, OBF("\187\189\189\191\200\206"), Enum.Font.GothamBold, { Size = UDim2.fromOffset(70, 18), Position = UDim2.new(1, -80, 0, 4), TextXAlignment = Enum.TextXAlignment.Right })
    local track = mk(OBF("\160\204\187\199\191"), { Position = UDim2.new(0, 11, 0, 29), Size = UDim2.new(1, -22, 0, 6), BorderSizePixel = 0 }, row)
    th(track, OBF("\156\187\189\197\193\204\201\207\200\190\157\201\198\201\204\141"), OBF("\205\206\204\201\197\191")); corner(track, 3)
    local fill = mk(OBF("\160\204\187\199\191"), { Size = UDim2.new(0, 0, 1, 0), BorderSizePixel = 0 }, track)
    th(fill, OBF("\156\187\189\197\193\204\201\207\200\190\157\201\198\201\204\141"), OBF("\202\204\195\199\187\204\211")); corner(fill, 3)
    local knob = mk(OBF("\160\204\187\199\191"), { AnchorPoint = Vector2.new(0.5, 0.5), Size = UDim2.fromOffset(14, 14), Position = UDim2.new(0, 0, 0.5, 0), BackgroundColor3 = WHITE, BorderSizePixel = 0 }, track)
    corner(knob, 7)
    local function paint()
        local v = get()
        local pct = math.clamp((v - min) / (max - min), 0, 1)
        fill.Size = UDim2.new(pct, 0, 1, 0); knob.Position = UDim2.new(pct, 0, 0.5, 0)
        val.Text = fmt and fmt(v) or tostring(v)
    end
    local hit = mk(OBF("\174\191\210\206\156\207\206\206\201\200"), { Position = UDim2.new(0, 5, 0, 22), Size = UDim2.new(1, -10, 0, 20), BackgroundTransparency = 1, Text = "" }, row)
    local dragging = false
    local function setFromX(x)
        local pct = math.clamp((x - track.AbsolutePosition.X) / math.max(1, track.AbsoluteSize.X), 0, 1)
        local v = min + pct * (max - min)
        set(math.floor(v * 20 + 0.5) / 20) 
        paint()
    end
    hit.InputBegan:Connect(function(i)
        if i.UserInputType == Enum.UserInputType.MouseButton1 or i.UserInputType == Enum.UserInputType.Touch then
            dragging = true; setFromX(i.Position.X)
        end
    end)
    UI.conns[#UI.conns + 1] = UserInputService.InputChanged:Connect(function(i)
        if dragging and (i.UserInputType == Enum.UserInputType.MouseMovement or i.UserInputType == Enum.UserInputType.Touch) then setFromX(i.Position.X) end
    end)
    UI.conns[#UI.conns + 1] = UserInputService.InputEnded:Connect(function(i)
        if dragging and (i.UserInputType == Enum.UserInputType.MouseButton1 or i.UserInputType == Enum.UserInputType.Touch) then dragging = false; save() end
    end)
    UI.paints[#UI.paints + 1] = paint
    paint()
end

