local function makeDraggable(handle, target, getScale, onEnd, onClick)
    local dragging, moved, startIn, startPos, dragInput = false, false, nil, nil, nil
    handle.InputBegan:Connect(function(i)
        if i.UserInputType == Enum.UserInputType.MouseButton1 or i.UserInputType == Enum.UserInputType.Touch then
            dragging = true; moved = false; startIn = i.Position; startPos = target.Position; dragInput = i
        end
    end)
    UI.conns[#UI.conns + 1] = UserInputService.InputChanged:Connect(function(i)
        if not dragging then return end
        if i.UserInputType == Enum.UserInputType.MouseMovement or i == dragInput then
            local d = i.Position - startIn
            if d.Magnitude > 6 then moved = true end
            if moved then
                local sc = getScale()
                target.Position = UDim2.new(startPos.X.Scale, startPos.X.Offset + d.X / sc, startPos.Y.Scale, startPos.Y.Offset + d.Y / sc)
            end
        end
    end)
    UI.conns[#UI.conns + 1] = UserInputService.InputEnded:Connect(function(i)
        if dragging and (i.UserInputType == Enum.UserInputType.MouseButton1 or i == dragInput) then
            dragging = false
            if moved then if onEnd then onEnd() end elseif onClick then onClick() end
        end
    end)
end

