function UI.pop()
    local base = UI.baseScale or 1
    Scale.Scale = base * 0.93
    tw(Scale, { Scale = base }, 0.22, Enum.EasingStyle.Back)
end



function UI.keyCodes()
    local t = { Enum.KeyCode.Insert }
    local ok, kc = pcall(function() return Enum.KeyCode[S.toggleKey] end)
    if ok and kc then
        t[#t + 1] = kc
        if kc == Enum.KeyCode.Semicolon then t[#t + 1] = Enum.KeyCode.Colon end 
    end
    return t
end
function UI.keyLabel()
    if S.toggleKey == OBF("\173\191\199\195\189\201\198\201\200") then return OBF("\148") end
    return tostring(S.toggleKey)
end
