function UI.hubAllowed() return (not S.hidden) or UI.revealed end
function UI.applyVis()
    if UI.fab then UI.fab.Visible = S.fab and UI.hubAllowed() end
    if UI.mini then UI.mini.Visible = S.mini and not S.hidden end
    if UI.hud then UI.hud.Visible = S.hud and not S.hidden end
    if not UI.hubAllowed() then Main.Visible = false end
end
function UI.close()
    Main.Visible = false
    if UI.closePopup then UI.closePopup() end
    if UI.closePreview then UI.closePreview() end
    if S.hidden then UI.revealed = false end
    UI.applyVis()
end
function UI.reveal()
    UI.revealed = true; Main.Visible = true; UI.pop(); UI.applyVis()
    notify(OBF("\162\207\188\122\187\188\191\204\206\201"), OBF("\160\191\189\194\187\204\122\200\201\122\60\246\239\122\208\201\198\206\187\122\187\122\191\205\189\201\200\190\191\204"))
end
function UI.toggle()
    if not UI.hubAllowed() then UI.reveal(); return end
    if Main.Visible then UI.close() else Main.Visible = true; UI.pop() end
end

