local pages, pageBtns = {}, {}
local function newPage(name, icon)
    local p = mk(OBF("\160\204\187\199\191"), { Size = UDim2.new(1, 0, 1, 0), BackgroundTransparency = 1, Visible = false }, Content)
    pages[name] = p
    local b = mk(OBF("\174\191\210\206\156\207\206\206\201\200"), {
        Size = UDim2.new(1, 0, 0, 34), AutoButtonColor = false, Text = "", BorderSizePixel = 0, LayoutOrder = #pageBtns + 1,
        BackgroundColor3 = UI.col.card, BackgroundTransparency = 1,
    }, SideList)
    corner(b, 9)
    local bar = mk(OBF("\160\204\187\199\191"), { AnchorPoint = Vector2.new(0, 0.5), Position = UDim2.new(0, 0, 0.5, 0), Size = UDim2.fromOffset(3, 16), BorderSizePixel = 0, Visible = false }, b)
    corner(bar, 2); th(bar, OBF("\156\187\189\197\193\204\201\207\200\190\157\201\198\201\204\141"), OBF("\187\189\189\191\200\206"))
    local ic = mk(OBF("\174\191\210\206\166\187\188\191\198"), { Position = UDim2.fromOffset(11, 0), Size = UDim2.fromOffset(20, 34), BackgroundTransparency = 1, Text = icon, TextSize = 14, Font = Enum.Font.GothamBold }, b)
    local lb = mk(OBF("\174\191\210\206\166\187\188\191\198"), {
        Position = UDim2.fromOffset(36, 0), Size = UDim2.new(1, -40, 1, 0), BackgroundTransparency = 1, Text = name,
        Font = Enum.Font.GothamBold, TextSize = 12, TextXAlignment = Enum.TextXAlignment.Left,
    }, b)
    pageBtns[name] = { btn = b, bar = bar, ic = ic, lb = lb }
    b.MouseEnter:Connect(function() if UI.current ~= name then tw(b, { BackgroundTransparency = 0.6, BackgroundColor3 = UI.col.card }, 0.1) end end)
    b.MouseLeave:Connect(function() if UI.current ~= name then tw(b, { BackgroundTransparency = 1 }, 0.12) end end)
    b.Activated:Connect(function() sound(OBF("\189\198\195\189\197")); UI.show(name) end)
    return p
end
function UI.show(name)
    if not pages[name] then name = OBF("\159\199\201\206\191\205") end
    local changed = (UI.current ~= name)
    for n, p in pairs(pages) do p.Visible = (n == name) end
    if changed then 
        pages[name].Position = UDim2.fromOffset(0, 10)
        tw(pages[name], { Position = UDim2.new() }, 0.2)
    end
    for n, e in pairs(pageBtns) do
        local on = (n == name)
        tw(e.btn, { BackgroundTransparency = on and 0 or 1, BackgroundColor3 = on and UI.col.primary or UI.col.card }, 0.15)
        e.bar.Visible = on
        e.lb.TextColor3 = on and UI.col.text or UI.col.sub
        e.ic.TextColor3 = on and UI.col.text or UI.col.sub
    end
    UI.current = name
    if UI.closePopup then UI.closePopup() end
    if UI.closePreview then UI.closePreview() end
    local f = UI.firstShow[name]
    if f then UI.firstShow[name] = nil; task.defer(f) end
    if S.page ~= name then S.page = name; save() end
end
UI.paints[#UI.paints + 1] = function() if UI.current then UI.show(UI.current) end end




function UI.placePopup(pop, anchor)
    task.defer(function()
        if not pop.Parent or not anchor.Parent then return end
        local cam = workspace.CurrentCamera
        local vp = cam and cam.ViewportSize or Vector2.new(1280, 720)
        local ap, as = anchor.AbsolutePosition, anchor.AbsoluteSize
        local w, h = pop.AbsoluteSize.X, pop.AbsoluteSize.Y
        local x = math.clamp(ap.X, 8, math.max(8, vp.X - w - 8))
        local y = ap.Y + as.Y + 5
        if y + h > vp.Y - 8 then y = math.max(8, ap.Y - h - 5) end
        pop.Position = UDim2.fromOffset(x, y)
    end)
end


