do
    local page = newPage(OBF("\159\199\201\206\191\205"), OBF("\74\249\232\7"))
    local BASE_KEYS = { OBF("\139"), OBF("\140"), OBF("\141"), OBF("\189\207\205\206\201\199"), OBF("\192\187\208"), OBF("\204\191\189\191\200\206"), OBF("\206\201\202"), OBF("\209\194\191\191\198") }
    local BASE_NAMES = { TABS[1].name, TABS[2].name, TABS[3].name, OBF("\157\207\205\206\201\199"), OBF("\60\242\223\122\160\187\208\205"), OBF("\172\191\189\191\200\206\191\205"), OBF("\174\201\202"), OBF("\74\249\232\251\122\172\201\190\187") }
    local keys, names = {}, {}

    
    local function userTab(key)
        local tid = type(key) == OBF("\205\206\204\195\200\193") and key:match(OBF("\184\206\148\130\136\133\131\126"))
        if not tid then return nil end
        for _, t in ipairs(S.userTabs) do if t.id == tid then return t end end
        return nil
    end
    local function rebuildKeys()
        keys, names = {}, {}
        for i, k in ipairs(BASE_KEYS) do keys[i] = k; names[i] = BASE_NAMES[i] end
        for _, t in ipairs(S.userTabs) do keys[#keys + 1] = OBF("\206\148") .. t.id; names[#names + 1] = OBF("\74\249\237\219\122") .. t.name end
    end
    rebuildKeys()
    local initial = table.find(keys, S.emoteKey) or 1
    UI.emoteKey = keys[initial]

    local function items(key)
        local out = {}
        local ut = userTab(key)
        if ut then for _, id in ipairs(ut.ids) do out[#out + 1] = id end
        elseif key == OBF("\192\187\208") then for _, id in ipairs(S.favs) do out[#out + 1] = id end
        elseif key == OBF("\204\191\189\191\200\206") then for _, id in ipairs(S.recents) do out[#out + 1] = id end
        elseif key == OBF("\189\207\205\206\201\199") then for _, id in ipairs(S.customEmotes) do out[#out + 1] = id end
        elseif key == OBF("\209\194\191\191\198") then for _, id in ipairs(S.wheel) do out[#out + 1] = id end
        elseif key == OBF("\206\201\202") then
            local arr = {}
            for k, v in pairs(S.stats) do if tonumber(k) then arr[#arr + 1] = { tonumber(k), v } end end
            table.sort(arr, function(a, b) return a[2] > b[2] end)
            for i = 1, math.min(#arr, 24) do out[i] = arr[i][1] end
        else
            local tab = TABS[tonumber(key)]
            if tab then for _, r in ipairs(tab.ids) do local id = parseId(r); if id ~= 0 then out[#out + 1] = id end end end
        end
        return out
    end
    UI.emoteItems = items

    local grid
    local function removeFor(key)
        local ut = userTab(key)
        if ut then
            return function(id)
                local i = table.find(ut.ids, id); if i then table.remove(ut.ids, i); save() end
                UI.refreshEmotes()
            end
        elseif key == OBF("\189\207\205\206\201\199") then
            return function(id)
                local i = table.find(S.customEmotes, id); if i then table.remove(S.customEmotes, i); save() end
                UI.refreshEmotes()
            end
        elseif key == OBF("\209\194\191\191\198") then
            return function(id) WH.remove(id); UI.refreshEmotes() end
        end
        return nil
    end
    function UI.refreshEmotes()
        clearKids(grid)
        local rm = removeFor(UI.emoteKey)
        for i, id in ipairs(items(UI.emoteKey)) do UI.emoteCard(grid, id, nil, rm).LayoutOrder = i end
    end

    local row = chipRow(page, UDim2.new())
    local c, showNew, addBtn
    local function updateAddBtn()
        if addBtn then addBtn.Text = userTab(UI.emoteKey) and OBF("\133\122\155\188\187") or OBF("\133\122\157\207\205\206\201\199") end
    end
    local function buildChips()
        clearKids(row)
        rebuildKeys()
        if not table.find(keys, UI.emoteKey) then UI.emoteKey = keys[1]; S.emoteKey = keys[1] end
        local cur = table.find(keys, UI.emoteKey) or 1
        local shown = {}
        for i, n in ipairs(names) do shown[i] = n end
        if #S.userTabs < CFG.MaxUserTabs then shown[#shown + 1] = OBF("\73\22\229\122\155\188\187") end
        if UI.chipPaint then 
            local i = table.find(UI.paints, UI.chipPaint); if i then table.remove(UI.paints, i) end
        end
        c = chips(row, shown, function(i)
            if i > #keys then 
                c.set(table.find(keys, UI.emoteKey) or 1)
                showNew(true)
                return
            end
            UI.emoteKey = keys[i]; S.emoteKey = keys[i]; save(); UI.refreshEmotes(); updateAddBtn()
        end, cur)
        UI.chipPaint = UI.paints[#UI.paints]
    end

    local inRow = mk(OBF("\160\204\187\199\191"), { Position = UDim2.fromOffset(0, 35), Size = UDim2.new(1, 0, 0, 28), BackgroundTransparency = 1 }, page)
    local box = textbox(inRow, OBF("\189\201\198\191\122\163\158\122\201\207\122\198\195\200\197\122\190\201\122\191\199\201\206\191"), UDim2.new(1, -150, 1, 0))
    UI.idBox = box
    button(inRow, OBF("\60\240\16"), UDim2.new(0, 30, 1, 0), function()
        local id = parseId(box.Text)
        if id == 0 then notify(OBF("\163\158\122\195\200\208\29\251\198\195\190\201"), OBF("\157\201\198\191\122\207\199\122\200\29\20\199\191\204\201\122\201\207\122\198\195\200\197")); sound(OBF("\191\204\204\201\204")); return end
        task.spawn(E.play, id)
    end, OBF("\202\204\195\199\187\204\211")).Position = UDim2.new(1, -146, 0, 0)
    addBtn = button(inRow, OBF("\133\122\157\207\205\206\201\199"), UDim2.new(0, 62, 1, 0), function()
        local id = parseId(box.Text)
        if id == 0 then notify(OBF("\163\158\122\195\200\208\29\251\198\195\190\201"), OBF("\157\201\198\191\122\207\199\122\200\29\20\199\191\204\201\122\201\207\122\198\195\200\197")); sound(OBF("\191\204\204\201\204")); return end
        local ut = userTab(UI.emoteKey)
        if ut then 
            if not table.find(ut.ids, id) then table.insert(ut.ids, 1, id); save() end
            notify(ut.name, OBF("\173\187\198\208\201\122\130") .. #ut.ids .. OBF("\131"))
            UI.refreshEmotes()
            return
        end
        if not table.find(S.customEmotes, id) then table.insert(S.customEmotes, id); save() end
        notify(OBF("\157\207\205\206\201\199"), OBF("\173\187\198\208\201\122\130") .. #S.customEmotes .. OBF("\131"))
        c.set(4); UI.emoteKey = OBF("\189\207\205\206\201\199"); S.emoteKey = OBF("\189\207\205\206\201\199"); save(); UI.refreshEmotes(); updateAddBtn()
    end)
    addBtn.Position = UDim2.new(1, -112, 0, 0)
    button(inRow, OBF("\74\249\232\251\133"), UDim2.new(0, 46, 1, 0), function()
        local id = parseId(box.Text)
        if id == 0 then notify(OBF("\163\158\122\195\200\208\29\251\198\195\190\201"), OBF("\157\201\198\191\122\207\199\122\200\29\20\199\191\204\201\122\201\207\122\198\195\200\197")); sound(OBF("\191\204\204\201\204")); return end
        WH.add(id)
        if UI.emoteKey == OBF("\209\194\191\191\198") then UI.refreshEmotes() end
    end).Position = UDim2.new(1, -46, 0, 0)

    
    local newRow = mk(OBF("\160\204\187\199\191"), { Position = UDim2.fromOffset(0, 35), Size = UDim2.new(1, 0, 0, 28), BackgroundTransparency = 1, Visible = false }, page)
    local nbox = textbox(newRow, OBF("\200\201\199\191\122\190\187\122\200\201\208\187\122\187\188\187"), UDim2.new(1, -112, 1, 0))
    local function createTab()
        local nm = nbox.Text:gsub(OBF("\184\127\205\133"), ""):gsub(OBF("\127\205\133\126"), "")
        nm = nm:sub(1, 14)
        if nm == "" then notify(OBF("\155\188\187"), OBF("\158\29\251\122\207\199\122\200\201\199\191\122\202\204\187\122\187\188\187")); sound(OBF("\191\204\204\201\204")); return end
        if #S.userTabs >= CFG.MaxUserTabs then notify(OBF("\155\188\187"), OBF("\166\195\199\195\206\191\122\190\191\122") .. CFG.MaxUserTabs .. OBF("\122\187\188\187\205")); sound(OBF("\191\204\204\201\204")); return end
        for _, t in ipairs(S.userTabs) do
            if t.name:lower() == nm:lower() then notify(OBF("\155\188\187"), OBF("\164\29\251\122\191\210\195\205\206\191\122\207\199\187\122\187\188\187\122\189\201\199\122\191\205\205\191\122\200\201\199\191")); sound(OBF("\191\204\204\201\204")); return end
        end
        local tab = { id = HttpService:GenerateGUID(false):sub(1, 8), name = nm, ids = {} }
        S.userTabs[#S.userTabs + 1] = tab
        UI.emoteKey = OBF("\206\148") .. tab.id; S.emoteKey = UI.emoteKey; save()
        showNew(false); buildChips(); updateAddBtn(); UI.refreshEmotes()
        if UI.refreshTabsMgr then UI.refreshTabsMgr() end
        notify(OBF("\155\188\187\122\189\204\195\187\190\187"), nm .. OBF("\122\122\28\17\122\122\188\201\206\187\204\122\191\199\201\206\191\148\122\133\122\155\188\187\122\201\207\122\74\249\237\219\122\200\201\205\122\189\187\204\190\205"))
    end
    button(newRow, OBF("\157\204\195\187\204"), UDim2.new(0, 58, 1, 0), createTab, OBF("\202\204\195\199\187\204\211")).Position = UDim2.new(1, -106, 0, 0)
    button(newRow, OBF("\60\246\239"), UDim2.new(0, 46, 1, 0), function() showNew(false) end).Position = UDim2.new(1, -46, 0, 0)
    nbox.FocusLost:Connect(function(enter) if enter then createTab() end end)
    showNew = function(v)
        newRow.Visible = v; inRow.Visible = not v
        if v then nbox.Text = ""; task.defer(function() pcall(function() nbox:CaptureFocus() end) end) end
    end

    grid = gridOf(page, UDim2.fromOffset(0, 72), UDim2.new(1, 0, 1, -72))
    UI.refreshers[#UI.refreshers + 1] = UI.refreshEmotes
    function UI.rebuildEmoteTabs() buildChips(); updateAddBtn(); UI.refreshEmotes() end
    buildChips(); updateAddBtn()
    UI.refreshEmotes()
end


function UI.skeleton(parent, n, h)
    for i = 1, n do
        local f = mk(OBF("\160\204\187\199\191"), { Name = OBF("\173\197\191\198"), BackgroundColor3 = UI.col.card, BorderSizePixel = 0, LayoutOrder = -1000 + i, Size = UDim2.new(1, -6, 0, h or 54) }, parent)
        corner(f, 11)
        pcall(function()
            TweenService:Create(f, TweenInfo.new(0.8, Enum.EasingStyle.Sine, Enum.EasingDirection.InOut, -1, true), { BackgroundColor3 = UI.col.card2 }):Play()
        end)
    end
end
function UI.clearSkeleton(parent)
    for _, c in ipairs(parent:GetChildren()) do if c.Name == OBF("\173\197\191\198") then c:Destroy() end end
end


function UI.empty(parent, icon, title, sub, order)
    local f = mk(OBF("\160\204\187\199\191"), { Size = UDim2.new(1, -6, 0, 120), BackgroundTransparency = 1, LayoutOrder = order or 1 }, parent)
    mk(OBF("\174\191\210\206\166\187\188\191\198"), { Size = UDim2.new(1, 0, 0, 44), Position = UDim2.fromOffset(0, 10), BackgroundTransparency = 1, Text = icon, TextSize = 32, Font = Enum.Font.GothamBold }, f)
    mk(OBF("\174\191\210\206\166\187\188\191\198"), {
        Size = UDim2.new(1, 0, 0, 18), Position = UDim2.fromOffset(0, 56), BackgroundTransparency = 1, Text = title, TextSize = 13,
        Font = Enum.Font.GothamBold, TextColor3 = UI.col.text,
    }, f)
    mk(OBF("\174\191\210\206\166\187\188\191\198"), {
        Size = UDim2.new(1, -30, 0, 28), Position = UDim2.new(0, 15, 0, 76), BackgroundTransparency = 1, Text = sub or "", TextSize = 10,
        Font = Enum.Font.Gotham, TextColor3 = UI.col.sub, TextWrapped = true, TextYAlignment = Enum.TextYAlignment.Top,
    }, f)
    return f
end





function UI.closePopup()
    if UI.popup then pcall(function() UI.popup:Destroy() end); UI.popup = nil end
    if UI.catcher then pcall(function() UI.catcher:Destroy() end); UI.catcher = nil end
end



function UI.loadPack(ctx, cb)
    if not ctx.pack and ctx.bundleId then ctx.pack = packByKey(OBF("\205") .. tostring(ctx.bundleId)) end
    if ctx.pack then cb(ctx.pack); return end
    if not ctx.bundleId then cb(nil, OBF("\202\187\189\197\122\195\200\190\195\205\202\201\200\29\7\208\191\198")); return end
    task.spawn(function()
        local p, err = Store.resolve(ctx.bundleId, ctx.name)
        if not p then cb(nil, err); return end
        ctx.pack = p; cb(p)
    end)
end

function UI.ensurePack(ctx, cb)
    if not ctx.pack and ctx.bundleId then ctx.pack = packByKey(OBF("\205") .. tostring(ctx.bundleId)) end
    if ctx.pack then
        
        if ctx.bundleId and not packByKey(ctx.pack.key) then table.insert(S.savedPacks, 1, ctx.pack); save() end
        cb(ctx.pack); return
    end
    if not ctx.bundleId then return end
    task.spawn(function()
        notify(OBF("\170\187\189\197"), OBF("\204\191\205\201\198\208\191\200\190\201\122") .. tostring(ctx.name) .. OBF("\136\136\136"))
        local p, err = Store.resolve(ctx.bundleId, ctx.name)
        if not p then notify(OBF("\159\204\204\201"), tostring(err)); sound(OBF("\191\204\204\201\204")); return end
        for i, sp in ipairs(S.savedPacks) do if sp.key == p.key then table.remove(S.savedPacks, i); break end end
        table.insert(S.savedPacks, 1, p); save()
        ctx.pack = p
        cb(p)
    end)
end

local function groupHas(p, g)
    for _, f in ipairs(GROUPS[g]) do if (p[f] or 0) ~= 0 then return true end end
    return false
end


function UI.packMenu(anchor, ctx)
    UI.closePopup()
    local catcher = mk(OBF("\174\191\210\206\156\207\206\206\201\200"), { Size = UDim2.fromScale(1, 1), BackgroundTransparency = 1, Text = "", AutoButtonColor = false, ZIndex = 100 }, Gui)
    catcher.Activated:Connect(UI.closePopup)
    local pop = mk(OBF("\160\204\187\199\191"), {
        Position = UDim2.fromOffset(-3000, -3000), Size = UDim2.fromOffset(212, 0), AutomaticSize = Enum.AutomaticSize.Y,
        BackgroundColor3 = UI.col.panel, BorderSizePixel = 0, ZIndex = 101,
    }, Gui)
    corner(pop, 12)
    mk(OBF("\175\163\173\206\204\201\197\191"), { Color = UI.col.accent, Thickness = 1.2, Transparency = 0.25, ApplyStrokeMode = Enum.ApplyStrokeMode.Border }, pop)
    mk(OBF("\175\163\173\189\187\198\191"), { Scale = UI.baseScale or 1 }, pop)
    mk(OBF("\175\163\170\187\190\190\195\200\193"), { PaddingTop = UDim.new(0, 9), PaddingBottom = UDim.new(0, 9), PaddingLeft = UDim.new(0, 9), PaddingRight = UDim.new(0, 9) }, pop)
    mk(OBF("\175\163\166\195\205\206\166\187\211\201\207\206"), { Padding = UDim.new(0, 5), SortOrder = Enum.SortOrder.LayoutOrder }, pop)
    UI.popup, UI.catcher = pop, catcher

    local order = 0
    local function nxt() order += 1; return order end
    local function done() UI.closePopup(); if UI.refreshPacks then UI.refreshPacks() end end

    local function pbtn(parent, text, size, active, onClick, color)
        local base = active and UI.col.primary or UI.col.card
        local b = mk(OBF("\174\191\210\206\156\207\206\206\201\200"), {
            Size = size, LayoutOrder = nxt(), AutoButtonColor = false, BorderSizePixel = 0, Text = text, Font = Enum.Font.GothamBold,
            TextSize = 11, BackgroundColor3 = base, TextColor3 = color or UI.col.text,
        }, parent)
        corner(b, 8)
        mk(OBF("\175\163\173\206\204\201\197\191"), { Color = active and UI.col.accent or UI.col.stroke, Thickness = 1, Transparency = active and 0.3 or 0.55, ApplyStrokeMode = Enum.ApplyStrokeMode.Border }, b)
        b.MouseEnter:Connect(function() tw(b, { BackgroundColor3 = base:Lerp(WHITE, 0.14) }, 0.1) end)
        b.MouseLeave:Connect(function() tw(b, { BackgroundColor3 = base }, 0.12) end)
        b.Activated:Connect(function() sound(OBF("\189\198\195\189\197")); onClick() end)
        return b
    end

    
    mk(OBF("\174\191\210\206\166\187\188\191\198"), {
        Size = UDim2.new(1, 0, 0, 18), LayoutOrder = nxt(), BackgroundTransparency = 1, Text = tostring(ctx.name), Font = Enum.Font.GothamBold,
        TextSize = 12, TextColor3 = UI.col.accent, TextXAlignment = Enum.TextXAlignment.Left, TextTruncate = Enum.TextTruncate.AtEnd,
    }, pop)

    
    do
        local r = mk(OBF("\160\204\187\199\191"), { Size = UDim2.new(1, 0, 0, 28), BackgroundTransparency = 1, LayoutOrder = nxt() }, pop)
        mk(OBF("\175\163\166\195\205\206\166\187\211\201\207\206"), { FillDirection = Enum.FillDirection.Horizontal, Padding = UDim.new(0, 6), SortOrder = Enum.SortOrder.LayoutOrder }, r)
        pbtn(r, OBF("\74\249\235\219\122\170\204\29\3\208\195\187"), UDim2.new(0.5, -3, 1, 0), false, function() UI.closePopup(); UI.previewPack(ctx) end)
        pbtn(r, OBF("\60\246\233\122\159\190\195\206\187\204"), UDim2.new(0.5, -3, 1, 0), false, function()
            UI.loadPack(ctx, function(p, err)
                if not p then notify(OBF("\159\204\204\201"), tostring(err)); sound(OBF("\191\204\204\201\204")); return end
                UI.closePopup(); UI.editPack(p)
            end)
        end)
    end

    pbtn(pop, OBF("\60\246\238\122\122\122\155\202\198\195\189\187\204\122\202\187\189\197\122\195\200\206\191\195\204\201"), UDim2.new(1, 0, 0, 30), true, function()
        UI.ensurePack(ctx, function(p) E.setPack(p.key); done() end)
    end)

    
    local copyMode = false
    local gridBtns = {}
    local modeLbl = mk(OBF("\174\191\210\206\166\187\188\191\198"), {
        Size = UDim2.new(1, 0, 0, 14), LayoutOrder = nxt(), BackgroundTransparency = 1, Text = OBF("\173\29\237\122\175\167\155\122\170\155\172\174\159\122\130\191\199\122\189\195\199\187\122\190\201\122\202\187\189\197\122\187\206\207\187\198\131"), Font = Enum.Font.GothamBold,
        TextSize = 9, TextColor3 = UI.col.sub, TextXAlignment = Enum.TextXAlignment.Left,
    }, pop)
    local mA, mB
    local function paintMode()
        for _, pair in ipairs({ { mA, not copyMode }, { mB, copyMode } }) do
            local b, on = pair[1], pair[2]
            b.BackgroundColor3 = on and UI.col.primary or UI.col.card
            b.TextColor3 = on and UI.col.text or UI.col.sub
        end
        modeLbl.Text = copyMode and OBF("\174\169\157\155\122\168\155\122\170\155\172\174\159\122\170\172\155\122\157\169\170\163\155\172\122\169\122\163\158\122\158\159\166\155") or OBF("\173\29\237\122\175\167\155\122\170\155\172\174\159\122\130\191\199\122\189\195\199\187\122\190\201\122\202\187\189\197\122\187\206\207\187\198\131")
        for g, b in pairs(gridBtns) do
            if copyMode then b.Text = OBF("\74\249\237\229\122") .. GROUP_LABEL[g] else
                local on = ctx.pack and S.parts[g] == ctx.pack.key
                b.Text = (on and OBF("\60\246\238\122") or (GROUP_ICON[g] .. OBF("\122"))) .. GROUP_LABEL[g]
            end
        end
    end
    do
        local r = mk(OBF("\160\204\187\199\191"), { Size = UDim2.new(1, 0, 0, 24), BackgroundTransparency = 1, LayoutOrder = nxt() }, pop)
        mk(OBF("\175\163\166\195\205\206\166\187\211\201\207\206"), { FillDirection = Enum.FillDirection.Horizontal, Padding = UDim.new(0, 6), SortOrder = Enum.SortOrder.LayoutOrder }, r)
        mA = pbtn(r, OBF("\155\202\198\195\189\187\204"), UDim2.new(0.5, -3, 1, 0), false, function() copyMode = false; paintMode() end)
        mB = pbtn(r, OBF("\157\201\202\195\187\204\122\163\158"), UDim2.new(0.5, -3, 1, 0), false, function() copyMode = true; paintMode() end)
    end

    local grid = mk(OBF("\160\204\187\199\191"), { Size = UDim2.new(1, 0, 0, 0), AutomaticSize = Enum.AutomaticSize.Y, BackgroundTransparency = 1, LayoutOrder = nxt() }, pop)
    mk(OBF("\175\163\161\204\195\190\166\187\211\201\207\206"), { CellSize = UDim2.new(0.5, -3, 0, 28), CellPadding = UDim2.fromOffset(6, 6), SortOrder = Enum.SortOrder.LayoutOrder }, grid)
    for _, g in ipairs(GROUP_ORDER) do
        gridBtns[g] = pbtn(grid, GROUP_ICON[g] .. OBF("\122") .. GROUP_LABEL[g], UDim2.new(), false, function()
            if copyMode then
                
                UI.loadPack(ctx, function(p, err)
                    if not p then notify(OBF("\159\204\204\201"), tostring(err)); sound(OBF("\191\204\204\201\204")); return end
                    local ids, seen = {}, {}
                    for _, f in ipairs(GROUPS[g]) do
                        local v = p[f] or 0
                        if v ~= 0 and not seen[v] then seen[v] = true; ids[#ids + 1] = tostring(v) end
                    end
                    if #ids == 0 then notify(GROUP_LABEL[g], OBF("\191\205\205\191\122\202\187\189\197\122\200\29\253\201\122\206\191\199\122") .. GROUP_LABEL[g]:lower()); sound(OBF("\191\204\204\201\204")); return end
                    copyText(table.concat(ids, OBF("\100")))
                    notify(OBF("\74\249\237\229\122") .. GROUP_LABEL[g], #ids == 1 and (OBF("\163\158\122") .. ids[1] .. OBF("\122\189\201\202\195\187\190\201")) or (#ids .. OBF("\122\163\158\205\122\189\201\202\195\187\190\201\205")))
                    UI.closePopup()
                end)
                return
            end
            UI.ensurePack(ctx, function(p)
                if not groupHas(p, g) then notify(GROUP_LABEL[g], OBF("\191\205\205\191\122\202\187\189\197\122\200\29\253\201\122\206\191\199\122") .. GROUP_LABEL[g]:lower()); sound(OBF("\191\204\204\201\204")); return end
                E.setPart(g, p.key)
                notify(GROUP_LABEL[g] .. OBF("\122\206\204\201\189\187\190\201"), OBF("\60\224\234\122") .. p.name)
                done()
