        end)
    end
    pbtn(grid, OBF("\60\224\20\122\174\195\204\187\204\122\202\187\204\206\191\205"), UDim2.new(), false, function() E.clearParts(); done() end, UI.col.sub)
    paintMode()

    if ctx.bundleId and not packByKey(OBF("\205") .. tostring(ctx.bundleId)) then
        pbtn(pop, OBF("\74\249\236\24\122\122\122\173\187\198\208\187\204\122\191\199\122\173\187\198\208\201\205"), UDim2.new(1, 0, 0, 28), false, function()
            UI.ensurePack(ctx, function(p) notify(OBF("\74\249\236\24\122") .. p.name, OBF("\205\187\198\208\201\122\191\199\122\173\187\198\208\201\205")); sound(OBF("\205\207\189\189\191\205\205")); done() end)
        end)
    end
    pbtn(pop, OBF("\74\249\237\229\122\122\122\157\201\202\195\187\204\122\206\201\190\201\205\122\201\205\122\163\158\205"), UDim2.new(1, 0, 0, 28), false, function()
        UI.loadPack(ctx, function(p, err)
            if not p then notify(OBF("\159\204\204\201"), tostring(err)); sound(OBF("\191\204\204\201\204")); return end
            copyText(packText(p)); notify(OBF("\74\249\237\229\122") .. p.name, OBF("\163\158\205\122\190\201\122\202\187\189\197\122\189\201\202\195\187\190\201\205")); UI.closePopup()
        end)
    end)

    
    task.defer(function()
        if not pop.Parent or not anchor.Parent then return end
        local cam = workspace.CurrentCamera
        local vp = cam and cam.ViewportSize or Vector2.new(1280, 720)
        local ap, as = anchor.AbsolutePosition, anchor.AbsoluteSize
        local w, h = pop.AbsoluteSize.X, pop.AbsoluteSize.Y
        local x = math.clamp(ap.X + as.X - w, 8, math.max(8, vp.X - w - 8))
        local y = ap.Y + as.Y + 5
        if y + h > vp.Y - 8 then y = math.max(8, ap.Y - h - 5) end
        pop.Position = UDim2.fromOffset(x, y)
    end)
end



