function PV.buildDummy()
    PV.clear()
    local char = LP.Character
    if not char then return false, OBF("\205\191\199\122\202\191\204\205\201\200\187\193\191\199\122\202\204\187\122\189\198\201\200\187\204") end
    pcall(function() char.Archivable = true end)
    local okc, clone = pcall(function() return char:Clone() end)
    if not okc or not clone then return false, OBF("\200\29\253\201\122\190\191\207\122\202\204\187\122\189\198\201\200\187\204\122\201\122\202\191\204\205\201\200\187\193\191\199") end
    local kill = {}
    for _, d in ipairs(clone:GetDescendants()) do
        if d:IsA(OBF("\166\207\187\173\201\207\204\189\191\157\201\200\206\187\195\200\191\204")) or d:IsA(OBF("\173\201\207\200\190")) or d:IsA(OBF("\160\201\204\189\191\160\195\191\198\190")) or d:IsA(OBF("\156\195\198\198\188\201\187\204\190\161\207\195")) or d:IsA(OBF("\162\195\193\194\198\195\193\194\206")) then
            kill[#kill + 1] = d
        end
    end
    for _, d in ipairs(kill) do pcall(function() d:Destroy() end) end
    local hum = clone:FindFirstChildOfClass(OBF("\162\207\199\187\200\201\195\190"))
    local root = clone:FindFirstChild(OBF("\162\207\199\187\200\201\195\190\172\201\201\206\170\187\204\206"))
    if not hum or not root then pcall(function() clone:Destroy() end); return false, OBF("\202\191\204\205\201\200\187\193\191\199\122\205\191\199\122\162\207\199\187\200\201\195\190") end
    hum.DisplayDistanceType = Enum.HumanoidDisplayDistanceType.None
    hum.HealthDisplayType = Enum.HumanoidHealthDisplayType.AlwaysOff

    local wm = Instance.new(OBF("\177\201\204\198\190\167\201\190\191\198")); wm.Parent = Stage
    clone.Parent = wm
    clone:PivotTo(CFrame.new(0, 0, 0))
    root.Anchored = true
    local animator = hum:FindFirstChildOfClass(OBF("\155\200\195\199\187\206\201\204")) or Instance.new(OBF("\155\200\195\199\187\206\201\204"), hum)

    
    local feet = hum.HipHeight + root.Size.Y / 2
    local plat = Instance.new(OBF("\170\187\204\206"))
    plat.Shape = Enum.PartType.Cylinder; plat.Size = Vector3.new(0.2, 5.2, 5.2); plat.Anchored = true; plat.CanCollide = false
    plat.Material = Enum.Material.Neon; plat.Color = UI.col.accent; plat.Transparency = 0.5
    plat.CFrame = CFrame.new(0, -feet - 0.1, 0) * CFrame.Angles(0, 0, math.rad(90))
    plat.Parent = wm

    PV.wm, PV.model, PV.hum, PV.animator = wm, clone, hum, animator
    PV.center = Vector3.new(0, -feet + 2.6, 0)
    PV.r6 = (hum.RigType == Enum.HumanoidRigType.R6)
    aim()
    return true
end





PV.timeout = 5
function PV.play(id, loop, speed, onStep)
    PV.token += 1
    local my = PV.token
    if PV.track then pcall(function() PV.track:Stop(0.1) end); PV.track = nil end
    local animator, hum = PV.animator, PV.hum
    if not animator then return false, OBF("\205\191\199\122\188\201\200\191\189\201") end
    onStep = onStep or function() end

    local tr
    local notes = {}
    local function dead() return my ~= PV.token end
    local function drop(t) if t then pcall(function() t:Destroy() end) end end
    local function try(aid, tag)
        local t = loadTrack(animator, aid, PV.timeout)
        notes[#notes + 1] = tag .. (t and OBF("\148\201\197") or OBF("\148\210"))
        return t
    end

    
    local real = PV.map[id]
    if real and real ~= id then tr = try(real, OBF("\189\187\189\194\191")) end
    if dead() then drop(tr); return false, OBF("\189\187\200\189\191\198\187\190\201") end

    
    if not tr then onStep(OBF("\189\187\204\204\191\193\187\200\190\201\136\136\136")); tr = try(id, OBF("\190\195\204\191\206\201")) end
    if dead() then drop(tr); return false, OBF("\189\187\200\189\191\198\187\190\201") end

    
    if not tr then
        onStep(OBF("\204\191\205\201\198\208\191\200\190\201\122\191\199\201\206\191\136\136\136\122\130\139\137\141\131"))
        local inner = innerAnims(id)
        notes[#notes + 1] = OBF("\201\188\196\205\148") .. #inner
        if dead() then return false, OBF("\189\187\200\189\191\198\187\190\201") end
        for _, a in ipairs(inner) do
            if a.id ~= id then
                tr = try(a.id, OBF("\195\200\200\191\204"))
                if dead() then drop(tr); return false, OBF("\189\187\200\189\191\198\187\190\201") end
                if tr then PV.map[id] = a.id; break end
            end
        end
    end

    
    if not tr then
        onStep(OBF("\204\191\205\201\198\208\191\200\190\201\122\191\199\201\206\191\136\136\136\122\130\140\137\141\131"))
        local _, rh = E.parts()
        if rh and rh.Health > 0 and not E.track then
            local ok, succ, rt = pcall(function() return rh:PlayEmoteAndGetAnimTrackById(id) end)
            if ok and succ and rt then
                local n = 0
                pcall(function() n = parseId(rt.Animation.AnimationId) end)
                pcall(function() rt:Stop(0) end)
                notes[#notes + 1] = OBF("\204\191\187\198\148") .. n
                if n ~= 0 and n ~= id then
                    tr = try(n, OBF("\204\191\187\198\195\190"))
                    if tr then PV.map[id] = n end
                end
            else
                notes[#notes + 1] = OBF("\204\191\187\198\148\210")
            end
        else
            notes[#notes + 1] = OBF("\204\191\187\198\148\202\207\198\201\207")
        end
        if dead() then drop(tr); return false, OBF("\189\187\200\189\191\198\187\190\201") end
    end

    
    if not tr then
        onStep(OBF("\204\191\205\201\198\208\191\200\190\201\122\191\199\201\206\191\136\136\136\122\130\141\137\141\131"))
        local KSP = game:GetService(OBF("\165\191\211\192\204\187\199\191\173\191\203\207\191\200\189\191\170\204\201\208\195\190\191\204"))
        local src = (PV.map[id] and PV.map[id] ~= id) and PV.map[id] or id
        local ok, ks = pcall(function() return KSP:GetKeyframeSequenceAsync(OBF("\204\188\210\187\205\205\191\206\195\190\148\137\137") .. tostring(src)) end)
        if ok and ks then
            local ok2, hash = pcall(function() return KSP:RegisterKeyframeSequence(ks) end)
            if ok2 and hash then tr = try(hash, OBF("\197\205")) else notes[#notes + 1] = OBF("\197\205\148\204\191\193") end
        else
            notes[#notes + 1] = OBF("\197\205\148\193\191\206")
        end
        if dead() then drop(tr); return false, OBF("\189\187\200\189\191\198\187\190\201") end
    end

    
    if not tr and hum then
        local ok, succ, t2 = pcall(function() return hum:PlayEmoteAndGetAnimTrackById(id) end)
        notes[#notes + 1] = OBF("\191\199\201\206\191\148") .. ((ok and succ and t2) and OBF("\201\197") or OBF("\210"))
        if ok and succ and t2 then tr = t2 end
        if dead() then drop(tr); return false, OBF("\189\187\200\189\191\198\187\190\201") end
    end

    if not tr then
        local why = table.concat(notes, OBF("\122"))
        pcall(function() warn(OBF("\181\161\174\155\122\159\199\201\206\191\162\207\188\183\122\202\204\29\3\208\195\187\122\192\187\198\194\201\207\122\195\190\151") .. id .. OBF("\122\60\224\236\122") .. why) end)
        return false, OBF("\200\29\253\201\122\189\187\204\204\191\193\201\207\122\200\187\122\202\204\29\3\208\195\187\122\181") .. why .. OBF("\183\122\60\218\238\122\207\205\191\122\124\206\201\189\187\204\122\200\201\122\199\191\207\122\202\191\204\205\201\200\187\193\191\199\124")
    end

    pcall(function() tr.Priority = Enum.AnimationPriority.Action4 end)
    pcall(function() tr.Looped = loop ~= false end)
    PV.track = tr
    if not tr.IsPlaying then pcall(function() tr:Play(0.1) end) end
    pcall(function() tr:AdjustSpeed(speed or 1) end)
    return true
end


