function UI.previewEmote(id, name)
    id = tonumber(id); if not id then return end
    PV.ctx = { kind = OBF("\191\199\201\206\191"), id = id }
    local ctx = PV.ctx
    local ok = openCommon(name or Names.cache[id] or (OBF("\159\199\201\206\191\122") .. id), OBF("\163\158\122") .. id)
    if not name and not Names.cache[id] then Names.get(id, function(n) if PV.ctx == ctx then PName.Text = n end end) end

    local loop, speeds, si = S.loop, { 0.5, 1, 1.5, 2 }, 2
    local function start()
        if not ok then return end
        pstat(OBF("\189\187\204\204\191\193\187\200\190\201\136\136\136"))
        task.spawn(function()
            local good, err = PV.play(id, loop, speeds[si], function(t) if PV.ctx == ctx then pstat(t) end end)
