function UI.previewPack(ctx)
    PV.ctx = { kind = OBF("\202\187\189\197"), src = ctx }
    local me = PV.ctx
    local ok = openCommon(tostring(ctx.name), OBF("\189\187\204\204\191\193\187\200\190\201\122\202\187\189\197\136\136\136"))
    pstat(OBF("\204\191\205\201\198\208\191\200\190\201\122\202\187\189\197\136\136\136"))
    UI.loadPack(ctx, function(p, err)
        if PV.ctx ~= me or not Prev.Visible then return end
        if not p then pstat(tostring(err or OBF("\202\187\189\197\122\195\200\190\195\205\202\201\200\29\7\208\191\198")), true); return end
        PSub.Text = (OBF("\209\187\198\197\122\127\205\122\28\17\122\204\207\200\122\127\205\122\28\17\122\195\190\198\191\122\127\205")):format(p.walk or 0, p.run or 0, p.idle1 or 0)
        pstat(OBF("\191\205\189\201\198\194\191\122\187\122\202\187\204\206\191\122\202\204\187\122\208\191\204"))

        local sel, cyc, btns = nil, {}, {}
        local function paint()
            for g, b in pairs(btns) do
                local on = (g == sel)
                b.BackgroundColor3 = on and UI.col.primary or UI.col.card
                b.TextColor3 = (groupHas(p, g) and UI.col.text or UI.col.sub)
            end
        end
        local bUse
        local function fieldOf(g)
            local fs = GROUPS[g]
            local i = cyc[g] or 1
            local f = fs[i]
            if (p[f] or 0) == 0 then f = fs[1] end
            return f
        end
        local function show(g)
            if not groupHas(p, g) then return end
            if sel == g and #GROUPS[g] > 1 then cyc[g] = ((cyc[g] or 1) % #GROUPS[g]) + 1 end 
            sel = g; paint()
            if bUse then bUse.Text = OBF("\175\205\187\204\122\205\29\13\122") .. GROUP_LABEL[g] end
            local f = fieldOf(g)
            if not ok then return end
            pstat(OBF("\189\187\204\204\191\193\187\200\190\201\122") .. GROUP_LABEL[g] .. OBF("\136\136\136"))
            task.spawn(function()
                local good, e2 = PV.play(p[f], true, 1)
                if PV.ctx ~= me then return end
                if good then pstat(OBF("\60\240\16\122") .. GROUP_LABEL[g] .. (#GROUPS[g] > 1 and (OBF("\122\130") .. f .. OBF("\131")) or "")) elseif e2 ~= OBF("\189\187\200\189\191\198\187\190\201") then pstat(e2, true) end
            end)
        end

        label(Ctl, OBF("\170\155\172\174\159\173"), 9, OBF("\205\207\188"), Enum.Font.GothamBold, { Size = UDim2.new(1, 0, 0, 12), LayoutOrder = nextOrder(Ctl) })
        local grid = mk(OBF("\160\204\187\199\191"), { Size = UDim2.new(1, 0, 0, 0), AutomaticSize = Enum.AutomaticSize.Y, BackgroundTransparency = 1, LayoutOrder = nextOrder(Ctl) }, Ctl)
        mk(OBF("\175\163\161\204\195\190\166\187\211\201\207\206"), { CellSize = UDim2.new(1 / 3, -4, 0, 26), CellPadding = UDim2.fromOffset(5, 5), SortOrder = Enum.SortOrder.LayoutOrder }, grid)
        for i, g in ipairs(GROUP_ORDER) do
            local b = mk(OBF("\174\191\210\206\156\207\206\206\201\200"), {
                BorderSizePixel = 0, AutoButtonColor = false, Text = GROUP_ICON[g] .. OBF("\122") .. GROUP_LABEL[g], Font = Enum.Font.GothamBold,
                TextSize = 10, LayoutOrder = i, BackgroundColor3 = UI.col.card, TextColor3 = UI.col.text,
            }, grid)
            corner(b, 8)
            b.Activated:Connect(function() sound(OBF("\189\198\195\189\197")); show(g) end)
            btns[g] = b
        end
        paint()

        wide(Ctl, OBF("\60\246\238\122\122\155\202\198\195\189\187\204\122\202\187\189\197\122\195\200\206\191\195\204\201"), function()
            UI.ensurePack(ctx, function(pk) E.setPack(pk.key); if UI.refreshPacks then UI.refreshPacks() end end)
        end, OBF("\202\204\195\199\187\204\211"))
        bUse = wide(Ctl, OBF("\175\205\187\204\122\205\29\13\122\60\218\0"), function()
            if not sel then pstat(OBF("\191\205\189\201\198\194\191\122\207\199\187\122\202\187\204\206\191\122\187\200\206\191\205"), true); return end
            UI.ensurePack(ctx, function(pk)
                E.setPart(sel, pk.key); notify(GROUP_LABEL[sel] .. OBF("\122\206\204\201\189\187\190\201"), OBF("\60\224\234\122") .. pk.name)
                if UI.refreshPacks then UI.refreshPacks() end
            end)
        end)
        bUse.Text = OBF("\175\205\187\204\122\205\29\13\122\60\218\0")

        
        row2(Ctl, { OBF("\74\249\237\229\122\163\158\122\190\187\122\202\187\204\206\191"), function()
            if not sel then pstat(OBF("\191\205\189\201\198\194\191\122\207\199\187\122\202\187\204\206\191\122\187\200\206\191\205"), true); return end
            local ids, seen = {}, {}
            for _, f in ipairs(GROUPS[sel]) do
                local v = p[f] or 0
                if v ~= 0 and not seen[v] then seen[v] = true; ids[#ids + 1] = tostring(v) end
            end
            copyText(table.concat(ids, OBF("\100")))
            notify(OBF("\74\249\237\229\122") .. GROUP_LABEL[sel], #ids == 1 and (OBF("\163\158\122") .. ids[1] .. OBF("\122\189\201\202\195\187\190\201")) or (#ids .. OBF("\122\163\158\205\122\189\201\202\195\187\190\201\205")))
        end }, { OBF("\60\246\233\122\159\190\195\206\187\204"), function() UI.closePreview(); UI.editPack(p) end })

        
        for _, g in ipairs({ OBF("\195\190\198\191"), OBF("\209\187\198\197"), OBF("\204\207\200"), OBF("\196\207\199\202"), OBF("\192\187\198\198"), OBF("\189\198\195\199\188"), OBF("\205\209\195\199") }) do
            if groupHas(p, g) then show(g); break end
        end
    end)
end




