local function emotePickRows(l, title, get, set)
    local box = mk(OBF("\160\204\187\199\191"), { Size = UDim2.new(1, -8, 0, 40), BorderSizePixel = 0, LayoutOrder = nextOrder(l) }, l)
    th(box, OBF("\156\187\189\197\193\204\201\207\200\190\157\201\198\201\204\141"), OBF("\189\187\204\190")); corner(box, 9)
    local img = mk(OBF("\163\199\187\193\191\166\187\188\191\198"), {
        Position = UDim2.fromOffset(6, 4), Size = UDim2.fromOffset(32, 32), BackgroundColor3 = UI.col.panel, BorderSizePixel = 0,
        ScaleType = Enum.ScaleType.Fit,
    }, box)
    corner(img, 8)
    local nm = label(box, "", 11, OBF("\206\191\210\206"), nil, { Position = UDim2.fromOffset(46, 2), Size = UDim2.new(1, -52, 0, 36) })
    local function refresh()
        local id = get()
        if id == 0 then img.Image = ""; nm.Text = title .. OBF("\148\122\74\249\232\12\122\187\198\191\187\206\29\13\204\195\201"); return end
        img.Image = (OBF("\204\188\210\206\194\207\199\188\148\137\137\206\211\202\191\151\155\205\205\191\206\128\195\190\151\127\190\128\209\151\139\143\138\128\194\151\139\143\138")):format(id)
        nm.Text = title .. OBF("\148\122") .. id
        Names.get(id, function(n) if get() == id and nm.Parent then nm.Text = title .. OBF("\148\122") .. n end end)
    end
    local row = mk(OBF("\160\204\187\199\191"), { Size = UDim2.new(1, -8, 0, 28), BackgroundTransparency = 1, LayoutOrder = nextOrder(l) }, l)
    local tb = textbox(row, OBF("\163\158\122\201\207\122\198\195\200\197\122\190\201\122\191\199\201\206\191"), UDim2.new(1, -168, 1, 0))
    local function put(x, w, text, fn, key)
        local b = button(row, text, UDim2.new(0, w, 1, 0), fn, key)
        b.Position = UDim2.new(1, x, 0, 0)
        return b
    end
    put(-164, 38, OBF("\169\165"), function()
        local id = parseId(tb.Text)
        if id == 0 then notify(title, OBF("\163\158\122\195\200\208\29\251\198\195\190\201")); sound(OBF("\191\204\204\201\204")); return end
        set(id); tb.Text = ""; refresh()
    end, OBF("\202\204\195\199\187\204\211"))
    put(-122, 36, OBF("\74\249\237\230"), function()
        if S.lastEmote == 0 then notify(title, OBF("\174\201\203\207\191\122\207\199\122\191\199\201\206\191\122\187\200\206\191\205")); return end
        set(S.lastEmote); refresh()
    end)
    put(-82, 36, OBF("\74\249\232\12"), function() set(0); refresh() end)
    put(-42, 38, OBF("\60\240\16"), function()
        local id = get()
        if id == 0 then local pool = E.pool(); id = pool[math.random(math.max(#pool, 1))] end
        if id then task.spawn(E.play, id, true) end
    end)
    refresh()
    return refresh
end




