    pcall(function()
        VirtualUser:CaptureController()
        VirtualUser:ClickButton2(Vector2.new(0, 0))
    end)
end)

UI.conns[#UI.conns + 1] = RunService.Heartbeat:Connect(function(dt)
    AF.acc += dt
    if AF.acc < CFG.AfkCheck then return end
    AF.acc = 0
    local A = S.afk
    if not A.on or AF.busy then return end
    local _, hum = E.parts()
    if not hum or hum.Health <= 0 then return end
    local now = os.clock()
    if hum.MoveDirection.Magnitude > 0 then AF.last = now; return end 
    if hum.Sit or E.track ~= nil or now - AF.last < A.secs or now < AF.nextTry then return end
    local id = A.emote
    if id == 0 then
        local pool = E.pool()
        id = pool[math.random(math.max(#pool, 1))]
        if not id then return end
    end
    AF.busy = true
    local okp, res = pcall(E.play, id, true)
    AF.busy = false
    if okp and res then AF.track = E.track; AF.nextTry = now + 1 else AF.nextTry = now + 30 end 
end)








local RL = {
    c = nil, t = 0, fall = 0, landPos = 0, landVel = 0, clean = true, warned = false,
    sm = { p = 0, pitch = 0, roll = 0, hy = 0, hp = 0, br = 0 },
    pf = 0, acc = 0,                       
    bob = Vector3.zero, bobPh = 0,         
    gl = { t = 1.5, yaw = 0, pit = 0, hold = false }, 
    prints = {}, pdist = 0, side = 1, splash = nil,    
}

RL.perfR = setmetatable({ footIK = false, dust = false, camBob = false, prints = false, splash = false, camLean = false, shake = false },
    { __index = S.real })

function RL.restore(c)
    c = c or RL.c; if not c then return end
    for k, m in pairs({ waist = c.waist, neck = c.neck, rootJ = c.rootJ }) do
        if m and c.o[k] then pcall(function() m.C0 = c.o[k] end) end
    end
    for _, L in pairs(c.legs or {}) do
        if L.ik then pcall(function() L.ik.Weight = 0 end); L.w = 0 end
    end
    if c.hum and c.camBase then pcall(function() c.hum.CameraOffset = c.camBase + FP.off + SH.off end) end
    RL.bob = Vector3.zero
    if c.dust then pcall(function() c.dust.Enabled = false end) end
end

function RL.reset()
    local c = RL.c
    if c then
        RL.restore(c)
        if c.conn then pcall(function() c.conn:Disconnect() end) end
        for _, L in pairs(c.legs or {}) do
            if L.ik then pcall(function() L.ik:Destroy() end) end
        end
        if c.targets then pcall(function() c.targets:Destroy() end) end
        if c.dustAtt then pcall(function() c.dustAtt:Destroy() end) end
    end
    RL.c = nil
    RL.fall, RL.landPos, RL.landVel, RL.clean = 0, 0, 0, true
    RL.pf, RL.acc, RL.bob, RL.bobPh = 0, 0, Vector3.zero, 0
    RL.gl = { t = 1.5, yaw = 0, pit = 0, hold = false }
    RL.pdist = 0
    if RL.splash then pcall(function() RL.splash.part:Destroy() end); RL.splash = nil end
    for _, p in ipairs(RL.prints) do pcall(function() p:Destroy() end) end
    RL.prints = {}
    for k in pairs(RL.sm) do RL.sm[k] = 0 end
end

function RL.setup(char)
    RL.reset()
    local hum = char:FindFirstChildOfClass(OBF("\162\207\199\187\200\201\195\190"))
    local root = char:FindFirstChild(OBF("\162\207\199\187\200\201\195\190\172\201\201\206\170\187\204\206"))
    if not hum or not root then return end
    local r6 = hum.RigType ~= Enum.HumanoidRigType.R15
    local function joint(part, name)
        local p = char:FindFirstChild(part); return p and p:FindFirstChild(name)
    end
    local c = {
        char = char, hum = hum, root = root, camBase = hum.CameraOffset, r6 = r6,
        waist = (not r6) and joint(OBF("\175\202\202\191\204\174\201\204\205\201"), OBF("\177\187\195\205\206")) or nil,
        neck = r6 and joint(OBF("\174\201\204\205\201"), OBF("\168\191\189\197")) or joint(OBF("\162\191\187\190"), OBF("\168\191\189\197")), 
        rootJ = (not r6) and joint(OBF("\166\201\209\191\204\174\201\204\205\201"), OBF("\172\201\201\206")) or nil,
        o = {}, legs = {},
    }
    for k, m in pairs({ waist = c.waist, neck = c.neck, rootJ = c.rootJ }) do if m then c.o[k] = m.C0 end end
    local lt = char:FindFirstChild(OBF("\166\201\209\191\204\174\201\204\205\201"))
    for _, side in ipairs({ OBF("\166\191\192\206"), OBF("\172\195\193\194\206") }) do
        local up, lo, ft = char:FindFirstChild(side .. OBF("\175\202\202\191\204\166\191\193")), char:FindFirstChild(side .. OBF("\166\201\209\191\204\166\191\193")), char:FindFirstChild(side .. OBF("\160\201\201\206"))
        local hipJ = lt and lt:FindFirstChild(side .. OBF("\162\195\202"))
        local kneeJ = up and up:FindFirstChild(side .. OBF("\165\200\191\191"))
        local ankJ = lo and lo:FindFirstChild(side .. OBF("\155\200\197\198\191"))
        if up and lo and ft and hipJ and kneeJ and ankJ and hipJ:IsA(OBF("\167\201\206\201\204\144\158")) and hipJ.Part0 then
            c.legs[side] = {
                up = up, lo = lo, ft = ft, hip = hipJ, w = 0,
                
                len = (hipJ.C1.Position - kneeJ.C0.Position).Magnitude + (kneeJ.C1.Position - ankJ.C0.Position).Magnitude,
                ank = ankJ.C1.Position, 
            }
        end
    end
    c.params = RaycastParams.new()
    c.params.FilterType = Enum.RaycastFilterType.Exclude
    c.params.RespectCanCollide = true 
    c.params.FilterDescendantsInstances = { char }
    
    c.conn = hum.StateChanged:Connect(function(_, new)
        if new == Enum.HumanoidStateType.Landed then
            if S.real.land then RL.landPos = -math.clamp(RL.fall * 0.012, 0, 0.85); RL.landVel = 0 end
            if S.real.shake and not E.perf then CAMFX.kick(RL.fall) end
            RL.fall = 0
        end
    end)
    RL.c = c
    RL.clean = false
end


function RL.ensureIK(c)
    if c.ik ~= nil then return c.ik end
    local ok = pcall(function()
        local folder = Instance.new(OBF("\160\201\198\190\191\204")); folder.Name = OBF("\159\162\185\163\165")
        folder.Parent = workspace
        c.targets = folder
        for _, L in pairs(c.legs) do
            local tp = Instance.new(OBF("\170\187\204\206"))
            tp.Anchored = true; tp.CanCollide = false; tp.CanQuery = false; tp.CanTouch = false; tp.Transparency = 1
            tp.Size = Vector3.new(0.2, 0.2, 0.2); tp.Parent = folder
            local ik = Instance.new(OBF("\163\165\157\201\200\206\204\201\198"))
            
            if not pcall(function() ik.Type = Enum.IKControlType.Transform end) then ik.Type = Enum.IKControlType.Position end
            ik.ChainRoot = L.up; ik.EndEffector = L.ft; ik.Target = tp
            ik.Weight = 0; ik.SmoothTime = 0.05; ik.Enabled = false
            ik.Parent = c.hum
            L.ik, L.tp = ik, tp
        end
    end)
    c.ik = ok
    if not ok then notify(OBF("\170\29\3\205\122\200\201\122\189\194\29\253\201"), OBF("\163\165\157\201\200\206\204\201\198\122\195\200\190\195\205\202\201\200\29\7\208\191\198\122\187\203\207\195\122\60\218\238\122\201\122\204\191\205\206\201\122\190\201\122\204\191\187\198\195\205\199\201\122\192\207\200\189\195\201\200\187")) end
    return ok
end


