local function hitsCharacter(inst)
    local m = inst and inst:FindFirstAncestorOfClass(OBF("\167\201\190\191\198"))
    return m ~= nil and m:FindFirstChildOfClass(OBF("\162\207\199\187\200\201\195\190")) ~= nil
end

function RL.update(dt)
    local c = RL.c
    if not c or not c.char.Parent or c.hum.Health <= 0 then return end
    local R = E.perf and RL.perfR or S.real
    local anyOn = R.footIK or R.lean or R.head or R.breathe or R.land or R.brake or R.dust or R.camBob
        or R.headLead or R.glance or R.prints or R.splash or R.shake
    if anyOn then RL.clean = false elseif RL.clean then return end
    dt = math.min(dt, 0.05); RL.t += dt

    local hum, root, sm = c.hum, c.root, RL.sm
    local state = hum:GetState()
    local vel = root.AssemblyLinearVelocity
    local lv = root.CFrame:VectorToObjectSpace(vel)
    local speed = Vector3.new(vel.X, 0, vel.Z).Magnitude
    local grounded = hum.FloorMaterial ~= Enum.Material.Air
    local special = hum.Sit or hum.PlatformStand or state == Enum.HumanoidStateType.Climbing or state == Enum.HumanoidStateType.Swimming
        or state == Enum.HumanoidStateType.Seated or state == Enum.HumanoidStateType.Dead or state == Enum.HumanoidStateType.Ragdoll
    local ok = (not special) and (E.track == nil) 
    local a = 1 - math.exp(-dt * 10)

    if state == Enum.HumanoidStateType.Freefall then RL.fall = math.max(RL.fall, -vel.Y) end

    
    do
        local fwd = -lv.Z
        local rawAcc = math.clamp((fwd - RL.pf) / math.max(dt, 0.001), -300, 300)
        RL.pf = fwd
        RL.acc += (rawAcc - RL.acc) * (1 - math.exp(-dt * 12))
    end

    
    
    local still = speed < 3 and hum.MoveDirection.Magnitude < 0.1
        and (state == Enum.HumanoidStateType.Running or state == Enum.HumanoidStateType.RunningNoPhysics or state == Enum.HumanoidStateType.Landed)
    local wantIK = R.footIK and ok and grounded and still and not c.r6
    if wantIK and c.ik == nil then RL.ensureIK(c) end
    local planeY
    if c.ik then
        local r = workspace:Raycast(root.Position, Vector3.new(0, -(hum.HipHeight + root.Size.Y / 2 + 3), 0), c.params)
        planeY = r and r.Position.Y
    end

    
    local nlegs, hits, nh, maxAbs, valid = 0, {}, 0, 0, true
    for _ in pairs(c.legs) do nlegs += 1 end
    if wantIK and c.ik and planeY and nlegs > 0 then
        for side, L in pairs(c.legs) do
            local fp = L.ft.Position
            local rr = workspace:Raycast(Vector3.new(fp.X, planeY + R.reach + 0.5, fp.Z), Vector3.new(0, -(R.reach * 2 + 1), 0), c.params)
            if rr and rr.Normal.Y >= 0.7 and not hitsCharacter(rr.Instance) then
                local d = rr.Position.Y - planeY
                if math.abs(d) <= R.reach then
                    hits[side] = { pos = rr.Position, n = rr.Normal, d = d }; nh += 1; maxAbs = math.max(maxAbs, math.abs(d))
                else valid = false end
            else valid = false end
        end
    end
    
    if not valid or nh < nlegs or maxAbs < 0.05 then hits = {}; nh = 0 end

    
    local dMin = 0
    for _, h in pairs(hits) do if h.d < dMin then dMin = h.d end end
    local pelvisT = (R.pelvis and ok) and dMin * 0.5 or 0
    local hipShift = pelvisT - sm.p 

    
    local plan, np = {}, 0
    for side, h in pairs(hits) do
        local L = c.legs[side]
        local n = h.n
        local right = root.CFrame.RightVector
        right = right - n * right:Dot(n)
        if right.Magnitude > 0.01 then
            right = right.Unit
            local rot = CFrame.fromMatrix(Vector3.zero, right, n)
            local center = h.pos + n * (L.ft.Size.Y / 2)
            local ankleT = center + rot:VectorToWorldSpace(L.ank)
            local hipPos = (L.hip.Part0.CFrame * L.hip.C0).Position + Vector3.new(0, hipShift, 0)
            if (ankleT - hipPos).Magnitude <= L.len * 0.96 then 
                plan[side] = CFrame.new(center) * rot; np += 1
            end
        end
    end
    local all = (nlegs > 0 and np == nlegs)  
    if not all then plan = {}; pelvisT = 0 end

    for side, L in pairs(c.legs) do
        if L.ik then
            local cf = plan[side]
            if cf then L.tp.CFrame = cf end
            L.w += ((cf and 1 or 0) - L.w) * a
            L.ik.Weight = L.w
            L.ik.Enabled = L.w > 0.01
        end
    end
    sm.p += (pelvisT - sm.p) * a

    
    if R.land then
        RL.landVel += (-120 * RL.landPos - 14 * RL.landVel) * dt
        RL.landPos += RL.landVel * dt
    else
        RL.landPos, RL.landVel = 0, 0
    end

    
    local pitchT, rollT = 0, 0
    if R.lean and ok then
        pitchT = -math.clamp(-lv.Z * 0.011, -0.15, 0.22) * R.leanAmt 
        rollT = math.clamp(root.AssemblyAngularVelocity.Y * 0.05 - lv.X * 0.012, -0.3, 0.3) * R.leanAmt
    end
    
    if R.brake and ok and grounded then
        pitchT += math.clamp(-RL.acc * 0.0045, 0, 0.3) * R.leanAmt
    end
    sm.pitch += (pitchT - sm.pitch) * a; sm.roll += (rollT - sm.roll) * a

    
    
    
    local hyT, hpT = 0, 0
    local cam = workspace.CurrentCamera
    local inFP = FP.first
    local md = hum.MoveDirection
    local moving = md.Magnitude > 0.1
    if (R.head or R.headLead or R.glance) and ok then
        
        if R.head and cam and not inFP then
            local l = root.CFrame:VectorToObjectSpace(cam.CFrame.LookVector)
            hyT = math.clamp(math.atan2(-l.X, -l.Z), -1.2, 1.2) * 0.85
            hpT = math.clamp(math.asin(math.clamp(l.Y, -1, 1)), -0.6, 0.6) * 0.8
        end
        if R.headLead and moving and not inFP and hum.AutoRotate and UserInputService.MouseBehavior ~= Enum.MouseBehavior.LockCenter then
            local l = root.CFrame:VectorToObjectSpace(md)
            local ang = math.atan2(-l.X, -l.Z) 
            if math.abs(ang) < 2.3 then hyT = math.clamp(ang, -1.2, 1.2) * 0.9 end 
        end
        local gl = RL.gl
        if R.glance and not moving and speed < 0.5 and grounded then
            gl.t -= dt
            if gl.t <= 0 then
                if gl.hold then
                    gl.yaw, gl.pit, gl.hold = 0, 0, false
                    gl.t = 2.5 + math.random() * 4.5
                else
                    gl.yaw = (math.random() * 2 - 1) * 0.75
                    gl.pit = (math.random() * 2 - 1) * 0.25
                    gl.hold = true
                    gl.t = 0.8 + math.random() * 1.4
                end
            end
            local k = inFP and 0.35 or 1 
            local free = 1 - math.clamp(math.abs(hyT) / 0.4, 0, 1) 
            hyT += gl.yaw * k * free; hpT += gl.pit * k * free
        else
            gl.yaw, gl.pit, gl.hold, gl.t = 0, 0, false, 1.5
        end
    end
    local ah = 1 - math.exp(-dt * 8)
    sm.hy += (hyT - sm.hy) * ah; sm.hp += (hpT - sm.hp) * ah

    
    local brT = (R.breathe and ok and grounded and speed < 0.5) and math.sin(RL.t * 1.8) * 0.012 or 0
    sm.br += (brT - sm.br) * a

    
    if R.dust and ok and grounded and speed > 9 then
        local d = RL.ensureDust(c)
        if d then
            d.Rate = math.clamp((speed - 9) * 3, 0, 26)
            local mat = hum.FloorMaterial
            if c.dustMat ~= mat then c.dustMat = mat; d.Color = ColorSequence.new(DUST_COL[mat] or DUST_DEF) end
            d.Enabled = true
        end
    elseif c.dust then
        c.dust.Enabled = false
    end

    
    local bobT = Vector3.zero
    if R.camBob and ok and grounded and speed > 2 then
        RL.bobPh += dt * speed * 0.6
        local k = math.clamp(speed / 16, 0.3, 1.6) * R.camAmt
        bobT = Vector3.new(math.cos(RL.bobPh) * 0.05 * k, (math.abs(math.sin(RL.bobPh)) - 0.5) * 0.12 * k, 0)
    end
    RL.bob = RL.bob:Lerp(bobT, a)
    if RL.bob.Magnitude > 0.0005 or RL.bobOn then
        RL.bobOn = RL.bob.Magnitude > 0.0005
        pcall(function() hum.CameraOffset = c.camBase + FP.off + SH.off + RL.bob end)
    end

    
    local fh
    if (R.prints or R.splash) and not special and speed > 2.5 then fh = RL.floorRay(c) end
    if R.splash and fh and fh.Material == Enum.Material.Water then
        local sp2 = RL.ensureSplash()
        if sp2 then
            sp2.part.CFrame = CFrame.new(fh.Position + Vector3.new(0, 0.1, 0))
            sp2.pe.Rate = math.clamp(speed * 2.2, 6, 34)
            sp2.pe.Enabled = true
        end
    elseif RL.splash and RL.splash.pe.Enabled then
        RL.splash.pe.Enabled = false
    end
    if R.prints and ok and grounded and fh and PRINT_COL[fh.Material] then
        RL.pdist += speed * dt
        if RL.pdist >= 2.2 then RL.pdist = 0; RL.side = -RL.side; RL.stamp(c, fh) end
    end

    
    local o = c.o
    if c.rootJ and o.rootJ then c.rootJ.C0 = o.rootJ * CFrame.new(0, sm.p + RL.landPos, 0) end
    if c.waist and o.waist then c.waist.C0 = o.waist * CFrame.Angles(sm.pitch + sm.br + RL.landPos * 0.5, 0, sm.roll) end
    
    if c.neck and o.neck then
        
        c.neck.C0 = CFrame.new(o.neck.Position) * CFrame.Angles(0, sm.hy, 0)
            * CFrame.Angles(sm.hp - sm.pitch * 0.5, 0, -sm.roll * 0.5) * o.neck.Rotation
    end

    
    if not anyOn then
        local m = math.abs(sm.p) + math.abs(sm.pitch) + math.abs(sm.roll) + math.abs(sm.hy) + math.abs(sm.hp) + math.abs(sm.br) + math.abs(RL.landPos)
        for _, L in pairs(c.legs) do m += L.w end
        m += RL.bob.Magnitude
        if m < 0.002 then RL.restore(c); RL.clean = true end
    end
end

UI.conns[#UI.conns + 1] = RunService.RenderStepped:Connect(function(dt)
    local ok, err = pcall(RL.update, dt)
    if not ok and not RL.warned then RL.warned = true; warn(OBF("\181\161\174\155\122\159\199\201\206\191\162\207\188\183\122\204\191\187\198\195\205\199\201\148\122") .. tostring(err)) end
end)







local FP_HIDE = { Hat = true, Hair = true, Face = true, Neck = true, Eyebrow = true, Eyelash = true }
local FP_OUT_DIST = 9 

function FP.setZoom(lo, hi)
    pcall(function() LP.CameraMinZoomDistance = lo; LP.CameraMaxZoomDistance = hi end)
end


function FP.applyOffset()
    local _, hum = E.parts()
    if not hum then return end
    local base = (RL.c and RL.c.camBase) or FP.base0 or Vector3.zero
    pcall(function() hum.CameraOffset = base + FP.off + SH.off + RL.bob end)
end

function FP.rebuild()
    FP.body, FP.hide = {}, {}
    local c = LP.Character
    if not c then FP.head, FP.neck = nil, nil; return end
    FP.head = c:FindFirstChild(OBF("\162\191\187\190"))
    local nk = FP.head and FP.head:FindFirstChild(OBF("\168\191\189\197")) 
    if not nk then local tor = c:FindFirstChild(OBF("\174\201\204\205\201")); nk = tor and tor:FindFirstChild(OBF("\168\191\189\197")) end 
    FP.neck = (nk and nk:IsA(OBF("\167\201\206\201\204\144\158"))) and nk or nil
    for _, d in ipairs(c:GetDescendants()) do
        if d:IsA(OBF("\156\187\205\191\170\187\204\206")) and d.Name ~= OBF("\162\207\199\187\200\201\195\190\172\201\201\206\170\187\204\206") then
            local acc = d:FindFirstAncestorOfClass(OBF("\155\189\189\191\205\205\201\204\211"))
            local hide = false
            if acc then
                local ok, tp = pcall(function() return acc.AccessoryType.Name end)
                hide = ok and FP_HIDE[tp] == true
            else
                hide = (d.Name == OBF("\162\191\187\190") and d.Parent == c)
            end
            local list = hide and FP.hide or FP.body
            list[#list + 1] = d
        end
    end
end

function FP.hook(char)
    if FP.dconn then pcall(function() FP.dconn:Disconnect() end); FP.dconn = nil end
    FP.dirty = true
    if char then FP.dconn = char.DescendantAdded:Connect(function() FP.dirty = true end) end
end


local function fpClearLocal()
    for _, list in ipairs({ FP.body, FP.hide }) do
        for _, p in ipairs(list) do if p.Parent then pcall(function() p.LocalTransparencyModifier = 0 end) end end
    end
end


function FP.dropNative()
    if FP.nativeCF then
        local cam = workspace.CurrentCamera
        if cam then pcall(function() cam.CFrame = FP.nativeCF end) end
    end
    FP.nativeCF = nil
    FP.bob, FP.roll, FP.ph = Vector3.zero, 0, 0
end

function FP.restoreZoom()
    if FP.zmin then FP.setZoom(FP.zmin, FP.zmax) end
end


function FP.pullOut(keep)
    FP.tok += 1
    local my = FP.tok
    local lo, hi = FP.zmin or 0.5, FP.zmax or 128
    local d = math.clamp(FP_OUT_DIST, lo, hi)
    FP.setZoom(d, d)
    task.delay(0.3, function()
        if FP.tok ~= my then return end 
        FP.setZoom(lo, hi)
        if not keep then FP.zmin, FP.zmax = nil, nil end
    end)
end

function FP.goFirst()
    FP.tok += 1
    FP.first = true
    FP.rebuild(); FP.dirty = false
    FP.setZoom(0.5, 0.5)
    local cam = workspace.CurrentCamera
    if cam and not FP.fov0 then FP.fov0 = SH.fov0 or cam.FieldOfView end
    FP.off = Vector3.new(0, 0, -S.fp.depth)
    FP.applyOffset()
end

function FP.goOut(keep)
    FP.first = false
    FP.dropNative()
    fpClearLocal()
    local cam = workspace.CurrentCamera
    if cam and FP.fov0 then cam.FieldOfView = FP.fov0 end
    FP.fov0 = nil
    FP.off = Vector3.zero
    FP.applyOffset()
    FP.pullOut(keep)
end

function FP.sync()
    local F = S.fp
    if F.on and not FP.begun then
        FP.begun = true
        if not FP.zmin then FP.zmin, FP.zmax = LP.CameraMinZoomDistance, LP.CameraMaxZoomDistance end
        FP.hook(LP.Character)
        local _, hum = E.parts()
        FP.base0 = hum and hum.CameraOffset or Vector3.zero
    elseif not F.on and FP.begun then
        FP.begun = false
        if FP.first then FP.goOut(false) else FP.restoreZoom(); FP.zmin, FP.zmax = nil, nil end
        FP.hook(nil)
        return
    end
    if not FP.begun then return end
    local want = not (F.emoteOut and E.track ~= nil)
    if want and not FP.first then FP.goFirst()
    elseif (not want) and FP.first then FP.goOut(true) end
    if FP.first and (LP.CameraMinZoomDistance ~= 0.5 or LP.CameraMaxZoomDistance ~= 0.5) then FP.setZoom(0.5, 0.5) end
end

function FP.toggle()
    S.fp.on = not S.fp.on; save(); FP.sync()
    for _, p in ipairs(UI.paints) do pcall(p) end 
    notify(OBF("\170\204\195\199\191\195\204\187\122\202\191\205\205\201\187"), S.fp.on and OBF("\198\195\193\187\190\187") or OBF("\190\191\205\198\195\193\187\190\187"))
end


function SH.zoom(d)
    if FP.first then return end
    SH.tok = (SH.tok or 0) + 1
    local my = SH.tok
    local lo = SH.lo or FP.zmin or LP.CameraMinZoomDistance
    local hi = SH.hi or FP.zmax or LP.CameraMaxZoomDistance
    SH.lo, SH.hi = lo, hi
    d = math.clamp(d, lo, hi)
    FP.setZoom(d, d)
    task.delay(0.3, function()
        if SH.tok ~= my then return end
        if not FP.first then FP.setZoom(lo, hi) end
        SH.lo, SH.hi = nil, nil
    end)
end

function SH.sync()
    local F = S.sh
    local want = F.on and not FP.first
    local target = want and Vector3.new(F.side * F.x, F.y, 0) or Vector3.zero
    if target ~= SH.off then SH.off = target; FP.applyOffset() end
    if want and not SH.active then SH.active = true; SH.zoom(F.dist)
    elseif not want and SH.active then SH.active = false end
end

function FP.charAdded(char, hum)
    if FP.first then FP.dropNative(); FP.first = false; FP.off = Vector3.zero end 
    FP.body, FP.hide = {}, {}
    FP.base0 = hum and hum.CameraOffset or Vector3.zero
    if FP.begun then FP.hook(char) end
end




local function camPre()
    if not FP.nativeCF then return end
    local cam = workspace.CurrentCamera
    if cam then cam.CFrame = FP.nativeCF end
end

local function camStep(dt)
    local cam = workspace.CurrentCamera
    if not cam then return end
    local R = E.perf and RL.perfR or S.real
    local F = S.fp

    
    if S.sh.on and S.sh.fovOn and not FP.first then
        if not SH.fov0 then SH.fov0 = cam.FieldOfView end
        if cam.FieldOfView ~= S.sh.fov then cam.FieldOfView = S.sh.fov end
    elseif SH.fov0 then
        cam.FieldOfView = SH.fov0; SH.fov0 = nil
    end

    CAMFX.t += dt
    CAMFX.amp *= math.exp(-dt * 5)
    if CAMFX.amp < 0.003 then CAMFX.amp = 0 end

    local c = LP.Character
    local root = c and c:FindFirstChild(OBF("\162\207\199\187\200\201\195\190\172\201\201\206\170\187\204\206"))
    local hum = c and c:FindFirstChildOfClass(OBF("\162\207\199\187\200\201\195\190"))
    local wantLean = (root ~= nil) and R.camLean
    if not (FP.first or wantLean or CAMFX.amp > 0 or math.abs(CAMFX.roll) > 1e-3) then
        FP.dropNative()
        return
    end

    if FP.first then
        if FP.dirty then FP.dirty = false; FP.rebuild() end
        
        local hv, bv = F.hideHead and 1 or 0, F.body and 0 or 1
        for _, p in ipairs(FP.hide) do if p.Parent then p.LocalTransparencyModifier = hv end end
        for _, p in ipairs(FP.body) do if p.Parent then p.LocalTransparencyModifier = bv end end
        if cam.FieldOfView ~= F.fov then cam.FieldOfView = F.fov end
    end
    if not (root and hum) then FP.nativeCF = nil; return end

    FP.nativeCF = cam.CFrame
    local rot, pos = FP.nativeCF.Rotation, FP.nativeCF.Position
    local a = 1 - math.exp(-dt * 10)
    local vel = root.AssemblyLinearVelocity
    local planar = Vector3.new(vel.X, 0, vel.Z)
    local speed = planar.Magnitude

    if FP.first then
        local head = FP.head
        if F.follow and head and head.Parent then
            
            pos = head.CFrame:PointToWorldSpace(Vector3.new(0, 0.1, -F.depth))
            
            local nk = FP.neck
            if nk and nk.Part0 and F.followAmt > 0 then
                local base = (nk.Part0.CFrame * nk.C0).Rotation
                local d = base * nk.Transform.Rotation * base:Inverse()
                rot = CFrame.new():Lerp(d, F.followAmt) * rot
            end
            
            local sm = RL.sm
            rot = CFrame.Angles(0, sm.hy * F.followAmt, 0) * rot * CFrame.Angles(sm.hp * F.followAmt, 0, 0)
        end
        
        local k = F.motion
        local bobT, rollT = Vector3.zero, 0
        if k > 0 and (F.follow or not R.camBob) then
            if hum.FloorMaterial ~= Enum.Material.Air and speed > 2 then
                FP.ph += dt * speed * 0.6
                local kk = math.clamp(speed / 16, 0.3, 1.6) * k
                bobT = Vector3.new(math.cos(FP.ph) * 0.04 * kk, (math.abs(math.sin(FP.ph)) - 0.5) * 0.1 * kk, 0)
            end
            rollT = -math.clamp(root.CFrame.RightVector:Dot(planar) / 16, -1.5, 1.5) * 0.04 * k
        end
        FP.bob = FP.bob:Lerp(bobT, a)
        FP.roll += (rollT - FP.roll) * a
    else
        FP.bob, FP.roll = Vector3.zero, 0
    end

    
    local rollC = 0
    if wantLean then
        rollC = math.clamp(root.AssemblyAngularVelocity.Y * 0.04, -0.14, 0.14) * math.clamp(speed / 16, 0, 1.2) * R.leanAmt
    end
    CAMFX.roll += (rollC - CAMFX.roll) * (1 - math.exp(-dt * 6))

    
    local sp, sy, sr, jit = 0, 0, 0, 0
    if CAMFX.amp > 0 then
        local t, k = CAMFX.t, CAMFX.amp
        sp = math.sin(t * 52) * k * 0.03
        sy = math.sin(t * 43 + 1.3) * k * 0.02
        sr = math.sin(t * 37 + 2.1) * k * 0.025
        jit = (math.sin(t * 58) * 0.04 - 0.22) * k
    end
    local camRot = rot * CFrame.Angles(sp, sy, (FP.first and FP.roll or 0) + CAMFX.roll + sr)
    cam.CFrame = CFrame.new(pos + Vector3.new(0, jit, 0) + camRot:VectorToWorldSpace(FP.bob)) * camRot
end
pcall(function() RunService:BindToRenderStep(OBF("\159\162\185\160\170\185\170\172\159"), Enum.RenderPriority.Camera.Value - 1, camPre) end)
pcall(function() RunService:BindToRenderStep(OBF("\159\162\185\160\170"), Enum.RenderPriority.Camera.Value + 1, camStep) end)

function FP.shutdown() 
    if FP.begun then
        FP.begun = false
        if FP.first then FP.goOut(false) else FP.restoreZoom() end
    end
    pcall(function() RunService:UnbindFromRenderStep(OBF("\159\162\185\160\170")) end)
    pcall(function() RunService:UnbindFromRenderStep(OBF("\159\162\185\160\170\185\170\172\159")) end)
    if FP.dconn then pcall(function() FP.dconn:Disconnect() end) end
end

