end)




local EV = { last = {}, any = 0, fall = 0, runT = 0, conns = {}, hp = 100, lowHp = false }

function EV.unhook()
    for _, cn in ipairs(EV.conns) do pcall(function() cn:Disconnect() end) end
    EV.conns = {}
end

local function evFire(key)
    local cfg = S.ev[key]
    if not cfg or not cfg.on then return end
    local now = os.clock()
    if now - (EV.last[key] or 0) < S.evCd or now - EV.any < 0.8 then return end
    local _, hum = E.parts()
    if not hum or hum.Health <= 0 or E.track ~= nil then return end 
    local id = cfg.emote
    if id == 0 then
        local pool = E.pool()
        id = pool[math.random(math.max(#pool, 1))]
    end
    if not id then return end
    EV.last[key], EV.any = now, now
    task.spawn(E.play, id, true)
end

function EV.hook(char, hum)
    EV.unhook()
    EV.fall, EV.runT, EV.lowHp, EV.hp = 0, 0, false, hum.Health
    local function add(cn) EV.conns[#EV.conns + 1] = cn end
    add(hum.StateChanged:Connect(function(old, new)
        local T = Enum.HumanoidStateType
        if new == T.Jumping then evFire(OBF("\196\207\199\202"))
        elseif new == T.Landed then
            local f = EV.fall; EV.fall = 0
            if f >= S.evLandMin then evFire(OBF("\198\187\200\190")) end
        elseif new == T.Swimming then evFire(OBF("\205\209\195\199"))
        elseif old == T.Swimming then evFire(OBF("\205\209\195\199\159\200\190")) end
    end))
    add(hum:GetPropertyChangedSignal(OBF("\173\195\206")):Connect(function() evFire(hum.Sit and OBF("\205\195\206") or OBF("\205\206\187\200\190")) end))
    add(char.ChildAdded:Connect(function(ch) if ch:IsA(OBF("\174\201\201\198")) then evFire(OBF("\191\203\207\195\202")) end end))
    add(char.ChildRemoved:Connect(function(ch) if ch:IsA(OBF("\174\201\201\198")) then evFire(OBF("\207\200\191\203\207\195\202")) end end))
    add(hum.HealthChanged:Connect(function(h)
        if h < EV.hp - 0.5 and h > 0 then evFire(OBF("\194\207\204\206")) end
        local frac = h / math.max(hum.MaxHealth, 1)
        if frac < 0.3 and h > 0 and not EV.lowHp then EV.lowHp = true; evFire(OBF("\198\201\209"))
        elseif frac > 0.5 then EV.lowHp = false end
        EV.hp = h
    end))
end


UI.conns[#UI.conns + 1] = RunService.Heartbeat:Connect(function(dt)
    local _, hum = E.parts()
    local root = hum and hum.RootPart
    if not root then return end
    local v = root.AssemblyLinearVelocity
    local sp = Vector3.new(v.X, 0, v.Z).Magnitude
    if hum:GetState() == Enum.HumanoidStateType.Freefall then EV.fall = math.max(EV.fall, -v.Y) end
    if sp >= S.evRunMin then EV.runT += dt
    elseif sp < 1.5 then
        if EV.runT >= 0.5 then evFire(OBF("\205\206\201\202\172\207\200")) end
        EV.runT = 0
    end
end)




