local function readPing()
    local ok, v = pcall(function() return Stats.Network.ServerStatsItem[OBF("\158\187\206\187\122\170\195\200\193")]:GetValue() end)
    if ok and type(v) == OBF("\200\207\199\188\191\204") then return v end
    local ok2, v2 = pcall(function() return LP:GetNetworkPing() * 1000 end)
    return ok2 and v2 or 0
end

function PF.tick()
    local fps = PF.fps
    if S.hud and hudBtn.Visible then
        hudBtn.Text = (OBF("\127\190\122\160\170\173\122\28\17\122\127\190\122\199\205\127\205")):format(math.floor(fps + 0.5), math.floor(readPing() + 0.5), E.perf and OBF("\122\60\244\251") or "")
        hudBtn.TextColor3 = fps >= 50 and Color3.fromRGB(110, 255, 150) or (fps >= 30 and Color3.fromRGB(255, 220, 90) or Color3.fromRGB(255, 90, 90))
    end
    if not S.perf.on then
        if E.perf then E.perf = false; E.fxApply() end
        PF.low, PF.high = 0, 0
        return
    end
    if os.clock() - PF.t0 < 8 then return end 
    local mn = S.perf.min
    if fps < mn then PF.low += 0.5; PF.high = 0
    elseif fps > mn + 15 then PF.high += 0.5; PF.low = 0
    else PF.low = math.max(PF.low - 0.25, 0) end
    if not E.perf and PF.low >= 4 then
        E.perf = true; PF.low = 0; E.fxApply()
        notify(OBF("\167\201\190\201\122\202\191\204\192\201\204\199\187\200\189\191"), OBF("\160\170\173\122\188\187\195\210\201\148\122\191\192\191\195\206\201\205\122\202\187\207\205\187\190\201\205"))
    elseif E.perf and PF.high >= 20 then
        E.perf = false; PF.high = 0; E.fxApply()
        notify(OBF("\167\201\190\201\122\202\191\204\192\201\204\199\187\200\189\191"), OBF("\160\170\173\122\201\197\148\122\191\192\191\195\206\201\205\122\190\191\122\208\201\198\206\187"))
    end
end
