local function onChar(char)
    E.track = nil; E.orig = {}
    local hum = char:WaitForChild(OBF("\162\207\199\187\200\201\195\190"), 10)
    if not hum then return end
    hum:WaitForChild(OBF("\155\200\195\199\187\206\201\204"), 10)
    if hum.RigType == Enum.HumanoidRigType.R15 then 
        for _, n in ipairs({ OBF("\175\202\202\191\204\174\201\204\205\201"), OBF("\166\201\209\191\204\174\201\204\205\201"), OBF("\162\191\187\190"), OBF("\166\191\192\206\160\201\201\206"), OBF("\172\195\193\194\206\160\201\201\206"), OBF("\166\191\192\206\166\201\209\191\204\166\191\193"), OBF("\172\195\193\194\206\166\201\209\191\204\166\191\193") }) do char:WaitForChild(n, 5) end
        RL.setup(char)
    else
        char:WaitForChild(OBF("\174\201\204\205\201"), 5) 
        RL.setup(char)
    end
    FP.charAdded(char, hum)
    EV.hook(char, hum)
    if S.pack ~= OBF("\200\201\200\191") then task.delay(0.6, function() E.applyPack(char, true) end) end
    if #S.wheel > 0 then task.delay(2, WH.inject) end
    if S.fx.particles or S.fx.aura or S.fx.trail then task.delay(1, E.fxApply) end
    local firstChar = not E.charSeen
    E.charSeen = true
    if S.spawn.on and (not firstChar or S.spawn.join) then
        task.delay(S.spawn.delay, function()
            if char ~= LP.Character or E.track ~= nil then return end
            local id = S.spawn.emote
            if id == 0 then local pool = E.pool(); id = pool[math.random(math.max(#pool, 1))] end
            if id then E.play(id, true) end
        end)
    elseif S.autoReload and S.lastEmote ~= 0 then
        task.delay(1.2, function() E.play(S.lastEmote) end)
    end
end
