    local function hideFromOthers(label, getFolder, isMine)
        local backup = {}
        PR:AddToggle({Name = label, Default = false, Callback = switch(0.1, function()
            local f = getFolder()
            if not f then return end
            for _, item in ipairs(f:GetChildren()) do
                if not isMine(item) then
                    local okc, clone = pcall(function() return item:Clone() end)
                    if okc and clone then backup[#backup + 1] = {inst = clone, parent = f} end
                    item:Destroy()
                end
            end
        end, function()
            for _, b in ipairs(backup) do
                if b.parent and b.parent.Parent then pcall(function() b.inst.Parent = b.parent end) end
            end
            backup = {}
        end)})
    end
