    local muted, soundConn, somStop = {}, nil, nil
    local function muteSound(s)
        if not s:IsA(OBF("\173\201\207\200\190")) then return end
        if LP.Character and s:IsDescendantOf(LP.Character) then return end
        if s.Volume > 0 then
            if muted[s] == nil then muted[s] = s.Volume end
            s.Volume = 0
        end
    end
    local function sweepSounds()
        for _, o in ipairs(WS:GetDescendants()) do muteSound(o) end
    end
    SU:AddToggle({Name = OBF("\155\200\206\195\122\173\201\199\122\130\205\195\198\191\200\189\195\187\122\201\205\122\205\201\200\205\122\190\201\122\199\187\202\187\122\191\122\190\201\205\122\201\207\206\204\201\205\131"), Default = false, Callback = function(v)
        if somStop then somStop() somStop = nil end
        if soundConn then soundConn:Disconnect() soundConn = nil end
        if v then
            soundConn = WS.DescendantAdded:Connect(function(o) task.defer(muteSound, o) end)
            somStop = runLoop(1, sweepSounds)
        else
            for s, vol in pairs(muted) do
                if s.Parent then pcall(function() s.Volume = vol end) end
            end
            muted = {}
        end
    end})

    local droneGui
    local function openDrone()
        if droneGui and droneGui.Parent then return end
        local CAS = game:GetService(OBF("\157\201\200\206\191\210\206\155\189\206\195\201\200\173\191\204\208\195\189\191"))
        local cam = WS.CurrentCamera
        local STEP, ACTION = OBF("\161\174\155\185\158\204\201\200\191"), OBF("\161\174\155\185\158\204\201\200\191\173\195\200\197")
        local active, smooth = false, false
        local speed, fov = 50, 70
        local yaw, pitch = 0, 0
        local camCF
        local vel = Vector3.zero
        local pad = {F = false, B = false, L = false, R = false, U = false, D = false}
        local saved, rotTouch, rmb, dragIn, dragStart, dragPos = nil, nil, false, nil, nil, nil
        local conns = {}

        local function mk(class, props, parent)
            local o = Instance.new(class)
            for k, val in pairs(props) do o[k] = val end
            o.Parent = parent
            return o
        end
        local gp = nil
        local okg, g = pcall(function() return gethui() end)
        if okg and typeof(g) == OBF("\163\200\205\206\187\200\189\191") then gp = g else gp = game:GetService(OBF("\157\201\204\191\161\207\195")) end
        local gui = mk(OBF("\173\189\204\191\191\200\161\207\195"), {Name = OBF("\161\174\155\185\158\204\201\200\191"), ResetOnSpawn = false, DisplayOrder = 900, IgnoreGuiInset = true}, nil)
        if not pcall(function() gui.Parent = gp end) or not gui.Parent then gui.Parent = LP:WaitForChild(OBF("\170\198\187\211\191\204\161\207\195")) end
        droneGui = gui

        local BG, FG = Color3.fromRGB(14, 14, 18), Color3.fromRGB(255, 60, 60)
        local win = mk(OBF("\160\204\187\199\191"), {Size = UDim2.new(0, 240, 0, 214), Position = UDim2.new(0.5, -120, 0.12, 0), BackgroundColor3 = BG, BorderSizePixel = 0}, gui)
        mk(OBF("\175\163\157\201\204\200\191\204"), {CornerRadius = UDim.new(0, 8)}, win)
        mk(OBF("\175\163\173\206\204\201\197\191"), {Color = FG, Thickness = 1.5}, win)
        local title = mk(OBF("\174\191\210\206\166\187\188\191\198"), {Size = UDim2.new(1, -64, 0, 28), Position = UDim2.new(0, 8, 0, 0), BackgroundTransparency = 1, Text = OBF("\158\204\201\200\191\122\161\174\155"), TextColor3 = Color3.new(1, 1, 1), Font = Enum.Font.GothamBold, TextSize = 14, TextXAlignment = Enum.TextXAlignment.Left}, win)
        local function btn(text, x, y, w, h, parent)
            return mk(OBF("\174\191\210\206\156\207\206\206\201\200"), {Text = text, Size = UDim2.new(0, w, 0, h), Position = UDim2.new(0, x, 0, y), BackgroundColor3 = Color3.fromRGB(34, 34, 42), TextColor3 = Color3.new(1, 1, 1), Font = Enum.Font.GothamBold, TextSize = 13, BorderSizePixel = 0, AutoButtonColor = true}, parent)
        end
        local bMin, bClose = btn(OBF("\135"), 178, 3, 26, 22, win), btn(OBF("\178"), 208, 3, 26, 22, win)
        local body = mk(OBF("\160\204\187\199\191"), {Size = UDim2.new(1, 0, 1, -30), Position = UDim2.new(0, 0, 0, 30), BackgroundTransparency = 1}, win)
        local bStart = btn(OBF("\157\201\199\191\29\1\187\204"), 10, 4, 220, 32, body)
        local function label(text, y) return mk(OBF("\174\191\210\206\166\187\188\191\198"), {Size = UDim2.new(0, 70, 0, 28), Position = UDim2.new(0, 10, 0, y), BackgroundTransparency = 1, Text = text, TextColor3 = Color3.fromRGB(200, 200, 210), Font = Enum.Font.Gotham, TextSize = 12, TextXAlignment = Enum.TextXAlignment.Left}, body) end
        label(OBF("\176\191\198\201\189\195\190\187\190\191"), 44)
        local bSm, tSpeed, bSp = btn(OBF("\135"), 86, 46, 28, 26, body), mk(OBF("\174\191\210\206\156\201\210"), {Text = tostring(speed), Size = UDim2.new(0, 70, 0, 26), Position = UDim2.new(0, 118, 0, 46), BackgroundColor3 = Color3.fromRGB(24, 24, 30), TextColor3 = Color3.new(1, 1, 1), Font = Enum.Font.Gotham, TextSize = 13, BorderSizePixel = 0, ClearTextOnFocus = false}, body), btn(OBF("\133"), 192, 46, 28, 26, body)
        label(OBF("\160\169\176"), 78)
        local bFm, tFov, bFp = btn(OBF("\135"), 86, 80, 28, 26, body), mk(OBF("\174\191\210\206\156\201\210"), {Text = tostring(fov), Size = UDim2.new(0, 70, 0, 26), Position = UDim2.new(0, 118, 0, 80), BackgroundColor3 = Color3.fromRGB(24, 24, 30), TextColor3 = Color3.new(1, 1, 1), Font = Enum.Font.Gotham, TextSize = 13, BorderSizePixel = 0, ClearTextOnFocus = false}, body), btn(OBF("\133"), 192, 80, 28, 26, body)
        local bSmooth = btn(OBF("\173\207\187\208\191\148\122\190\191\205\198\195\193\187\190\201"), 10, 114, 220, 28, body)
        mk(OBF("\174\191\210\206\166\187\188\191\198"), {Size = UDim2.new(1, -20, 0, 30), Position = UDim2.new(0, 10, 0, 144), BackgroundTransparency = 1, Text = OBF("\170\157\148\122\177\155\173\158\134\122\159\205\202\187\29\1\201\122\205\201\188\191\134\122\173\194\195\192\206\122\190\191\205\189\191\134\122\188\201\206\29\253\201\122\190\195\204\191\195\206\201\122\193\195\204\187\136\122\157\191\198\207\198\187\204\148\122\205\191\206\187\205\122\191\122\187\204\204\187\205\206\187\204\122\187\122\199\191\206\187\190\191\122\190\195\204\191\195\206\187\136"), TextColor3 = Color3.fromRGB(150, 150, 160), Font = Enum.Font.Gotham, TextSize = 10, TextWrapped = true, TextXAlignment = Enum.TextXAlignment.Left}, body)

        local padFrame = mk(OBF("\160\204\187\199\191"), {Size = UDim2.new(0, 230, 0, 112), Position = UDim2.new(0, 14, 1, -126), BackgroundTransparency = 1, Visible = false}, gui)
        local function hold(text, x, y, key)
            local b = mk(OBF("\174\191\210\206\156\207\206\206\201\200"), {Text = text, Size = UDim2.new(0, 52, 0, 52), Position = UDim2.new(0, x, 0, y), BackgroundColor3 = BG, BackgroundTransparency = 0.25, TextColor3 = Color3.new(1, 1, 1), Font = Enum.Font.GothamBold, TextSize = 20, BorderSizePixel = 0, AutoButtonColor = false}, padFrame)
            mk(OBF("\175\163\157\201\204\200\191\204"), {CornerRadius = UDim.new(0, 8)}, b)
            b.InputBegan:Connect(function(i) if i.UserInputType == Enum.UserInputType.Touch or i.UserInputType == Enum.UserInputType.MouseButton1 then pad[key] = true end end)
            b.InputEnded:Connect(function(i) if i.UserInputType == Enum.UserInputType.Touch or i.UserInputType == Enum.UserInputType.MouseButton1 then pad[key] = false end end)
        end
        hold(OBF("\60\240\12"), 56, 0, OBF("\160")) hold(OBF("\60\241\218"), 0, 56, OBF("\166")) hold(OBF("\60\240\22"), 56, 56, OBF("\156")) hold(OBF("\60\240\16"), 112, 56, OBF("\172"))
        hold(OBF("\60\6\224"), 176, 0, OBF("\175")) hold(OBF("\60\6\225"), 176, 56, OBF("\158"))

        local function setSpeed(n) speed = math.clamp(math.floor(tonumber(n) or speed), 1, 1000) tSpeed.Text = tostring(speed) end
        local function setFov(n) fov = math.clamp(math.floor(tonumber(n) or fov), 10, 120) tFov.Text = tostring(fov) end  
        tSpeed.FocusLost:Connect(function() setSpeed(tSpeed.Text) end)
        tFov.FocusLost:Connect(function() setFov(tFov.Text) end)
        bSm.Activated:Connect(function() setSpeed(speed - 10) end)
        bSp.Activated:Connect(function() setSpeed(speed + 10) end)
        bFm.Activated:Connect(function() setFov(fov - 5) end)
        bFp.Activated:Connect(function() setFov(fov + 5) end)
        bSmooth.Activated:Connect(function()
            smooth = not smooth
            bSmooth.Text = smooth and OBF("\173\207\187\208\191\148\122\198\195\193\187\190\201") or OBF("\173\207\187\208\191\148\122\190\191\205\198\195\193\187\190\201")
        end)

        local function controls(on)
            pcall(function()
                local pm = LP:FindFirstChild(OBF("\170\198\187\211\191\204\173\189\204\195\202\206\205")) and LP.PlayerScripts:FindFirstChild(OBF("\170\198\187\211\191\204\167\201\190\207\198\191"))
                if not pm then return end
                local c = require(pm):GetControls()
                if on then c:Enable() else c:Disable() end
            end)
        end
        local function update(dt)
            if not active then return end
            cam = WS.CurrentCamera
            local mv = Vector3.zero
            if not UIS:GetFocusedTextBox() then
                if UIS:IsKeyDown(Enum.KeyCode.W) then mv = mv + Vector3.new(0, 0, -1) end
                if UIS:IsKeyDown(Enum.KeyCode.S) then mv = mv + Vector3.new(0, 0, 1) end
                if UIS:IsKeyDown(Enum.KeyCode.A) then mv = mv + Vector3.new(-1, 0, 0) end
                if UIS:IsKeyDown(Enum.KeyCode.D) then mv = mv + Vector3.new(1, 0, 0) end
                if UIS:IsKeyDown(Enum.KeyCode.Space) then mv = mv + Vector3.new(0, 1, 0) end
                if UIS:IsKeyDown(Enum.KeyCode.LeftShift) then mv = mv + Vector3.new(0, -1, 0) end
            end
            if pad.F then mv = mv + Vector3.new(0, 0, -1) end
            if pad.B then mv = mv + Vector3.new(0, 0, 1) end
            if pad.L then mv = mv + Vector3.new(-1, 0, 0) end
            if pad.R then mv = mv + Vector3.new(1, 0, 0) end
            if pad.U then mv = mv + Vector3.new(0, 1, 0) end
            if pad.D then mv = mv + Vector3.new(0, -1, 0) end
            local rot = CFrame.fromOrientation(pitch, yaw, 0)
            local dir = rot:VectorToWorldSpace(Vector3.new(mv.X, 0, mv.Z)) + Vector3.new(0, mv.Y, 0)
            if dir.Magnitude > 0 then dir = dir.Unit end
            local goal = dir * speed
            if smooth then vel = vel:Lerp(goal, 1 - math.exp(-8 * dt)) else vel = goal end
            camCF = CFrame.new(camCF.Position + vel * dt) * rot
            cam.CFrame = camCF
            cam.FieldOfView = fov
        end
        local function stop()
            if not active then return end
            active = false
            pcall(function() RunS:UnbindFromRenderStep(STEP) end)
            pcall(function() CAS:UnbindAction(ACTION) end)
            controls(true)
            if saved then
                cam.CameraType = saved.ct
                cam.CameraSubject = saved.subj
                cam.FieldOfView = saved.fov
                saved = nil
            end
            vel, rotTouch, rmb = Vector3.zero, nil, false
            for k in pairs(pad) do pad[k] = false end
            padFrame.Visible = false
            bStart.Text = OBF("\157\201\199\191\29\1\187\204")
        end
        local function start()
            if active then return end
            cam = WS.CurrentCamera
            saved = {ct = cam.CameraType, subj = cam.CameraSubject, fov = cam.FieldOfView}
            camCF = cam.CFrame
            pitch, yaw = camCF:ToOrientation()
            vel = Vector3.zero
            active = true
            cam.CameraType = Enum.CameraType.Scriptable
            controls(false)
            CAS:BindActionAtPriority(ACTION, function() return Enum.ContextActionResult.Sink end, false, 3000,
                Enum.KeyCode.W, Enum.KeyCode.A, Enum.KeyCode.S, Enum.KeyCode.D, Enum.KeyCode.Space, Enum.KeyCode.LeftShift)
            RunS:BindToRenderStep(STEP, Enum.RenderPriority.Camera.Value + 1, update)
            padFrame.Visible = true
            bStart.Text = OBF("\170\187\204\187\204")
        end
        bStart.Activated:Connect(function() if active then stop() else start() end end)

        local minimized = false
        bMin.Activated:Connect(function()
            minimized = not minimized
            body.Visible = not minimized
            win.Size = minimized and UDim2.new(0, 240, 0, 30) or UDim2.new(0, 240, 0, 214)
        end)
        local function close()
            stop()
            for _, c in ipairs(conns) do c:Disconnect() end
            conns = {}
            gui:Destroy()
            droneGui = nil
        end
        bClose.Activated:Connect(close)

        title.Active = true
        title.InputBegan:Connect(function(i)
            if i.UserInputType == Enum.UserInputType.MouseButton1 or i.UserInputType == Enum.UserInputType.Touch then
                dragIn, dragStart, dragPos = i, i.Position, win.Position
            end
        end)
        conns[#conns + 1] = UIS.InputBegan:Connect(function(i, processed)
            if i.UserInputType == Enum.UserInputType.MouseButton2 then rmb = true
            elseif i.UserInputType == Enum.UserInputType.Touch and active and not processed and not rotTouch and i.Position.X > cam.ViewportSize.X / 2 then
                rotTouch = i
            end
        end)
        conns[#conns + 1] = UIS.InputEnded:Connect(function(i)
            if i.UserInputType == Enum.UserInputType.MouseButton2 then rmb = false end
            if i == rotTouch then rotTouch = nil end
            if i == dragIn then dragIn = nil end
        end)
        conns[#conns + 1] = UIS.InputChanged:Connect(function(i)
            if dragIn and (i == dragIn or i.UserInputType == Enum.UserInputType.MouseMovement) then
                local d = i.Position - dragStart
                win.Position = UDim2.new(dragPos.X.Scale, dragPos.X.Offset + d.X, dragPos.Y.Scale, dragPos.Y.Offset + d.Y)
            end
            if not active then return end
            if i.UserInputType == Enum.UserInputType.MouseMovement and rmb then
                yaw = yaw - math.rad(i.Delta.X * 0.3)
                pitch = math.clamp(pitch - math.rad(i.Delta.Y * 0.3), -1.5, 1.5)
            elseif i == rotTouch then
                yaw = yaw - math.rad(i.Delta.X * 0.4)
                pitch = math.clamp(pitch - math.rad(i.Delta.Y * 0.4), -1.5, 1.5)
