        if typeof(p) ~= OBF("\163\200\205\206\187\200\189\191") or p == LP then return false end
        local ok1, res = pcall(function() return GTA_PL.canHit(p) end)
        return ok1 and res == true
    end
    local function hostileChars()  
        local set = {}
        for _, p in ipairs(Plrs:GetPlayers()) do
            if p == LP or not canHit(p) then
                if p.Character then set[p.Character] = true end
            end
        end
        return set
    end
    local function genLoop(getId, interval)  
        local gen = 0
        return function(v)
            gen = gen + 1
            if v then
                local mine = gen
                task.spawn(function()
                    while gen == mine do
                        pcall(getId)
                        task.wait(interval)
                    end
                end)
            end
        end
    end

