    local sg = Instance.new(OBF("\173\189\204\191\191\200\161\207\195")); sg.Name = OBF("\161\174\155\162\207\188\185\169\202\191\200\156\207\206\206\201\200"); sg.ResetOnSpawn = false; sg.DisplayOrder = 1000; sg.IgnoreGuiInset = true
    pcall(function() sg.Parent = parentGui end)
    local b = Instance.new(OBF("\174\191\210\206\156\207\206\206\201\200")); b.Name = OBF("\174\201\193\193\198\191"); b.Size = UDim2.new(0, 52, 0, 52); b.Position = UDim2.new(0, 14, 0.5, -26)
    b.BackgroundColor3 = Color3.fromRGB(8, 8, 10); b.BorderSizePixel = 0; b.Text = ""; b.TextColor3 = Color3.fromRGB(255, 60, 60)
    b.Font = Enum.Font.GothamBold; b.TextSize = 11; b.Parent = sg
    Instance.new(OBF("\175\163\157\201\204\200\191\204"), b).CornerRadius = UDim.new(1, 0)
    local st = Instance.new(OBF("\175\163\173\206\204\201\197\191"), b); st.Color = Color3.fromRGB(255, 60, 60); st.Thickness = 2
    local sharBox = GTA_MakeSharingan(b); sharBox.Size = UDim2.new(1, -6, 1, -6)
    local function refresh()
        local g = Hub.MainGui
        local open = (g and g.Enabled) and true or false
        st.Color = open and Color3.fromRGB(255, 60, 60) or Color3.fromRGB(110, 110, 120)
        sharBox.Rotation = open and 0 or 45
    end
    local dragging, dragStart, startPos, moved
    b.InputBegan:Connect(function(i)
        if i.UserInputType == Enum.UserInputType.MouseButton1 or i.UserInputType == Enum.UserInputType.Touch then
            dragging = true; moved = false; dragStart = i.Position; startPos = b.Position
        end
    end)
    UserInputService.InputChanged:Connect(function(i)
        if dragging and (i.UserInputType == Enum.UserInputType.MouseMovement or i.UserInputType == Enum.UserInputType.Touch) then
            local d = i.Position - dragStart
            if d.Magnitude > 6 then moved = true end
            if moved then b.Position = UDim2.new(startPos.X.Scale, startPos.X.Offset + d.X, startPos.Y.Scale, startPos.Y.Offset + d.Y) end
        end
    end)
    UserInputService.InputEnded:Connect(function(i)
        if dragging and (i.UserInputType == Enum.UserInputType.MouseButton1 or i.UserInputType == Enum.UserInputType.Touch) then
            dragging = false
            if not moved then
                local g = Hub.MainGui or resolveMainGui()
                if g then g.Enabled = not g.Enabled end
                refresh()
            end
        end
    end)
    task.defer(refresh)
end
